- ਉਸ ਨੇ ਕਿਹਾ: "ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਅੱਲਾਹ ਦੀ ਬੰਦਗੀ ਕਰੋ, ਉਸ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡਾ ਕੋਈ ਪੂਜਣਯੋਗ ਨਹੀਂ, ਕੀ ਤੁਸੀਂ ਡਰਦੇ ਨਹੀਂ?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- ਨਾ ਉਨ੍ਹਾਂ ਦਾ ਧਨ ਅਤੇ ਨਾ ਉਨ੍ਹਾਂ ਦੀ ਔਲਾਦ ਅੱਲਾਹ ਦੇ ਸਾਹਮਣੇ ਉਨ੍ਹਾਂ ਦੇ ਕਿਸੇ ਕੰਮ ਆਵੇਗੀ, ਅਤੇ ਇਹੀ ਲੋਕ ਹਨ। (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- ਬਾਗ ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠਾਂ ਨਹਿਰਾਂ ਵਹਿ ਰਹੀਆਂ ਹਨ, ਉਨ੍ਹਾਂ ਵਿੱਚ ਉਹ ਸਦਾ ਰਹਿਣਗੇ, ਅਤੇ ਇਹੀ ਵੱਡੀ ਸਫਲਤਾ ਹੈ। (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- ਕੀ ਉਨ੍ਹਾਂ ਤੋਂ ਪਹਿਲਾਂ ਵਾਲਿਆਂ ਦੀ ਖਬਰ, ਨੂਹ, ਆਦ ਅਤੇ ਸਮੂਦ ਦੀਆਂ ਕੌਮਾਂ ਦੀ, ਉਨ੍ਹਾਂ ਕੋਲ ਨਹੀਂ ਆਈ? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- ਅੱਲਾਹ ਦੇ ਰਾਹ ਵਿੱਚ ਮੇਰੇ ਮਦਦਗਾਰ ਕੌਣ ਹਨ? ਹਵਾਰੀਆਂ (ਸ਼ਗਿਰਦਾਂ) ਨੇ ਕਿਹਾ: "ਅਸੀਂ ਅੱਲਾਹ ਦੇ ਮਦਦਗਾਰ ਹਾਂ, ਅਸੀਂ ਈਮਾਨ ਲਿਆਏ ਹਾਂ।" (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- ਤੇਰਾ ਰੱਬ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਕਿ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਕੌਣ ਭਟਕਿਆ, ਅਤੇ ਉਹ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਰਾਹ ਪਾਉਣ ਵਾਲਿਆਂ ਨੂੰ। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- ਇਹ ਇਸ ਲਈ ਹੈ ਕਿ ਅੱਲਾਹ ਹੀ ਸੱਚ ਹੈ, ਅਤੇ ਉਹ ਜਿਸ ਨੂੰ ਉਸ ਤੋਂ ਬਿਨਾਂ ਪੁਕਾਰਦੇ ਹਨ ਉਹ ਬਾਤਿਲ ਹੈ। (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- ਅਤੇ ਜੋ ਕੋਈ ਅੱਲਾਹ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ ਦੀ ਆਗਿਆ ਦੀ ਪਾਲਣਾ ਕਰਦਾ ਹੈ, ਅੱਲਾਹ ਉਸ ਨੂੰ ਉਨ੍ਹਾਂ ਬਾਗਾਂ ਵਿੱਚ ਪਾਵੇਗਾ ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠਾਂ ਨਹਿਰਾਂ ਵਹਿ ਰਹੀਆਂ ਹਨ। (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- ਉਸ ਨੇ ਤੁਹਾਡੇ ਉੱਤੇ ਸਿਰਫ਼ ਮੁਰਦਾਰ, ਖੂਨ, ਸੂਰ ਦਾ ਮਾਸ ਅਤੇ ਉਹ ਜੋ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਕਿਸੇ ਹੋਰ ਦੇ ਨਾਮ ਉੱਤੇ ਜ਼ਿਬ੍ਹਾ ਕੀਤਾ ਜਾਵੇ, ਹਰਾਮ ਕੀਤਾ ਹੈ। (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- ਕਿ ਤੁਸੀਂ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਕਿਸੇ ਦੀ ਬੰਦਗੀ ਨਾ ਕਰੋ; ਬੇਸ਼ੱਕ, ਮੈਂ ਤੁਹਾਡੇ ਉੱਤੇ ਵੱਡੇ ਦਿਨ ਦੇ ਅਜ਼ਾਬ ਤੋਂ ਡਰਦਾ ਹਾਂ। (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- ਇਹ ਗ਼ੈਬ ਦੀਆਂ ਖਬਰਾਂ ਵਿੱਚੋਂ ਹੈ ਜਿਸ ਨੂੰ ਅਸੀਂ ਤੁਹਾਡੇ ਵੱਲ ਵਹੀ ਕਰ ਰਹੇ ਹਾਂ; ਜਦੋਂ ਉਹ ਫੈਸਲਾ ਕਰ ਰਹੇ ਸਨ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਕੋਲ ਨਹੀਂ ਸੀ। (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- ਕੀ ਤੁਹਾਨੂੰ ਹੈਰਾਨੀ ਹੁੰਦੀ ਹੈ ਕਿ ਤੁਹਾਡੇ ਰੱਬ ਵੱਲੋਂ ਤੁਹਾਡੇ ਆਪਣੇ ਵਿੱਚੋਂ ਇੱਕ ਵਿਅਕਤੀ ਰਾਹੀਂ ਤੁਹਾਡੇ ਕੋਲ ਨਸੀਹਤ ਆਈ, ਤਾਂ ਜੋ ਉਹ ਤੁਹਾਨੂੰ ਚੇਤਾਵਨੀ ਦੇਵੇ? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- ਆਖ: "ਮੈਨੂੰ ਉਨ੍ਹਾਂ ਚੀਜ਼ਾਂ ਦੀ ਬੰਦਗੀ ਕਰਨ ਤੋਂ ਰੋਕਿਆ ਗਿਆ ਹੈ ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਪੁਕਾਰਦੇ ਹੋ।" (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- ਆਪਣੀਆਂ ਪਤਨੀਆਂ ਜਾਂ ਆਪਣੇ ਸੱਜੇ ਹੱਥਾਂ ਦੀ ਮਲਕੀਅਤ ਵਾਲੀਆਂ (ਦਾਸੀਆਂ) ਤੋਂ ਬਿਨਾਂ, ਕਿਉਂਕਿ ਉਹ ਦੋਸ਼ੀ ਨਹੀਂ ਹਨ। (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- ਕਿਉਂਕਿ ਅੱਲਾਹ ਰਾਤ ਨੂੰ ਦਿਨ ਵਿੱਚ ਦਾਖਲ ਕਰਦਾ ਹੈ ਅਤੇ ਦਿਨ ਨੂੰ ਰਾਤ ਵਿੱਚ ਦਾਖਲ ਕਰਦਾ ਹੈ। (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- ਅੱਗ, ਅਤੇ ਉਸ ਨੇ ਆਪਣੇ ਘਰ ਵਾਲਿਆਂ ਨੂੰ ਕਿਹਾ: "ਰੁਕੋ, ਮੈਂ ਅੱਗ ਵੇਖੀ ਹੈ, ਸ਼ਾਇਦ ਮੈਂ ਉਸ ਵਿੱਚੋਂ ਤੁਹਾਡੇ ਲਈ ਕੁਝ ਲਿਆ ਸਕਾਂ।" (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- ਉਸ ਨੇ ਕਿਹਾ: "ਮੈਂ ਉਸ ਤੋਂ ਉੱਤਮ ਹਾਂ; ਤੂੰ ਮੈਨੂੰ ਅੱਗ ਤੋਂ ਪੈਦਾ ਕੀਤਾ ਅਤੇ ਉਸ ਨੂੰ ਮਿੱਟੀ ਤੋਂ ਪੈਦਾ ਕੀਤਾ।" (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- ਅਤੇ ਜਦੋਂ ਉਨ੍ਹਾਂ ਨੂੰ ਕਿਹਾ ਜਾਂਦਾ ਹੈ: "ਅੱਲਾਹ ਨੇ ਜੋ ਉਤਾਰਿਆ ਹੈ ਉਸ ਵੱਲ ਅਤੇ ਰਸੂਲ ਵੱਲ ਆਓ।" (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- ਅਤੇ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਲਈ ਦੁਖੀ ਨਾ ਹੋਵੋ, ਅਤੇ ਉਹ ਸਾਜ਼ਿਸ਼ਾਂ ਕਰਦੇ ਹਨ ਉਸ ਕਰਕੇ ਤੰਗ ਨਾ ਹੋਵੋ। (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- ਅਤੇ ਜੇਕਰ ਅੱਲਾਹ ਤੁਹਾਨੂੰ ਕੋਈ ਤਕਲੀਫ਼ ਪਹੁੰਚਾਵੇ, ਤਾਂ ਉਸ ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਉਸ ਨੂੰ ਦੂਰ ਨਹੀਂ ਕਰ ਸਕਦਾ, ਅਤੇ ਜੇਕਰ। (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- ਉਨ੍ਹਾਂ ਤੋਂ ਪਹਿਲਾਂ ਪੀੜ੍ਹੀਆਂ ਜੋ ਆਪਣੇ ਘਰਾਂ ਵਿੱਚ ਫਿਰਦੀਆਂ ਸਨ; ਬੇਸ਼ੱਕ, ਇਸ ਵਿੱਚ ਨਿਸ਼ਾਨੀਆਂ ਹਨ। (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- ਅਤੇ ਅਸੀਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲਾਂ ਉੱਤੇ ਪਰਦੇ ਪਾ ਦਿੱਤੇ ਤਾਂ ਜੋ ਉਹ ਇਸ ਨੂੰ ਸਮਝ ਨਾ ਸਕਣ, ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਕੰਨਾਂ ਵਿੱਚ ਭਾਰੀਪਣ, ਅਤੇ ਜੇਕਰ। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- ਉਨ੍ਹਾਂ ਦੇ ਰਸੂਲ ਸਪਸ਼ਟ ਦਲੀਲਾਂ ਲੈ ਕੇ ਉਨ੍ਹਾਂ ਕੋਲ ਆਏ, ਪਰ ਅੱਲਾਹ ਅਜਿਹਾ ਨਹੀਂ ਸੀ ਕਿ ਉਨ੍ਹਾਂ ਉੱਤੇ ਜ਼ੁਲਮ ਕਰੇ, ਸਗੋਂ ਉਹ ਆਪਣੇ ਆਪ ਉੱਤੇ ਜ਼ੁਲਮ ਕਰ ਰਹੇ ਸਨ। (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- ਅਤੇ ਧਰਤੀ ਵਿੱਚ, ਅਤੇ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡਾ ਕੋਈ ਸਰਪ੍ਰਸਤ ਅਤੇ ਨਾ ਕੋਈ ਮਦਦਗਾਰ ਹੈ। (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ਫਿਰ ਤੁਹਾਨੂੰ ਗੁਪਤ ਅਤੇ ਪ੍ਰਗਟ ਦੇ ਜਾਣਨ ਵਾਲੇ ਵੱਲ ਮੋੜਿਆ ਜਾਵੇਗਾ, ਅਤੇ ਉਹ ਤੁਹਾਨੂੰ ਦੱਸੇਗਾ ਜੋ ਤੁਸੀਂ ਕੀ ਕਰ ਰਹੇ ਸੀ। (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- ਰਾਤ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਉਸ ਵਿੱਚ ਅਰਾਮ ਕਰੋ, ਅਤੇ ਦਿਨ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਵੇਖੋ; ਬੇਸ਼ੱਕ, ਇਸ ਵਿੱਚ ਸੋਚਣ ਵਾਲੇ ਲੋਕਾਂ ਲਈ ਨਿਸ਼ਾਨੀਆਂ ਹਨ। (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- ਅਤੇ ਤੁਹਾਡੇ ਰੱਬ ਵੱਲੋਂ ਜੋ ਤੁਹਾਡੇ ਉੱਤੇ ਉਤਾਰਿਆ ਗਿਆ ਹੈ, ਉਹ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਬਹੁਤਿਆਂ ਦੀ ਸਰਕਸ਼ੀ ਅਤੇ ਕੁਫ਼ਰ ਨੂੰ ਹੋਰ ਵਧਾਏਗਾ। (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- ਉਸ ਨੇ ਕਿਹਾ: "ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਮੈਨੂੰ ਦੱਸੋ, ਜੇਕਰ ਮੈਂ ਆਪਣੇ ਰੱਬ ਵੱਲੋਂ ਸਪਸ਼ਟ ਦਲੀਲ ਉੱਤੇ ਹਾਂ ਅਤੇ ਉਸ ਨੇ ਮੈਨੂੰ ਦਿੱਤਾ ਹੈ।" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
