- ਅਤੇ ਜਦੋਂ ਅੱਲਾਹ ਕਿਸੇ ਕੰਮ ਦਾ ਫੈਸਲਾ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਹ ਉਸ ਨੂੰ ਕਹਿੰਦਾ ਹੈ: "ਹੋ ਜਾ!" ਅਤੇ ਉਹ ਹੋ ਜਾਂਦਾ ਹੈ। (وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 2:117; 3:47; 19:35; 40:68
- ਅਤੇ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡਾ ਕੋਈ ਸਰਪ੍ਰਸਤ ਅਤੇ ਨਾ ਕੋਈ ਮਦਦਗਾਰ ਹੈ। (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- ਮੈਂ ਉਨ੍ਹਾਂ ਦੇ ਗੁਨਾਹਾਂ ਨੂੰ ਮੁਆਫ਼ ਕਰ ਦਿਆਂਗਾ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਬਾਗਾਂ ਵਿੱਚ ਪਾਵਾਂਗਾ ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠਾਂ ਨਹਿਰਾਂ ਵਹਿ ਰਹੀਆਂ ਹਨ। (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- ਅਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਬਾਗਾਂ ਵਿੱਚ ਪਾਵਾਂਗੇ ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠਾਂ ਨਹਿਰਾਂ ਵਹਿ ਰਹੀਆਂ ਹਨ, ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਉਹ ਸਦਾ ਰਹਿਣਗੇ। (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- ਤੇਰਾ ਰੱਬ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਕਿ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਕੌਣ ਭਟਕਿਆ, ਅਤੇ ਉਹ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- ਤੁਹਾਨੂੰ ਗੁਪਤ ਅਤੇ ਪ੍ਰਗਟ ਦੇ ਜਾਣਨ ਵਾਲੇ ਵੱਲ ਮੋੜਿਆ ਜਾਵੇਗਾ, ਅਤੇ ਉਹ ਤੁਹਾਨੂੰ ਦੱਸੇਗਾ ਜੋ ਤੁਸੀਂ ਕੀ ਕਰ ਰਹੇ ਸੀ। (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- ਉਹ ਤੁਹਾਡੇ ਪੁੱਤਰਾਂ ਨੂੰ ਕਤਲ ਕਰਦੇ ਸਨ ਅਤੇ ਤੁਹਾਡੀਆਂ ਔਰਤਾਂ ਨੂੰ ਜਿਉਂਦਾ ਰੱਖਦੇ ਸਨ; ਇਸ ਵਿੱਚ ਤੁਹਾਡੇ ਰੱਬ ਵੱਲੋਂ ਇੱਕ ਵੱਡੀ ਪਰੀਖਿਆ ਸੀ। (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- ਬੇਸ਼ੱਕ, ਤੇਰਾ ਰੱਬ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਕਿ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਕੌਣ ਭਟਕਦਾ ਹੈ, ਅਤੇ ਉਹ। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- ਅੱਲਾਹ, ਜਿਸ ਦੇ ਲਈ ਅਕਾਸ਼ਾਂ ਵਿੱਚ ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਜੋ ਵੀ ਹੈ। (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- ਤੁਹਾਡੇ ਤੋਂ ਪਹਿਲਾਂ ਦੀਆਂ ਕੌਮਾਂ ਵਿੱਚ, ਜਿਨ੍ਹਾਂ ਅਤੇ ਮਨੁੱਖਾਂ ਵਿੱਚੋਂ। (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- ਅੱਲਾਹ ਦੀ ਬੰਦਗੀ ਕਰੋ, ਉਸ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡਾ ਕੋਈ ਪੂਜਣਯੋਗ ਨਹੀਂ, ਕੀ ਤੁਸੀਂ ਡਰਦੇ ਨਹੀਂ? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- ਅਤੇ ਅਸੀਂ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲਾਂ ਉੱਤੇ ਪਰਦੇ ਪਾ ਦਿੱਤੇ ਤਾਂ ਜੋ ਉਹ ਇਸ ਨੂੰ ਸਮਝ ਨਾ ਸਕਣ, ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਕੰਨਾਂ ਵਿੱਚ ਭਾਰੀਪਣ। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- ਉਹ ਕਿਆਮਤ ਦੇ ਦਿਨ ਉਨ੍ਹਾਂ ਵਿਚਕਾਰ ਉਸ ਚੀਜ਼ ਦਾ ਫੈਸਲਾ ਕਰੇਗਾ ਜਿਸ ਵਿੱਚ ਉਹ ਮਤਭੇਦ ਕਰਦੇ ਸਨ। (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- ਉਸ ਨੇ ਕਿਹਾ: "ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਮੈਨੂੰ ਦੱਸੋ, ਜੇਕਰ ਮੈਂ ਆਪਣੇ ਰੱਬ ਵੱਲੋਂ ਸਪਸ਼ਟ ਦਲੀਲ ਉੱਤੇ ਹਾਂ?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- ਇਹ ਉਸ ਕਾਰਨ ਹੈ ਜੋ ਤੁਹਾਡੇ ਹੱਥਾਂ ਨੇ ਅੱਗੇ ਭੇਜਿਆ, ਅਤੇ ਅੱਲਾਹ ਆਪਣੇ ਬੰਦਿਆਂ ਉੱਤੇ ਜ਼ੁਲਮ ਕਰਨ ਵਾਲਾ ਨਹੀਂ। (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- ਉਨ੍ਹਾਂ ਲਈ ਦੁਨੀਆ ਵਿੱਚ ਅਪਮਾਨ ਹੈ ਅਤੇ ਆਖ਼ਿਰਤ ਵਿੱਚ ਵੱਡਾ ਅਜ਼ਾਬ ਹੈ। (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- ਅਕਾਸ਼ਾਂ ਵਿੱਚ ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਜੋ ਵੀ ਹੈ, ਅਤੇ ਅੱਲਾਹ ਸਰਪ੍ਰਸਤ ਦੇ ਤੌਰ ਉੱਤੇ ਕਾਫੀ ਹੈ। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- ਸਿਵਾਏ ਉਨ੍ਹਾਂ ਦੇ ਜਿਨ੍ਹਾਂ ਈਮਾਨ ਲਿਆਏ ਅਤੇ ਚੰਗੇ ਕੰਮ ਕੀਤੇ; ਉਨ੍ਹਾਂ ਲਈ ਕਦੇ ਨਾ ਮੁੱਕਣ ਵਾਲਾ ਇਨਾਮ ਹੈ। (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- ਕਿ ਤੂੰ ਮੇਰੇ ਨਾਲ ਉਸ ਚੀਜ਼ ਨੂੰ ਸਾਂਝਾ ਨਾ ਕਰ ਜਿਸ ਦਾ ਤੈਨੂੰ ਗਿਆਨ ਨਹੀਂ; ਉਨ੍ਹਾਂ ਦੀ ਗੱਲ ਨਾ ਮੰਨ। (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- ਬੇਸ਼ੱਕ, ਇਹ ਇੱਕ ਨਸੀਹਤ ਹੈ; ਜੋ ਚਾਹੇ, ਉਹ ਆਪਣੇ ਰੱਬ ਵੱਲ ਰਾਹ ਅਪਣਾਵੇ। (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- ਅਤੇ ਜੋ ਸ਼ੁਕਰ ਕਰਦਾ ਹੈ, ਉਹ ਆਪਣੇ ਲਈ ਸ਼ੁਕਰ ਕਰਦਾ ਹੈ; ਅਤੇ ਜੋ ਨਾਸ਼ੁਕਰਾ ਹੈ। (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- ਜਿਹੜੇ ਨਮਾਜ਼ ਕਾਇਮ ਕਰਦੇ ਹਨ, ਜ਼ਕਾਤ ਦਿੰਦੇ ਹਨ, ਅਤੇ ਆਖ਼ਿਰਤ ਉੱਤੇ ਯਕੀਨ ਰੱਖਦੇ ਹਨ। (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ਇਬਰਾਹੀਮ, ਇਸਮਾਈਲ, ਇਸਹਾਕ, ਯਾਕੂਬ ਅਤੇ ਔਲਾਦਾਂ ਨੂੰ, ਅਤੇ ਮੂਸਾ ਅਤੇ ਈਸਾ ਨੂੰ ਜੋ ਦਿੱਤਾ ਗਿਆ। (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- ਗਰੋਹ ਬਣ ਕੇ, ਜਦੋਂ ਤੱਕ ਉਹ ਉਸ ਕੋਲ ਨਾ ਪਹੁੰਚਣ, ਅਤੇ ਉਸ ਦੇ ਦਰਵਾਜ਼ੇ ਖੋਲ੍ਹੇ ਜਾਣ, ਅਤੇ ਉਸ ਦੇ ਰਾਖੇ ਉਨ੍ਹਾਂ ਨੂੰ ਕਹਿਣ। (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- ਅੱਲਾਹ ਤੁਹਾਨੂੰ ਤੁਹਾਡੀਆਂ ਸੌਂਹਾਂ ਦੀਆਂ ਬੇਕਾਰ ਗੱਲਾਂ ਉੱਤੇ ਨਹੀਂ ਫੜਦਾ, ਪਰ ਉਹ ਤੁਹਾਨੂੰ ਉਸ ਉੱਤੇ ਫੜਦਾ ਹੈ। (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- ਰਹਿਮਤ, ਉਹ ਉਸ ਤੋਂ ਖੁਸ਼ ਹੁੰਦੇ ਹਨ, ਅਤੇ ਜੇਕਰ ਉਨ੍ਹਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਹੱਥਾਂ ਦੀ ਕਮਾਈ ਕਾਰਨ ਕੋਈ ਤਕਲੀਫ਼ ਪਹੁੰਚਦੀ ਹੈ। (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- ਬਾਗ ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠਾਂ ਨਹਿਰਾਂ ਵਹਿ ਰਹੀਆਂ ਹਨ, ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਉਹ ਸਦਾ ਰਹਿਣਗੇ, ਅਤੇ ਕੰਮ ਕਰਨ ਵਾਲਿਆਂ ਦਾ ਇਨਾਮ ਕਿੰਨਾ ਚੰਗਾ ਹੈ! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- ਅੱਲਾਹ ਜਾਣਦਾ ਹੈ ਜੋ ਅਕਾਸ਼ਾਂ ਵਿੱਚ ਹੈ ਅਤੇ ਜੋ ਧਰਤੀ ਵਿੱਚ ਹੈ, ਅਤੇ ਅੱਲਾਹ। (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- ਅੱਲਾਹ ਦੀ ਆਗਿਆ ਦੀ ਪਾਲਣਾ ਕਰੋ ਅਤੇ ਰਸੂਲ ਦੀ ਆਗਿਆ ਦੀ ਪਾਲਣਾ ਕਰੋ; ਪਰ ਜੇਕਰ ਤੁਸੀਂ ਮੂੰਹ ਮੋੜਦੇ ਹੋ, ਤਾਂ ਉਸ ਉੱਤੇ (ਜ਼ਿੰਮੇਵਾਰੀ) ਹੈ। (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ਉਨ੍ਹਾਂ ਲਈ ਉਨ੍ਹਾਂ ਦੇ ਰੱਬ ਕੋਲ ਉਨ੍ਹਾਂ ਦਾ ਇਨਾਮ ਹੈ, ਅਤੇ ਨਾ ਉਨ੍ਹਾਂ ਨੂੰ ਕੋਈ ਡਰ ਹੈ, ਅਤੇ ਨਾ ਉਹ। (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- ਅਤੇ ਉਨ੍ਹਾਂ ਨੇ ਕਿਹਾ: "ਕੀ ਜਦੋਂ ਅਸੀਂ ਹੱਡੀਆਂ ਅਤੇ ਮਿੱਟੀ ਹੋ ਜਾਵਾਂਗੇ, ਤਾਂ ਕੀ ਅਸੀਂ ਨਵੀਂ ਰਚਨਾ ਵਜੋਂ ਉਠਾਏ ਜਾਵਾਂਗੇ?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- ਅਤੇ ਉਹ ਆਪਣੇ ਲਈ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਸਰਪ੍ਰਸਤ ਅਤੇ ਨਾ ਮਦਦਗਾਰ ਪਾਉਂਦੇ ਹਨ। (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "ਤੁਸੀਂ ਕਿੰਨਾ ਚਿਰ ਰਹੇ?" ਉਸ ਨੇ ਕਿਹਾ: "ਮੈਂ ਇੱਕ ਦਿਨ ਜਾਂ ਦਿਨ ਦਾ ਕੁਝ ਹਿੱਸਾ ਰਿਹਾ।" ਉਸ ਨੇ ਕਿਹਾ। (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- ਕਿਆਮਤ ਦੇ ਦਿਨ ਤੱਕ, ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਕੌਣ ਹੈ ਜੋ ਤੁਹਾਡੇ ਕੋਲ ਲਿਆ ਸਕੇ? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- ਜੋ ਚੰਗਾ ਕੰਮ ਕਰਦਾ ਹੈ, ਭਾਵੇਂ ਮਰਦ ਹੈ ਜਾਂ ਔਰਤ, ਅਤੇ ਉਹ ਮੋਮਿਨ ਹੈ। (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- ਜਿਹੜੇ ਅੱਲਾਹ ਦੇ ਰਾਹ ਤੋਂ ਰੋਕਦੇ ਹਨ ਅਤੇ ਉਸ ਨੂੰ ਟੇਢਾ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹਨ, ਅਤੇ ਉਹ ਆਖ਼ਿਰਤ ਨੂੰ ਨਹੀਂ ਮੰਨਦੇ। (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ਜਿੱਥੇ ਚਾਹੋ ਖਾਓ, ਪਰ ਇਸ ਰੁੱਖ ਦੇ ਨੇੜੇ ਨਾ ਜਾਓ, ਨਹੀਂ ਤਾਂ ਤੁਸੀਂ ਜ਼ਾਲਮ ਬਣ ਜਾਓਗੇ। (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- ਆਖ: "ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਤੁਸੀਂ ਆਪਣੀ ਥਾਂ ਕੰਮ ਕਰੋ, ਮੈਂ ਵੀ ਕੰਮ ਕਰਦਾ ਹਾਂ, ਫਿਰ ਤੁਹਾਨੂੰ ਪਤਾ ਲੱਗ ਜਾਵੇਗਾ।" (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- ਬੇਸ਼ੱਕ, ਘਾਟੇ ਵਿੱਚ ਰਹਿਣ ਵਾਲੇ ਉਹ ਹਨ ਜਿਨ੍ਹਾਂ ਨੇ ਕਿਆਮਤ ਦੇ ਦਿਨ ਆਪਣੇ ਆਪ ਨੂੰ ਅਤੇ ਆਪਣੇ ਘਰ-ਪਰਿਵਾਰ ਨੂੰ ਘਾਟੇ ਵਿੱਚ ਪਾ ਦਿੱਤਾ, ਸੁਣੋ। (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- ਜੋ ਰਾਹ ਪਾਉਂਦਾ ਹੈ, ਉਹ ਆਪਣੇ ਲਈ ਰਾਹ ਪਾਉਂਦਾ ਹੈ; ਅਤੇ ਜੋ ਭਟਕਦਾ ਹੈ, ਉਹ ਆਪਣੇ ਲਈ ਭਟਕਦਾ ਹੈ; ਅਤੇ। (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- ਅਤੇ ਕਾਫ਼ਿਰ ਲੋਕ ਕਹਿੰਦੇ ਹਨ: "ਉਸ ਉੱਤੇ ਉਸ ਦੇ ਰੱਬ ਵੱਲੋਂ ਕੋਈ ਨਿਸ਼ਾਨੀ ਕਿਉਂ ਨਹੀਂ ਉਤਾਰੀ ਗਈ?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- ਜਿਸ ਨੇ ਤੁਹਾਡੇ ਲਈ ਰਾਤ ਬਣਾਈ ਤਾਂ ਜੋ ਤੁਸੀਂ ਉਸ ਵਿੱਚ ਅਰਾਮ ਕਰੋ, ਅਤੇ ਦਿਨ ਤਾਂ ਜੋ ਤੁਸੀਂ ਵੇਖੋ, ਬੇਸ਼ੱਕ। (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- ਉਸ ਦਿਨ ਤੋਂ ਪਹਿਲਾਂ ਜਿਸ ਵਿੱਚ ਨਾ ਕੋਈ ਲੈਣ-ਦੇਣ ਹੈ ਅਤੇ ਨਾ ਕੋਈ ਦੋਸਤੀ। (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- ਤਾਂ ਜੋ ਉਹ ਸੋਚਣ ਕਿ ਉਨ੍ਹਾਂ ਦੇ ਸਾਥੀ ਨੂੰ ਕੋਈ ਪਾਗਲਪਨ ਨਹੀਂ; ਉਹ ਤਾਂ ਬੱਸ ਇੱਕ ਚੇਤਾਵਨੀ ਦੇਣ ਵਾਲਾ ਹੈ। (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- ਉਹ ਉਸ ਵਿੱਚ ਸਦਾ ਰਹਿਣਗੇ, ਨਾ ਉਨ੍ਹਾਂ ਤੋਂ ਅਜ਼ਾਬ ਹਲਕਾ ਕੀਤਾ ਜਾਵੇਗਾ ਅਤੇ ਨਾ ਉਨ੍ਹਾਂ ਨੂੰ ਮੋਹਲਤ ਦਿੱਤੀ ਜਾਵੇਗੀ। (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- ਆਪਣੀਆਂ ਅੱਖਾਂ ਉਨ੍ਹਾਂ ਚੀਜ਼ਾਂ ਵੱਲ ਨਾ ਫੈਲਾਓ ਜੋ ਅਸੀਂ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕੁਝ ਨੂੰ ਆਨੰਦ ਲਈ ਦਿੱਤੀਆਂ ਹਨ। (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- ਅਤੇ ਲੋਕਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀਆਂ ਚੀਜ਼ਾਂ ਵਿੱਚ ਘਾਟਾ ਨਾ ਦਿਓ, ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਫ਼ਸਾਦ ਨਾ ਫੈਲਾਓ। (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- ਅਤੇ ਉਸ ਉੱਤੇ ਸਲਾਮ ਹੈ ਜਿਸ ਦਿਨ ਉਹ ਪੈਦਾ ਹੋਇਆ, ਅਤੇ ਜਿਸ ਦਿਨ ਉਹ ਮਰੇਗਾ, ਅਤੇ ਜਿਸ ਦਿਨ ਉਹ ਜਿਉਂਦਾ ਕੀਤਾ ਜਾਵੇਗਾ। (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਤੁਸੀਂ ਆਪਣੀ ਥਾਂ ਕੰਮ ਕਰੋ, ਮੈਂ ਵੀ ਕੰਮ ਕਰਦਾ ਹਾਂ, ਫਿਰ ਤੁਹਾਨੂੰ ਪਤਾ ਲੱਗ ਜਾਵੇਗਾ ਕਿ ਕੌਣ। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- ਅਤੇ ਕਿਸੇ ਰਸੂਲ ਲਈ ਇਹ ਸੰਭਵ ਨਹੀਂ ਸੀ ਕਿ ਉਹ ਅੱਲਾਹ ਦੀ ਇਜਾਜ਼ਤ ਤੋਂ ਬਿਨਾਂ ਕੋਈ ਨਿਸ਼ਾਨੀ ਲਿਆਵੇ। (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ਫਿਰ ਹਰ ਵਿਅਕਤੀ ਨੂੰ ਉਸ ਦੀ ਕਮਾਈ ਦਾ ਪੂਰਾ ਇਨਾਮ ਦਿੱਤਾ ਜਾਵੇਗਾ, ਅਤੇ ਉਨ੍ਹਾਂ ਉੱਤੇ ਜ਼ੁਲਮ ਨਹੀਂ ਕੀਤਾ ਜਾਵੇਗਾ। (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ਮਰਦ ਹੋਵੇ ਜਾਂ ਔਰਤ, ਅਤੇ ਉਹ ਮੋਮਿਨ ਹੋਵੇ, ਤਾਂ ਉਹ ਲੋਕ ਜੰਨਤ ਵਿੱਚ ਦਾਖਲ ਹੋਣਗੇ। (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ਉਸ ਨੇ ਕੋਈ ਔਲਾਦ ਨਹੀਂ ਰੱਖੀ ਅਤੇ ਨਾ ਉਸ ਦੀ ਬਾਦਸ਼ਾਹਤ ਵਿੱਚ ਕੋਈ ਸਾਂਝੀ ਹੈ। (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- ਅਤੇ ਅੱਲਾਹ ਜਿਸ ਨੂੰ ਰਾਹ ਦਿਖਾਉਂਦਾ ਹੈ, ਉਹ ਰਾਹ ਪਾਉਣ ਵਾਲਾ ਹੈ; ਅਤੇ ਜਿਸ ਨੂੰ ਉਹ ਭਟਕਾਉਂਦਾ ਹੈ। (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- ਵੇਖੋ, ਉਹ ਤੁਹਾਡੇ ਲਈ ਕਿਵੇਂ ਉਦਾਹਰਣਾਂ ਬਣਾਉਂਦੇ ਹਨ, ਫਿਰ ਉਹ ਭਟਕ ਗਏ, ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਰਾਹ ਨਹੀਂ ਮਿਲਿਆ। (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- ਆਖ: "ਮੈਂ ਡਰਦਾ ਹਾਂ, ਜੇਕਰ ਮੈਂ ਆਪਣੇ ਰੱਬ ਦੀ ਨਾਫ਼ਰਮਾਨੀ ਕਰਾਂ, ਤਾਂ ਵੱਡੇ ਦਿਨ ਦੇ ਅਜ਼ਾਬ ਤੋਂ।" (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- ਉਨ੍ਹਾਂ ਦੀਆਂ ਸ਼ਰਮ ਵਾਲੀਆਂ ਥਾਂਵਾਂ ਖੁੱਲ੍ਹ ਗਈਆਂ, ਅਤੇ ਉਹ ਜੰਨਤ ਦੇ ਪੱਤਿਆਂ ਨਾਲ ਆਪਣੇ ਆਪ ਨੂੰ ਢੱਕਣ ਲੱਗੇ। (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- ਅਤੇ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ ਬੁਲਾ ਸਕਦੇ ਹੋ, ਉਨ੍ਹਾਂ ਨੂੰ ਬੁਲਾਓ, ਜੇਕਰ ਤੁਸੀਂ ਸੱਚੇ ਹੋ। (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- ਧਰਤੀ ਦੀਆਂ ਸਾਰੀਆਂ ਚੀਜ਼ਾਂ ਅਤੇ ਉਸ ਦੇ ਬਰਾਬਰ ਹੋਰ, ਆਪਣੇ ਆਪ ਨੂੰ ਛੁਡਾਉਣ ਲਈ। (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- ਅਸੀਂ ਤੁਹਾਨੂੰ ਜੋ ਦਿੱਤਾ ਹੈ ਉਸ ਨੂੰ ਮਜ਼ਬੂਤੀ ਨਾਲ ਫੜੋ, ਅਤੇ ਜੋ ਉਸ ਵਿੱਚ ਹੈ ਉਸ ਨੂੰ ਯਾਦ ਰੱਖੋ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਪਰਹੇਜ਼ਗਾਰ ਬਣੋ। (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ਕੀ ਤੁਸੀਂ ਉਹ ਬਦਕਾਰੀ ਕਰਦੇ ਹੋ ਜੋ ਤੁਹਾਡੇ ਤੋਂ ਪਹਿਲਾਂ ਸੰਸਾਰ ਵਿੱਚ ਕਿਸੇ ਨੇ ਨਹੀਂ ਕੀਤੀ? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- ਅਤੇ ਅੱਲਾਹ ਲਈ ਹੀ ਹੈ ਜੋ ਅਕਾਸ਼ਾਂ ਵਿੱਚ ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਹੈ, ਅਤੇ ਅੱਲਾਹ ਹੈ। (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- ਉਨ੍ਹਾਂ ਦੇ ਕੀਤੇ ਗੁਨਾਹ ਉਨ੍ਹਾਂ ਉੱਤੇ ਆ ਪਏ, ਅਤੇ ਜਿਸ ਚੀਜ਼ ਦਾ ਉਹ ਮਜ਼ਾਕ ਉਡਾਉਂਦੇ ਸਨ, ਉਸ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਘੇਰ ਲਿਆ। (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
