- ਜਿਸ ਨੇ ਸਿੱਧਾ ਰਾਹ ਪਾਇਆ, ਉਹ ਆਪਣੇ ਆਪ ਲਈ ਪਾਇਆ, ਅਤੇ ਜਿਹੜਾ ਭਟਕ ਗਿਆ। (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- ਆਪਣੇ ਆਪ ਲਈ ਪਾਇਆ, ਅਤੇ ਜਿਹੜਾ ਭਟਕ ਗਿਆ, ਉਹ ਆਪਣੇ ਨੁਕਸਾਨ ਲਈ ਭਟਕ ਗਿਆ। (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- ਉਸ ਉੱਤੇ ਉਸ ਦੇ ਰੱਬ ਵੱਲੋਂ ਕੋਈ ਨਿਸ਼ਾਨੀ ਕਿਉਂ ਨਹੀਂ ਉਤਾਰੀ ਗਈ? ਆਖ: ਬੇਸ਼ੱਕ। (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- ਜਿਨ੍ਹਾਂ ਨੇ ਈਮਾਨ ਲਿਆਂਦਾ ਅਤੇ ਚੰਗੇ ਕੰਮ ਕੀਤੇ, ਉਹਨਾਂ ਲਈ ਅਟੁੱਟ ਇਨਾਮ ਹੈ। (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- ਤੂੰ ਜੀਉਂਦੇ ਨੂੰ ਮੁਰਦੇ ਵਿੱਚੋਂ ਕੱਢਦਾ ਹੈਂ ਅਤੇ ਮੁਰਦੇ ਨੂੰ ਜੀਉਂਦੇ ਵਿੱਚੋਂ ਕੱਢਦਾ ਹੈਂ। (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- ਜਿਹੜਾ ਅੱਲਾਹ ਦੇ ਉਤਾਰੇ (ਕਾਨੂੰਨ) ਅਨੁਸਾਰ ਫੈਸਲਾ ਨਹੀਂ ਕਰਦਾ, ਉਹ ਲੋਕ ਹੀ ਹਨ। (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- ਉਸ ਨੇ ਆਕਾਸ਼ਾਂ, ਧਰਤੀ ਅਤੇ ਉਹਨਾਂ ਦੇ ਵਿੱਚਕਾਰ ਸਭ ਕੁਝ ਛੇ ਦਿਨਾਂ ਵਿੱਚ ਪੈਦਾ ਕੀਤਾ। (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- ਬੇਸ਼ੱਕ ਅੱਲਾਹ ਲੋਕਾਂ ਉੱਤੇ ਬੜਾ ਕਿਰਪਾਵਾਨ ਹੈ, ਪਰ ਬਹੁਤੇ। (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- ਅੱਲਾਹ ਨੇ ਉਹਨਾਂ ਉੱਤੇ ਜ਼ੁਲਮ ਨਹੀਂ ਕੀਤਾ, ਪਰ ਉਹ ਆਪੇ ਆਪਣੇ ਉੱਤੇ ਜ਼ੁਲਮ ਕਰਦੇ ਸਨ। (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- ਉਹ ਤੁਹਾਡੇ ਗੁਨਾਹਾਂ ਨੂੰ ਮੁਆਫ਼ ਕਰੇਗਾ ਅਤੇ ਤੁਹਾਨੂੰ ਅਜਿਹੇ ਬਾਗ਼ਾਂ ਵਿੱਚ ਦਾਖ਼ਲ ਕਰੇਗਾ, ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ। (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- ਉਸ ਨੇ ਤੁਹਾਡੇ ਉੱਤੇ ਮੁਰਦਾਰ, ਖੂਨ, ਸੂਰ ਦਾ ਮਾਸ ਅਤੇ ਉਹ ਚੀਜ਼ ਹਰਾਮ ਕੀਤੀ ਹੈ ਜੋ ਅੱਲਾਹ ਤੋਂ ਬਿਨਾਂ ਕਿਸੇ ਹੋਰ ਦੇ ਨਾਮ ਉੱਤੇ ਜ਼ਿਬ੍ਹਾ ਕੀਤੀ ਜਾਵੇ। (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- ਮੈਂ ਡਰਦਾ ਹਾਂ, ਜੇਕਰ ਮੈਂ ਆਪਣੇ ਰੱਬ ਦੀ ਨਾਫ਼ਰਮਾਨੀ ਕਰਾਂ, ਤਾਂ ਵੱਡੇ ਦਿਨ ਦੇ ਅਜ਼ਾਬ ਤੋਂ। (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- ਪਰ ਉਹਨਾਂ ਕੋਲ ਗਿਆਨ ਆਉਣ ਮਗਰੋਂ, ਆਪਸੀ ਹੱਸਦ ਵਿੱਚ। (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- ਉਹ ਨਮਾਜ਼ ਕਾਇਮ ਕਰਦੇ ਹਨ ਅਤੇ ਜੋ ਕੁਝ ਅਸੀਂ ਉਹਨਾਂ ਨੂੰ ਦਿੱਤਾ ਹੈ, ਉਸ ਵਿੱਚੋਂ ਲੁਕੋ ਕੇ ਅਤੇ ਖੁੱਲ੍ਹ ਕੇ ਖ਼ਰਚ ਕਰਦੇ ਹਨ। (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- ਕੀ ਅਸੀਂ ਅੱਲਾਹ ਨੂੰ ਛੱਡ ਕੇ ਅਜਿਹੇ ਨੂੰ ਪੁਕਾਰੀਏ, ਜੋ ਨਾ ਸਾਨੂੰ ਫ਼ਾਇਦਾ ਦੇ ਸਕੇ ਅਤੇ ਨਾ ਨੁਕਸਾਨ? (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- ਉਹ ਉਸ (ਕੁਰਾਨ) ਉੱਤੇ ਈਮਾਨ ਲਿਆਉਂਦੇ ਹਨ ਜੋ ਤੁਹਾਡੇ ਵੱਲ ਉਤਾਰਿਆ ਗਿਆ ਅਤੇ ਜੋ ਤੁਹਾਡੇ ਤੋਂ ਪਹਿਲਾਂ ਉਤਾਰਿਆ ਗਿਆ। (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- ਕੀ ਤੁਸੀਂ ਨਹੀਂ ਵੇਖਦੇ ਕਿ ਅੱਲਾਹ ਅਕਾਸ਼ ਵਿੱਚੋਂ ਪਾਣੀ ਵਰਸਾਉਂਦਾ ਹੈ? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- ਜਦੋਂ ਉਹ ਕਿਸੇ ਕੰਮ ਦਾ ਫੈਸਲਾ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਸ ਨੂੰ ਆਖਦਾ ਹੈ: ਹੋ ਜਾ, ਅਤੇ ਉਹ ਹੋ ਜਾਂਦਾ ਹੈ। (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- ਅਤੇ ਮਦਯਨ ਵੱਲ ਉਹਨਾਂ ਦੇ ਭਰਾ ਸ਼ੁਐਬ ਨੂੰ (ਭੇਜਿਆ)। ਉਸ ਨੇ ਆਖਿਆ: ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਅੱਲਾਹ ਦੀ ਬੰਦਗੀ ਕਰੋ। (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- ਇਹ ਗੈਬ ਦੀਆਂ ਖ਼ਬਰਾਂ ਵਿੱਚੋਂ ਹੈ, ਜੋ ਅਸੀਂ ਤੁਹਾਡੇ ਵੱਲ ਵਹੀ ਰਾਹੀਂ ਭੇਜ ਰਹੇ ਹਾਂ; ਤੁਸੀਂ ਇਹ ਨਹੀਂ ਜਾਣਦੇ ਸੀ। (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- ਜਦੋਂ ਉਹਨਾਂ ਦੀ ਮਿਆਦ ਆ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਉਹ ਇੱਕ ਘੜੀ ਵੀ ਪਿੱਛੇ ਨਹੀਂ ਕਰ ਸਕਦੇ, ਨਾ ਅੱਗੇ। (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- ਅਤੇ ਸ਼ੈਤਾਨ ਦੇ ਕਦਮਾਂ ਉੱਤੇ ਨਾ ਚੱਲੋ, ਬੇਸ਼ੱਕ ਉਹ ਤੁਹਾਡਾ ਖੁੱਲ੍ਹਾ ਦੁਸ਼ਮਣ ਹੈ। (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- ਕੁਝ ਲੋਕ ਅਜਿਹੇ ਹਨ ਜੋ ਅੱਲਾਹ ਬਾਰੇ ਬਿਨਾਂ ਗਿਆਨ ਦੇ ਝਗੜਾ ਕਰਦੇ ਹਨ। (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- ਅੱਲਾਹ ਜਿਸ ਨੂੰ ਚਾਹੁੰਦਾ ਹੈ, ਦੇ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਅੱਲਾਹ ਵੱਡਾ ਕਿਰਪਾਵਾਨ ਹੈ। (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ਹਰੇਕ ਜੀਵ ਨੂੰ ਉਸ ਦੀ ਕਮਾਈ ਦਾ ਪੂਰਾ ਬਦਲਾ ਦਿੱਤਾ ਜਾਵੇਗਾ, ਅਤੇ ਉਹਨਾਂ ਉੱਤੇ ਜ਼ੁਲਮ ਨਹੀਂ ਹੋਵੇਗਾ। (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- ਉਸ ਜਾਨ ਨੂੰ ਨਾ ਮਾਰੋ ਜਿਸ ਨੂੰ ਅੱਲਾਹ ਨੇ ਹਰਾਮ ਕੀਤਾ ਹੈ, ਪਰੰਤੂ ਹੱਕ ਨਾਲ। (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- ਜਦੋਂ ਉਹ ਕਿਸੇ ਕੰਮ ਦਾ ਫੈਸਲਾ ਕਰਦਾ ਹੈ, ਤਾਂ ਉਸ ਨੂੰ ਆਖਦਾ ਹੈ: ਹੋ ਜਾ। (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- ਤੁਸੀਂ ਜਹੰਨਮ ਦੇ ਦਰਵਾਜ਼ਿਆਂ ਵਿੱਚ ਦਾਖ਼ਲ ਹੋ ਜਾਓ, ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹੋਗੇ; ਅਤੇ ਮੁਤੱਕਬਿਰਾਂ ਦਾ ਟਿਕਾਣਾ ਕਿੰਨਾ ਬੁਰਾ ਹੈ! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- ਕੀ ਤੁਸੀਂ ਉਹਨਾਂ ਲੋਕਾਂ ਨੂੰ ਨਹੀਂ ਵੇਖਿਆ, ਜਿਨ੍ਹਾਂ ਨੂੰ ਕਿਤਾਬ ਦਾ ਕੁਝ ਹਿੱਸਾ ਦਿੱਤਾ ਗਿਆ ਸੀ? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- ਉਹਨਾਂ ਲਈ ਅਜਿਹੇ ਬਾਗ਼ ਹਨ, ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ, ਉਹ ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ। (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- ਹੇ ਮੇਰੀ ਕੌਮ ਦੇ ਲੋਕੋ! ਤੁਸੀਂ ਆਪਣੀ ਥਾਂ ਕੰਮ ਕਰੋ, ਮੈਂ ਵੀ ਕੰਮ ਕਰ ਰਿਹਾ ਹਾਂ, ਅਤੇ ਤੁਹਾਨੂੰ ਜਲਦੀ ਪਤਾ ਲੱਗ ਜਾਵੇਗਾ। (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- ਜਿਹੜਾ ਅੱਲਾਹ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ ਦਾ ਵਿਰੋਧ ਕਰਦਾ ਹੈ, ਉਸ ਲਈ ਜਹੰਨਮ ਦੀ ਅੱਗ ਹੈ, ਜਿਸ ਵਿੱਚ ਉਹ ਹਮੇਸ਼ਾ ਰਹੇਗਾ। (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- ਅਸੀਂ ਉਹਨਾਂ ਦੇ ਦਿਲਾਂ ਉੱਤੇ ਪਰਦੇ ਪਾ ਦਿੱਤੇ ਹਨ, ਤਾਂ ਜੋ ਉਹ ਇਸ ਨੂੰ ਨਾ ਸਮਝਣ, ਅਤੇ ਉਹਨਾਂ ਦੇ ਕੰਨਾਂ ਵਿੱਚ ਭਾਰੀਪਣ। (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- ਜਿਸ ਵਸੋਂ ਵਿੱਚ ਅਸੀਂ ਕੋਈ ਸੁਚੇਤ ਕਰਨ ਵਾਲਾ ਭੇਜਿਆ, ਉਸ ਦੇ ਧਨਾਢ ਲੋਕਾਂ ਨੇ ਆਖਿਆ: ਅਸੀਂ। (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- ਉਹਨਾਂ ਨੇ ਆਖਿਆ: ਸਾਡੇ ਲਈ ਆਪਣੇ ਰੱਬ ਅੱਗੇ ਦੁਆ ਕਰੋ ਕਿ ਉਹ ਸਾਨੂੰ ਸਪੱਸ਼ਟ ਕਰੇ ਕਿ ਉਹ ਕਿਹੋ ਜਿਹੀ ਹੈ। (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- ਉਹ ਕਹਿਣਗੇ: ਅੱਲਾਹ। ਆਖ: ਸਾਰੀ ਪ੍ਰਸ਼ੰਸਾ ਅੱਲਾਹ ਲਈ ਹੈ! ਪਰ ਉਹਨਾਂ ਵਿੱਚੋਂ ਬਹੁਤੇ। (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- ਉਸ ਦੀ ਕੌਮ ਦਾ ਜਵਾਬ ਸਿਰਫ਼ ਇਹੀ ਸੀ ਕਿ ਉਹਨਾਂ ਨੇ ਆਖਿਆ: ਉਹਨਾਂ ਨੂੰ ਕੱਢ ਦਿਓ। (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ, ਉਹ ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ; ਇਹੀ ਮਹਾਨ ਸਫ਼ਲਤਾ ਹੈ। (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- ਇਹ ਲੋਕ ਆਪਣੇ ਰੱਬ ਵੱਲੋਂ ਮਾਰਗਦਰਸ਼ਨ ਉੱਤੇ ਹਨ, ਅਤੇ ਇਹੀ ਲੋਕ ਸਫ਼ਲ ਹਨ। (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- ਜਿਸ ਨੂੰ ਅਪਮਾਨਜਨਕ ਅਜ਼ਾਬ ਆ ਪਹੁੰਚੇ ਅਤੇ ਉਸ ਉੱਤੇ ਸਦੀਵੀ ਅਜ਼ਾਬ ਆ ਪਵੇ। (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- ਧਰਤੀ ਉੱਤੇ ਚੱਲੋ-ਫਿਰੋ ਅਤੇ ਵੇਖੋ ਕਿ ਝੂਠਲਾਉਣ ਵਾਲਿਆਂ ਦਾ ਅੰਜਾਮ ਕਿਵੇਂ ਹੋਇਆ। (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- ਉਹ ਇਸ ਦੀ ਕਦੇ ਇੱਛਾ ਨਹੀਂ ਕਰਨਗੇ, ਆਪਣੇ ਹੱਥਾਂ ਦੇ ਕੀਤੇ ਕਰਮਾਂ ਕਰਕੇ, ਅਤੇ ਅੱਲਾਹ ਜ਼ਾਲਮਾਂ ਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ। (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- ਉਹ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਕਿ ਕੌਣ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਭਟਕ ਗਿਆ ਹੈ, ਅਤੇ ਉਹ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ। (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- ਬੇਸ਼ੱਕ ਅੱਲਾਹ ਮੇਰਾ ਰੱਬ ਹੈ ਅਤੇ ਤੁਹਾਡਾ ਰੱਬ ਹੈ, ਇਸ ਲਈ ਉਸੇ ਦੀ ਬੰਦਗੀ ਕਰੋ; ਇਹੀ ਸਿੱਧਾ ਰਾਹ ਹੈ। (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- ਉਹ ਲੋਕਾਂ ਉੱਤੇ ਬੜਾ ਕਿਰਪਾਵਾਨ ਹੈ, ਪਰ ਉਹਨਾਂ ਵਿੱਚੋਂ ਬਹੁਤੇ ਸ਼ੁਕਰ ਨਹੀਂ ਕਰਦੇ। (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- ਆਕਾਸ਼ਾਂ, ਧਰਤੀ ਅਤੇ ਉਹਨਾਂ ਦੇ ਵਿੱਚਕਾਰ ਸਭ ਕੁਝ, ਅਸੀਂ ਸਿਰਫ਼ ਸੱਚ ਅਤੇ ਇੱਕ ਨਿਸ਼ਚਿਤ ਮਿਆਦ ਲਈ ਪੈਦਾ ਕੀਤਾ ਹੈ। (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- ਉਹਨਾਂ ਨੂੰ ਉਹਨਾਂ ਦੀਆਂ ਫਜ਼ੂਲ ਗੱਲਾਂ ਅਤੇ ਖੇਡ ਵਿੱਚ ਛੱਡ ਦੇ, ਜਦੋਂ ਤੱਕ ਉਹ ਆਪਣੇ ਉਸ ਦਿਨ ਨੂੰ ਨਾ ਮਿਲਣ, ਜਿਸ ਦਾ ਵਾਅਦਾ ਉਹਨਾਂ ਨਾਲ ਕੀਤਾ ਗਿਆ ਹੈ। (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- ਜਦੋਂ ਉਹ ਈਮਾਨ ਵਾਲਿਆਂ ਨੂੰ ਮਿਲਦੇ ਹਨ, ਤਾਂ ਆਖਦੇ ਹਨ: ਅਸੀਂ ਈਮਾਨ ਲਿਆਂਦਾ ਹੈ, ਅਤੇ ਜਦੋਂ ਆਪਸ ਵਿੱਚ ਇਕੱਲੇ ਹੁੰਦੇ ਹਨ। (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- ਉਹ ਤੌਰਾਤ, ਇੰਜੀਲ ਅਤੇ ਆਪਣੇ ਰੱਬ ਵੱਲੋਂ ਜੋ ਕੁਝ ਉਹਨਾਂ ਵੱਲ ਉਤਾਰਿਆ ਗਿਆ ਹੈ, ਨੂੰ ਕਾਇਮ ਰੱਖਦੇ ਹਨ। (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- ਉਹ ਜਾਣਦਾ ਹੈ ਜੋ ਉਹਨਾਂ ਦੇ ਅੱਗੇ ਹੈ ਅਤੇ ਜੋ ਉਹਨਾਂ ਦੇ ਪਿੱਛੇ ਹੈ, ਅਤੇ ਉਹ ਉਸ ਨੂੰ ਆਪਣੇ ਗਿਆਨ ਨਾਲ ਘੇਰ ਨਹੀਂ ਸਕਦੇ। (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- ਅਤੇ ਉਹੀ ਹੈ ਜਿਸ ਨੇ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਨੂੰ ਛੇ ਦਿਨਾਂ ਵਿੱਚ ਪੈਦਾ ਕੀਤਾ। (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- ਬੇਸ਼ੱਕ ਇਸ ਵਿੱਚ ਤੁਹਾਡੇ ਲਈ ਨਿਸ਼ਾਨੀ ਹੈ, ਜੇਕਰ ਤੁਸੀਂ ਈਮਾਨ ਵਾਲੇ ਹੋ। (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- ਲੋਕਾਂ ਨੂੰ ਜਦੋਂ ਮਾਰਗਦਰਸ਼ਨ ਆ ਗਿਆ, ਤਾਂ ਉਹਨਾਂ ਨੂੰ ਈਮਾਨ ਲਿਆਉਣ ਤੋਂ ਕਿਸ ਚੀਜ਼ ਨੇ ਰੋਕਿਆ? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- ਉਹਨਾਂ ਨੇ ਅੱਲਾਹ ਦੇ ਭਾਈਵਾਲ ਬਣਾ ਲਏ, ਤਾਂ ਕਿ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਭਟਕਾਉਣ। ਆਖ: ਮਜ਼ੇ ਕਰੋ। (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- ਉਹਨਾਂ ਨੂੰ ਹੈਰਾਨੀ ਹੋਈ ਕਿ ਉਹਨਾਂ ਵਿੱਚੋਂ ਹੀ ਇੱਕ ਸੁਚੇਤ ਕਰਨ ਵਾਲਾ ਉਹਨਾਂ ਕੋਲ ਆਇਆ, ਅਤੇ ਕਾਫ਼ਿਰਾਂ ਨੇ ਆਖਿਆ: ਇਹ। (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- ਬੇਸ਼ੱਕ ਤੁਹਾਡਾ ਰੱਬ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਕਿ ਕੌਣ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਭਟਕ ਗਿਆ ਹੈ। (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- ਉਸ ਵਿਅਕਤੀ ਵਰਗਾ, ਜੋ ਆਪਣਾ ਮਾਲ ਲੋਕਾਂ ਨੂੰ ਦਿਖਾਉਣ ਲਈ ਖ਼ਰਚ ਕਰਦਾ ਹੈ ਅਤੇ ਅੱਲਾਹ ਉੱਤੇ ਈਮਾਨ ਨਹੀਂ ਰੱਖਦਾ। (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- ਜੋ ਕੁਝ ਅਸੀਂ ਤੁਹਾਨੂੰ ਦਿੱਤਾ ਹੈ, ਉਸ ਵਿੱਚੋਂ ਉਸ (ਦਿਨ) ਦੇ ਆਉਣ ਤੋਂ ਪਹਿਲਾਂ ਖ਼ਰਚ ਕਰੋ। (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- ਉਸ ਨੇ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਜੋ ਕੁਝ ਹੈ, ਸਭ ਤੁਹਾਡੇ ਅਧੀਨ ਕਰ ਦਿੱਤਾ ਹੈ। (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- ਅਸੀਂ ਤਾਂ ਉਸ ਚੀਜ਼ ਬਾਰੇ ਸ਼ੱਕ ਵਿੱਚ ਹਾਂ, ਜਿਸ ਵੱਲ ਤੁਸੀਂ ਸਾਨੂੰ ਬੁਲਾਉਂਦੇ ਹੋ। (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- ਬੇਸ਼ੱਕ ਤੁਹਾਡਾ ਰੱਬ ਜਿਸ ਨੂੰ ਚਾਹੁੰਦਾ ਹੈ, ਰੋਜ਼ੀ ਖੁੱਲ੍ਹੀ ਕਰ ਦਿੰਦਾ ਹੈ ਅਤੇ ਤੰਗ ਵੀ ਕਰ ਦਿੰਦਾ ਹੈ। ਬੇਸ਼ੱਕ ਉਹ। (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- ਆਕਾਸ਼ਾਂ, ਧਰਤੀ ਅਤੇ ਉਹਨਾਂ ਦੇ ਵਿੱਚਕਾਰ ਸਭ ਕੁਝ ਦਾ ਰੱਬ, ਜੇਕਰ ਤੁਸੀਂ ਯਕੀਨ ਰੱਖਣ ਵਾਲੇ ਹੋ। (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- ਅਸੀਂ ਅੱਲਾਹ ਉੱਤੇ ਈਮਾਨ ਲਿਆਂਦਾ ਅਤੇ ਜੋ ਸਾਡੇ ਵੱਲ ਉਤਾਰਿਆ ਗਿਆ ਅਤੇ ਜੋ (ਇਬਰਾਹੀਮ, ਇਸਮਾਈਲ, ਇਸਹਾਕ, ਯਾਕੂਬ ਅਤੇ ਉਹਨਾਂ ਦੀ ਔਲਾਦ ਵੱਲ) ਉਤਾਰਿਆ ਗਿਆ। (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- ਜ਼ਾਲਮਾਂ ਨੂੰ ਭਿਆਨਕ ਚੀਕ ਨੇ ਫੜ ਲਿਆ, ਅਤੇ ਉਹ ਆਪਣੇ ਘਰਾਂ ਵਿੱਚ ਔਧੇ ਮੂੰਹ ਡਿੱਗੇ ਰਹੇ। (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- ਉਹ ਔਰਤਾਂ ਆਪਣੇ ਬਾਰੇ ਜੋ ਕਰਦੀਆਂ ਹਨ, ਉਸ ਵਿੱਚ ਤੁਹਾਡੇ ਉੱਤੇ ਕੋਈ ਗੁਨਾਹ ਨਹੀਂ। (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- ਤੁਹਾਡਾ ਰੱਬ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ ਕਿ ਕੌਣ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਭਟਕ ਗਿਆ ਹੈ, ਅਤੇ ਉਹ। (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- ਆਪਣੇ ਹੁਕਮ ਨਾਲ ਰੂਹ (ਵਹੀ) ਨੂੰ ਆਪਣੇ ਬੰਦਿਆਂ ਵਿੱਚੋਂ ਜਿਸ ਉੱਤੇ ਚਾਹੁੰਦਾ ਹੈ, ਉਤਾਰਦਾ ਹੈ। (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- ਅਸੀਂ ਮਰੀਅਮ ਦੇ ਪੁੱਤਰ ਈਸਾ ਨੂੰ ਸਪੱਸ਼ਟ ਨਿਸ਼ਾਨੀਆਂ ਦਿੱਤੀਆਂ ਅਤੇ ਪਵਿੱਤਰ ਰੂਹ ਰਾਹੀਂ ਉਸ ਨੂੰ ਮਜ਼ਬੂਤ ਕੀਤਾ। (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- ਤਾਂ ਕਿ ਕਿਆਮਤ ਦੇ ਦਿਨ ਉਹਨਾਂ ਦੇ ਵਿੱਚ, ਜਿਸ ਵਿੱਚ ਉਹ ਮਤਭੇਦ ਕਰਦੇ ਸਨ, ਫੈਸਲਾ ਕਰੇ। (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- ਅਸੀਂ ਉਸ (ਸ਼ਹਿਰ) ਦੇ ਉੱਪਰਲੇ ਹਿੱਸੇ ਨੂੰ ਥੱਲੇ ਕਰ ਦਿੱਤਾ ਅਤੇ ਉਹਨਾਂ ਉੱਤੇ ਪੱਕੀਆਂ ਮਿੱਟੀ ਦੇ ਪੱਥਰਾਂ ਦੀ ਵਰਖਾ ਕੀਤੀ। (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- ਉਹਨਾਂ ਲਈ ਬਰਾਬਰ ਹੈ, ਭਾਵੇਂ ਤੁਸੀਂ ਉਹਨਾਂ ਨੂੰ ਡਰਾਓ ਜਾਂ ਨਾ ਡਰਾਓ, ਉਹ ਈਮਾਨ ਨਹੀਂ ਲਿਆਉਣਗੇ। (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- ਲੋਕਾਂ ਨੂੰ ਛੱਡ ਕੇ, ਜੇਕਰ ਤੁਸੀਂ ਸੱਚੇ ਹੋ, ਤਾਂ ਮੌਤ ਦੀ ਇੱਛਾ ਕਰੋ। (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- ਅੱਲਾਹ ਦੀ (ਬੰਦਗੀ ਕਰੋ), ਉਸ ਤੋਂ ਬਿਨਾਂ ਤੁਹਾਡਾ ਕੋਈ ਮਾਬੂਦ ਨਹੀਂ। ਕੀ ਤੁਸੀਂ ਨਹੀਂ ਡਰਦੇ? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- ਅਸੀਂ ਉਹਨਾਂ ਨੂੰ ਜਿਸ ਚੀਜ਼ ਦੀ ਧਮਕੀ ਦਿੰਦੇ ਹਾਂ, ਉਸ ਦਾ ਕੁਝ ਹਿੱਸਾ ਤੁਹਾਨੂੰ ਦਿਖਾ ਦੇਈਏ, ਜਾਂ ਤੁਹਾਨੂੰ ਮੌਤ ਦੇ ਦੇਈਏ, ਉਹਨਾਂ ਦਾ ਮੁੜਨਾ ਤਾਂ ਸਾਡੇ ਵੱਲ ਹੀ ਹੈ। (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- ਉਹਨਾਂ ਨੇ ਆਖਿਆ: ਕੀ ਜਦੋਂ ਅਸੀਂ ਮਰ ਕੇ ਮਿੱਟੀ ਅਤੇ ਹੱਡੀਆਂ ਹੋ ਜਾਵਾਂਗੇ, ਤਾਂ ਕੀ ਅਸੀਂ ਮੁੜ ਜੀਉਂਦੇ ਕੀਤੇ ਜਾਵਾਂਗੇ? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- ਬੇਸ਼ੱਕ ਕਿਰਪਾ ਅੱਲਾਹ ਦੇ ਹੱਥ ਵਿੱਚ ਹੈ, ਉਹ ਜਿਸ ਨੂੰ ਚਾਹੁੰਦਾ ਹੈ, ਦੇ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਅੱਲਾਹ। (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- ਅਤੇ ਤੁਸੀਂ ਲੁਕਵੇਂ ਅਤੇ ਖੁੱਲ੍ਹੇ ਦੇ ਜਾਣਨ ਵਾਲੇ ਵੱਲ ਮੋੜੇ ਜਾਓਗੇ, ਫਿਰ ਉਹ ਤੁਹਾਨੂੰ ਦੱਸੇਗਾ ਜੋ ਕੁਝ ਤੁਸੀਂ ਕਰਦੇ ਸੀ। (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- ਹੇ ਈਮਾਨ ਵਾਲਿਓ! ਅੱਲਾਹ ਦੀ ਉਸ ਕਿਰਪਾ ਨੂੰ ਯਾਦ ਕਰੋ, ਜਦੋਂ। (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- ਅਸੀਂ ਤੁਹਾਡੇ ਤੋਂ ਪਹਿਲਾਂ ਵੀ ਸਿਰਫ਼ ਮਰਦਾਂ ਨੂੰ ਹੀ ਰਸੂਲ ਬਣਾ ਕੇ ਭੇਜਿਆ, ਜਿਨ੍ਹਾਂ ਵੱਲ ਅਸੀਂ ਵਹੀ ਭੇਜਦੇ ਸੀ। (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- ਉਹ ਉਸ ਦੇ ਗੁਨਾਹਾਂ ਨੂੰ ਮੁਆਫ਼ ਕਰੇਗਾ ਅਤੇ ਉਸ ਨੂੰ ਅਜਿਹੇ ਬਾਗ਼ਾਂ ਵਿੱਚ ਦਾਖ਼ਲ ਕਰੇਗਾ, ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ। (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- ਜਿਹੜਾ ਬੀਮਾਰ ਹੋਵੇ ਜਾਂ ਸਫ਼ਰ ਵਿੱਚ ਹੋਵੇ, ਤਾਂ ਦੂਜੇ ਦਿਨਾਂ ਵਿੱਚ ਗਿਣਤੀ ਪੂਰੀ ਕਰੇ। (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- ਉਹ ਸਿਰਫ਼ ਅੰਦਾਜ਼ੇ ਅਤੇ ਅਟਕਲਾਂ ਦੇ ਪਿੱਛੇ ਲੱਗੇ ਹਨ। (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- ਜਿਹੜਾ ਅੱਲਾਹ ਅਤੇ ਅਖ਼ਿਰਤ ਦੇ ਦਿਨ ਦੀ ਆਸ ਰੱਖਦਾ ਹੈ, ਉਸ ਲਈ ਚੰਗਾ ਨਮੂਨਾ ਹੈ। (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- ਅਸੀਂ ਆਕਾਸ਼ਾਂ, ਧਰਤੀ ਅਤੇ ਉਹਨਾਂ ਦੇ ਵਿੱਚਕਾਰ ਸਭ ਕੁਝ ਸਿਰਫ਼ ਸੱਚ ਨਾਲ ਪੈਦਾ ਕੀਤਾ ਹੈ। (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- ਆਪਣਾ ਹੱਥ ਆਪਣੀ ਕੱਛ ਵਿੱਚ ਪਾਓ, ਉਹ ਬਿਨਾਂ ਕਿਸੇ ਰੋਗ ਦੇ ਚਮਕਦਾ ਹੋਇਆ ਬਾਹਰ ਨਿਕਲੇਗਾ। (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- ਉਹ ਆਪਣੀ ਰਹਿਮਤ ਨਾਲ ਜਿਸ ਨੂੰ ਚਾਹੁੰਦਾ ਹੈ, ਖ਼ਾਸ ਕਰ ਲੈਂਦਾ ਹੈ, ਅਤੇ ਅੱਲਾਹ ਵੱਡਾ ਕਿਰਪਾਵਾਨ ਹੈ। (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- ਕੀ ਤੁਸੀਂ ਨਹੀਂ ਜਾਣਦੇ ਕਿ ਅੱਲਾਹ ਲਈ ਹੀ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਦੀ ਬਾਦਸ਼ਾਹੀ ਹੈ? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- ਤੁਸੀਂ ਆਪਣੇ ਲਈ ਜੋ ਭਲਾਈ ਅੱਗੇ ਭੇਜੋਗੇ, ਉਸ ਨੂੰ ਅੱਲਾਹ ਕੋਲ ਪਾਓਗੇ। (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- ਤੁਸੀਂ ਜਿਥੋਂ ਵੀ ਨਿਕਲੋ, ਆਪਣਾ ਮੂੰਹ ਮਸਜਿਦ-ਅਲ-ਹਰਾਮ ਵੱਲ ਫੇਰੋ। (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- ਤੁਹਾਡੇ ਤੋਂ ਪਹਿਲਾਂ ਦੇ ਲੋਕ (ਗੁਜ਼ਰ ਚੁੱਕੇ ਹਨ), ਅਤੇ ਤੁਸੀਂ ਅੱਲਾਹ ਦੀ ਸੁੰਨਤ ਵਿੱਚ ਕੋਈ ਤਬਦੀਲੀ ਨਹੀਂ ਪਾਓਗੇ। (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- ਉਹੀ ਹੈ ਜਿਸ ਦੇ ਲਈ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਸਭ ਕੁਝ ਹੈ। (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- ਕੋਈ ਔਰਤ ਗਰਭ ਨਹੀਂ ਰੱਖਦੀ ਅਤੇ ਨਾ ਜਣਨ ਦਿੰਦੀ ਹੈ, ਪਰੰਤੂ ਉਸ ਦੇ ਗਿਆਨ ਨਾਲ। (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- ਉਸ ਨੇ ਰਾਤ, ਸੂਰਜ ਅਤੇ ਚੰਦ ਨੂੰ ਤੁਹਾਡੇ ਅਧੀਨ ਕੀਤਾ; ਹਰ ਇੱਕ ਆਪਣੀ ਨਿਸ਼ਚਿਤ ਮਿਆਦ ਤੱਕ ਚੱਲ ਰਿਹਾ ਹੈ। (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ, ਉਹ ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ, ਅਤੇ ਇਹ ਹੈ ਇਨਾਮ। (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- ਉਸ ਨੇ ਆਖਿਆ: ਨਹੀਂ, ਸਗੋਂ ਤੁਹਾਡੇ ਮਨਾਂ ਨੇ ਤੁਹਾਡੇ ਲਈ ਇੱਕ ਕੰਮ ਨੂੰ ਸੁੰਦਰ ਬਣਾ ਦਿੱਤਾ ਹੈ; ਸੋ ਧੀਰਜ ਚੰਗਾ ਹੈ। (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- ਜੋ ਕੁਝ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਵਿੱਚ ਹੈ, ਅਤੇ ਬੇਸ਼ੱਕ ਅੱਲਾਹ। (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- ਉਹਨਾਂ ਕੋਲ ਜੋ ਰਸੂਲ ਆਇਆ, ਉਹ ਉਸ ਦਾ ਮਜ਼ਾਕ ਉਡਾਉਂਦੇ ਸਨ। (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- ਉਹਨਾਂ ਨੇ ਆਖਿਆ: ਹੇ ਮੂਸਾ! ਜਾਂ ਤੁਸੀਂ ਸੁੱਟੋ ਜਾਂ ਅਸੀਂ ਸੁੱਟੀਏ? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- ਉਹੀ ਹੈ ਜੋ ਤੁਹਾਨੂੰ ਮੌਤ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਤੁਹਾਡੇ ਵਿੱਚੋਂ ਕਿਸੇ ਨੂੰ ਬਹੁਤ ਬੁਢਾਪੇ ਵੱਲ ਮੋੜ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ। (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- ਉਹਨਾਂ ਲਈ ਆਪਣੇ ਰੱਬ ਕੋਲ ਅਜਿਹੇ ਬਾਗ਼ ਹਨ, ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ, ਉਹ ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ। (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- ਅਤੇ ਅਸੀਂ ਉਹਨਾਂ ਦੇ ਦਿਲਾਂ ਉੱਤੇ ਪਰਦੇ ਪਾ ਦਿੱਤੇ ਹਨ, ਤਾਂ ਜੋ ਉਹ ਇਸ ਨੂੰ ਨਾ ਸਮਝਣ, ਅਤੇ ਉਹਨਾਂ ਦੇ ਕੰਨਾਂ ਵਿੱਚ ਭਾਰੀਪਣ। (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- ਅੱਲਾਹ ਦਾ ਵਾਅਦਾ ਸੱਚਾ ਹੈ, ਪਰ ਉਹਨਾਂ ਵਿੱਚੋਂ ਬਹੁਤੇ ਜਾਣਦੇ ਨਹੀਂ ਹਨ। (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- ਇਹ ਇਸ ਲਈ ਹੈ ਕਿ ਉਹਨਾਂ ਨੇ ਅੱਲਾਹ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ ਦਾ ਵਿਰੋਧ ਕੀਤਾ; ਅਤੇ ਜਿਹੜਾ ਅੱਲਾਹ ਦਾ ਵਿਰੋਧ ਕਰਦਾ ਹੈ। (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- ਅਤੇ ਜਿਸ ਦਿਨ ਉਹ ਉਹਨਾਂ ਨੂੰ ਬੁਲਾਵੇਗਾ ਅਤੇ ਆਖੇਗਾ: ਮੇਰੇ ਉਹ ਭਾਈਵਾਲ ਕਿੱਥੇ ਹਨ, ਜਿਨ੍ਹਾਂ ਬਾਰੇ ਤੁਸੀਂ ਦਾਅਵਾ ਕਰਦੇ ਸੀ? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- ਕੀ ਉਹਨਾਂ ਨੇ ਨਹੀਂ ਵੇਖਿਆ ਕਿ ਅੱਲਾਹ, ਜਿਸ ਨੇ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਨੂੰ ਪੈਦਾ ਕੀਤਾ ਹੈ, ਉਹ ਉਹਨਾਂ ਵਰਗਾ ਪੈਦਾ ਕਰ ਸਕਦਾ ਹੈ? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (ਉਹ) ਜਿਸ ਨੇ ਤੁਹਾਨੂੰ ਮਿੱਟੀ ਤੋਂ, ਫਿਰ ਵੀਰਜ ਤੋਂ, ਫਿਰ. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- ਉਹ ਆਖਦੇ: ਸਾਡੇ ਰੱਬ! ਜੇਕਰ ਤੂੰ ਸਾਡੇ ਕੋਲ ਕੋਈ ਰਸੂਲ ਭੇਜਿਆ ਹੁੰਦਾ, ਤਾਂ ਅਸੀਂ ਤੇਰੀਆਂ ਨਿਸ਼ਾਨੀਆਂ ਦੀ ਪੈਰਵੀ ਕਰਦੇ। (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- ਫਿਰ ਉਹਨਾਂ ਦਾ ਮੁੜਨਾ ਆਪਣੇ ਰੱਬ ਵੱਲ ਹੈ, ਫਿਰ ਉਹ ਉਹਨਾਂ ਨੂੰ ਦੱਸੇਗਾ ਜੋ ਉਹ ਕਰਦੇ ਸਨ। (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- ਉਹਨਾਂ ਨੂੰ ਇਸ ਦਾ ਕੋਈ ਗਿਆਨ ਨਹੀਂ; ਉਹ ਸਿਰਫ਼ ਅੰਦਾਜ਼ੇ ਦੇ ਪਿੱਛੇ ਲੱਗੇ ਹਨ। (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- ਅਸੀਂ ਆਪਣੇ ਬਾਪ-ਦਾਦਿਆਂ ਨੂੰ ਇੱਕ ਧਰਮ ਉੱਤੇ ਪਾਇਆ, ਅਤੇ ਅਸੀਂ ਉਹਨਾਂ ਦੇ ਨਕਸ਼ੇ-ਕਦਮ ਉੱਤੇ ਚੱਲ ਰਹੇ ਹਾਂ। (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- ਜਿਨ੍ਹਾਂ ਨੂੰ ਕਿਤਾਬ ਦਿੱਤੀ ਗਈ, ਉਹਨਾਂ ਨੇ ਗਿਆਨ ਆਉਣ ਮਗਰੋਂ ਹੀ (ਮਤਭੇਦ ਕੀਤਾ)। (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- ਜਦੋਂ ਇਬਰਾਹੀਮ ਨੇ ਆਖਿਆ: ਮੇਰੇ ਰੱਬ! ਇਸ ਸ਼ਹਿਰ ਨੂੰ ਸੁਰੱਖਿਅਤ ਬਣਾ। (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- ਉਸ ਨੇ ਤੁਹਾਨੂੰ ਕੰਨ, ਅੱਖਾਂ ਅਤੇ ਦਿਲ ਦਿੱਤੇ; ਤੁਸੀਂ ਬਹੁਤ ਘੱਟ ਸ਼ੁਕਰ ਕਰਦੇ ਹੋ। (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- ਜਿਹੜੇ ਲੋਕ ਅੱਲਾਹ ਦੀਆਂ ਨਿਸ਼ਾਨੀਆਂ ਬਾਰੇ ਬਿਨਾਂ ਕਿਸੇ ਸਨਦ (ਪ੍ਰਮਾਣ) ਦੇ ਝਗੜਾ ਕਰਦੇ ਹਨ, ਜੋ ਉਹਨਾਂ ਕੋਲ ਆਈ ਹੋਵੇ। (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- ਸੋ ਇਬਰਾਹੀਮ ਦੇ ਸੱਚੇ ਧਰਮ ਦੀ ਪੈਰਵੀ ਕਰੋ, ਜੋ ਇੱਕ-ਰੁਖ਼ਾ ਸੀ, ਅਤੇ ਉਹ ਮੁਸ਼ਰਿਕਾਂ ਵਿੱਚੋਂ ਨਹੀਂ ਸੀ। (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- ਅਤੇ ਜਦੋਂ ਅਸੀਂ ਤੁਹਾਨੂੰ ਫ਼ਿਰਔਨ ਦੇ ਲੋਕਾਂ ਤੋਂ ਛੁਡਾਇਆ, ਜਿਹੜੇ ਤੁਹਾਨੂੰ ਸਖ਼ਤ ਅਜ਼ਾਬ ਦਿੰਦੇ ਸਨ। (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- ਇਹੀ ਸਿੱਧਾ ਧਰਮ ਹੈ, ਪਰ ਬਹੁਤੇ ਲੋਕ ਨਹੀਂ ਜਾਣਦੇ। (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- ਕੀ ਤੁਸੀਂ ਨਹੀਂ ਵੇਖਦੇ ਕਿ ਅੱਲਾਹ ਨੇ ਜੋ ਕੁਝ ਆਕਾਸ਼ਾਂ ਵਿੱਚ ਹੈ, ਤੁਹਾਡੇ ਅਧੀਨ ਕਰ ਦਿੱਤਾ ਹੈ? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- ਕਾਫ਼ਿਰਾਂ ਨੇ ਆਖਿਆ: ਇਹ ਤਾਂ ਸਪੱਸ਼ਟ ਜਾਦੂ ਹੈ। (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- ਜਦੋਂ ਉਹਨਾਂ ਨੂੰ ਸਾਡੀਆਂ ਸਪੱਸ਼ਟ ਆਇਤਾਂ ਸੁਣਾਈਆਂ ਜਾਂਦੀਆਂ ਹਨ, ਤਾਂ ਕਾਫ਼ਿਰ ਆਖਦੇ ਹਨ। (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- ਹਮੇਸ਼ਾ ਵਾਲੇ ਬਾਗ਼, ਜਿਨ੍ਹਾਂ ਦੇ ਹੇਠੋਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ, ਉਹ ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ। (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- ਉਹ ਜੋ ਚਾਹੁੰਦਾ ਹੈ, ਪੈਦਾ ਕਰਦਾ ਹੈ; ਬੇਸ਼ੱਕ ਅੱਲਾਹ ਹਰ ਚੀਜ਼ ਉੱਤੇ ਸਮਰੱਥ ਹੈ। (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- ਤਾਂ ਜੋ ਉਹ ਤੁਹਾਡੇ ਗੁਨਾਹਾਂ ਨੂੰ ਮੁਆਫ਼ ਕਰੇ ਅਤੇ ਤੁਹਾਨੂੰ ਇੱਕ ਨਿਸ਼ਚਿਤ ਸਮੇਂ ਤੱਕ ਮੁਹਲਤ ਦੇਵੇ। (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- ਕੀ ਤੁਸੀਂ ਸਾਨੂੰ ਉਸ ਚੀਜ਼ ਤੋਂ ਰੋਕਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਜਿਸ ਦੀ ਸਾਡੇ ਬਾਪ-ਦਾਦਾ ਬੰਦਗੀ ਕਰਦੇ ਸਨ? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- ਜਦੋਂ ਤੁਹਾਡੇ ਰੱਬ ਨੇ ਫ਼ਰਿਸ਼ਤਿਆਂ ਨੂੰ ਆਖਿਆ: ਮੈਂ ਮਿੱਟੀ ਤੋਂ ਇੱਕ ਮਨੁੱਖ ਪੈਦਾ ਕਰਨ ਵਾਲਾ ਹਾਂ। (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- ਉਹੀ ਹੈ ਜੋ ਆਪਣੀ ਰਹਿਮਤ ਤੋਂ ਪਹਿਲਾਂ ਹਵਾਵਾਂ ਨੂੰ ਖੁਸ਼ਖਬਰੀ ਦੇਣ ਵਾਲੀਆਂ ਭੇਜਦਾ ਹੈ। (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- ਆਖ: ਧਰਤੀ ਉੱਤੇ ਚੱਲੋ-ਫਿਰੋ ਅਤੇ ਵੇਖੋ ਕਿ ਅੰਜਾਮ ਕਿਵੇਂ ਹੋਇਆ। (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਦੀ ਪੈਦਾਇਸ਼ ਵਿੱਚ, ਅਤੇ ਰਾਤ-ਦਿਨ ਦੇ ਫੇਰਬਦਲ ਵਿੱਚ (ਨਿਸ਼ਾਨੀਆਂ ਹਨ)। (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- ਕੌਣ ਹੈ ਜੋ ਅੱਲਾਹ ਨੂੰ ਚੰਗਾ ਕਰਜ਼ ਦੇਵੇ, ਤਾਂ ਜੋ ਉਹ ਉਸ ਨੂੰ ਕਈ ਗੁਣਾ ਵਧਾ ਕੇ ਦੇਵੇ? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- ਸੋ ਉਹਨਾਂ ਦੇ ਵਿੱਚ ਅੱਲਾਹ ਦੇ ਉਤਾਰੇ (ਕਾਨੂੰਨ) ਅਨੁਸਾਰ ਫੈਸਲਾ ਕਰੋ, ਅਤੇ ਉਹਨਾਂ ਦੀਆਂ ਖ਼ਾਹਿਸ਼ਾਂ ਦੇ ਪਿੱਛੇ ਨਾ ਲੱਗੋ। (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- ਕੀ ਉਹ ਫ਼ਰਿਸ਼ਤੇ ਉਹਨਾਂ ਕੋਲ ਆਉਣ, ਜਾਂ ਤੁਹਾਡੇ ਰੱਬ ਦਾ ਹੁਕਮ ਆਉਣ, ਤੋਂ ਬਿਨਾਂ ਕਿਸੇ ਹੋਰ ਚੀਜ਼ ਦੀ ਉਡੀਕ ਕਰ ਰਹੇ ਹਨ? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- ਬੇਸ਼ੱਕ ਜਿਹੜੇ ਲੋਕ ਅੱਲਾਹ ਉੱਤੇ ਝੂਠ ਘੜਦੇ ਹਨ, ਉਹ ਸਫ਼ਲ ਨਹੀਂ ਹੋਣਗੇ। (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ਜਿਵੇਂ ਫ਼ਿਰਔਨ ਦੇ ਲੋਕ ਅਤੇ ਉਹਨਾਂ ਤੋਂ ਪਹਿਲਾਂ ਦੇ ਲੋਕਾਂ ਦਾ ਹਾਲ ਸੀ; ਉਹਨਾਂ ਨੇ ਸਾਡੀਆਂ ਆਇਤਾਂ ਨੂੰ ਝੂਠਲਾਇਆ। (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- ਅਤੇ ਉਹ ਈਮਾਨ ਵਾਲਿਆਂ ਨੂੰ ਜਿਹੜੇ ਚੰਗੇ ਕੰਮ ਕਰਦੇ ਹਨ, ਖੁਸ਼ਖਬਰੀ ਦਿੰਦਾ ਹੈ ਕਿ ਉਹਨਾਂ ਲਈ ਇਨਾਮ ਹੈ। (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- ਅੱਲਾਹ ਆਪਣੇ ਬੰਦਿਆਂ ਵਿੱਚੋਂ ਜਿਸ ਨੂੰ ਚਾਹੁੰਦਾ ਹੈ, ਰੋਜ਼ੀ ਖੁੱਲ੍ਹੀ ਕਰ ਦਿੰਦਾ ਹੈ ਅਤੇ ਤੰਗ ਵੀ ਕਰ ਦਿੰਦਾ ਹੈ। (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- ਅਤੇ ਤੁਸੀਂ ਲੁਕਵੇਂ ਅਤੇ ਖੁੱਲ੍ਹੇ ਦੇ ਜਾਣਨ ਵਾਲੇ ਵੱਲ ਮੋੜੇ ਜਾਓਗੇ, ਫਿਰ ਉਹ ਤੁਹਾਨੂੰ ਦੱਸੇਗਾ ਜੋ ਕੁਝ ਤੁਸੀਂ ਕਰਦੇ ਸੀ। (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- ਅਤੇ ਖੂਨ ਦੇ ਰਿਸ਼ਤੇਦਾਰ, ਉਹਨਾਂ ਵਿੱਚੋਂ ਕੁਝ ਦੂਜਿਆਂ ਨਾਲੋਂ ਅੱਲਾਹ ਦੀ ਕਿਤਾਬ ਵਿੱਚ ਵਧੇਰੇ ਹੱਕਦਾਰ ਹਨ। (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — ਲਾਜ਼ਮੀ (ਕਰਨਾ ਲਾਜ਼ਮੀ; ਛੱਡਣਾ ਗੁਨਾਹ)
- mustahabb / mandub (مستحب / مندوب) — ਸਿਫ਼ਾਰਸ਼ੀ (ਕਰਨ 'ਤੇ ਨੇਕੀ, ਨਾ ਕਰਨ 'ਤੇ ਕੋਈ ਗੁਨਾਹ ਨਹੀਂ)
- mubah (مباح) — ਜਾਇਜ਼ / ਮੁਬਾਹ (ਨਾ ਨੇਕੀ ਨਾ ਗੁਨਾਹ)
- makruh (مكروه) — ਨਾਪਸੰਦੀਦਾ (ਹੌਲਾ ਕਰਨ ਤੋਂ ਗੁਰੇਜ਼, ਪਰ ਗੁਨਾਹ ਨਹੀਂ)
- haram (حرام) — ਵਰਜਿਤ (ਕਰਨਾ ਗੁਨਾਹ)
- halal (حلال, ਜਾਇਜ਼ / ਕਾਨੂੰਨੀ) — ਮੁਬਾਹ ਅਤੇ ਮੁਸਤਹੱਬ ਦੋਵੇਂ ਸ਼ਾਮਲ — ਕੋਈ ਵੀ ਚੀਜ਼ ਜੋ ਵਰਜਿਤ ਨਾ ਹੋਵੇ
- ਸਿਰਫ਼ ਅੱਲ੍ਹਾ ਦੀ ਇਬਾਦਤ ਕਰੋ ਅਤੇ ਉਸ ਤੋਂ ਮਦਦ ਮੰਗੋ। 1:5
- ਸਿਰਫ਼ ਅੱਲ੍ਹਾ ਦੀ ਇਬਾਦਤ ਕਰੋ 2:21
- ਅੱਲ੍ਹਾ ਨਾਲ ਕਿਸੇ ਨੂੰ ਸ਼ਰੀਕ ਨਾ ਬਣਾਓ 2:22
- ਅੱਲ੍ਹਾ ਉਹ ਹੈ ਜੋ ਮਾਫ਼ ਕਰਦਾ ਹੈ (ਤੌਬਾ ਕਬੂਲ ਕਰਦਾ ਹੈ), ਉਸ ਨੇ ਆਦਮ (عَلَيْهِ ٱلسَّلَامُ) ਦੀ ਤੌਬਾ ਕਬੂਲ ਕੀਤੀ। 2:37
- ਸੱਚ ਨੂੰ ਝੂਠ ਨਾਲ ਨਾ ਰਲਾਓ, ਨਾ ਹੀ ਸੱਚ ਨੂੰ ਛਿਪਾਓ। 2:42
- ਨਮਾਜ਼ ਕਾਇਮ ਕਰੋ ਅਤੇ ਜ਼ਕਾਤ ਦਿਓ। 2:43
- ਦੂਜਿਆਂ ਨੂੰ ਨੇਕੀ ਦਾ ਹੁਕਮ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪ ਉਸ 'ਤੇ ਅਮਲ ਕਰੋ 2:44
- ਹਰ ਮਾਮਲੇ ਵਿਚ ਅੱਲ੍ਹਾ ਤੋਂ ਮਦਦ ਮੰਗੋ 2:45
- ਫ਼ਸਾਦ ਵਿਚ ਨਾ ਪਓ ਅਤੇ ਨਾ ਫੈਲਾਓ 2:60
- ਲੋਕਾਂ ਨੂੰ ਪੂਜਾ ਘਰਾਂ ਵਿਚ ਜਾਣ ਤੋਂ ਨਾ ਰੋਕੋ 2:114
- ਮਸਜਿਦ ਦੀ ਇੱਜ਼ਤ ਕਰੋ। ਆਪਣੀਆਂ ਨਮਾਜ਼ਾਂ ਦੀਆਂ ਥਾਵਾਂ ਨੂੰ ਸਾਫ਼ ਰੱਖੋ 2:125
- ਅੱਲ੍ਹਾ ਨੂੰ ਯਾਦ ਰੱਖੋ (ਨਮਾਜ਼, ਤਸਬੀਹ ਆਦਿ ਨਾਲ), ਉਹ ਤੁਹਾਨੂੰ ਯਾਦ ਰੱਖੇਗਾ, ਅਤੇ ਉਸ ਦਾ ਸ਼ੁਕਰ ਅਦਾ ਕਰੋ। 2:152
- ਮੁਸੀਬਤ ਵਿਚ ਸਬਰ ਕਰੋ 2:153
- ਸ਼ੈਤਾਨ ਦੇ ਕਦਮਾਂ 'ਤੇ ਨਾ ਚੱਲੋ ਜੋ ਖੁੱਲ੍ਹਾ ਦੁਸ਼ਮਣ ਹੈ। 2:168
- ਕਿਸੇ ਦੀ ਅੰਨ੍ਹੀ ਤਕਲੀਦ ਨਾ ਕਰੋ 2:170
- ਸਭ ਅਮਾਨਤਾਂ ਨੂੰ ਨਿਭਾਓ। ਆਪਣੇ ਧਾਰਮਿਕ ਫ਼ਰਜ਼ ਇਮਾਨਦਾਰੀ ਨਾਲ ਅਦਾ ਕਰੋ। ਆਪਣੀਆਂ ਸੌਗੰਆਂ ਅਤੇ ਇਕਰਾਰਨਾਮੇ ਪੂਰੇ ਕਰੋ। ਵਾਅਦੇ ਨਿਭਾਓ, ਖਾਸ ਕਰਕੇ ਅੱਲ੍ਹਾ ਨਾਲ ਕੀਤੇ। ਲੋੜਵੰਦਾਂ ਦੀ ਮਦਦ ਕਰੋ ਅਤੇ ਮੁਸ਼ਕਲਾਂ ਘਟਾਓ। ਅੱਲ੍ਹਾ ਦੀ ਨਾਰਾਜ਼ਗੀ ਵਾਲੇ ਗੁਨਾਹਾਂ ਤੋਂ ਬਚੋ। ਮਾਣ ਨਾ ਕਰੋ ਕਿ ਤੁਸੀਂ ਜ਼ੁਲਮ ਕਰੋ 2:177
- ਕ਼ਿਸਾਸ (ਬਰਾਬਰੀ ਦਾ ਕਾਨੂੰਨ) ਵਿਚ ਤੁਹਾਡੇ ਲਈ ਜੀਵਨ ਹੈ। 2:179
- ਰਮਜ਼ਾਨ ਦੇ ਮਹੀਨੇ ਵਿਚ ਰੋਜ਼ੇ ਰੱਖੋ। ਰੋਜ਼ੇ ਰੱਖੋ ਤਾਂ ਜੋ ਪਰਹੇਜ਼ਗਾਰ ਬਣੋ। 2:183
- ਕੁਰਆਨ ਨੂੰ ਰਹਿਨੁਮਾਈ ਦੇ ਆਖ਼ਰੀ ਸਰੋਤ ਵਜੋਂ ਮਾਣ ਦਿਓ 2:185
- ਆਪਸ ਵਿਚ ਇਕ-ਦੂਜੇ ਦਾ ਮਾਲ ਨਾਜਾਇਜ਼ ਤੌਰ 'ਤੇ ਨਾ ਖਾਓ, ਨਾ ਹੀ ਹਾਕਮਾਂ (ਜੱਜਾਂ) ਨੂੰ ਰਿਸ਼ਵਤ ਦਿਓ (ਆਪਣੇ ਕੇਸ ਪੇਸ਼ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ)। 2:188
- ਕਿਸੇ 'ਤੇ ਜ਼ੁਲਮ ਨਾ ਕਰੋ, ਚਾਹੇ ਬੋਲੀ ਵਿਚ ਜਾਂ ਕੰਮ ਵਿਚ। ਹਮੇਸ਼ਾ ਹਮਲਾਵਰ ਵਜੋਂ ਨਾ ਲੜੋ, ਸਗੋਂ ਸਿਰਫ਼ ਬਚਾਅ ਲਈ 2:190
- ਯਤੀਮਾਂ ਦੀ ਰੱਖਿਆ ਕਰੋ। ਯਤੀਮਾਂ ਦੇ ਮਾਲ ਵਿਚ ਇਮਾਨਦਾਰੀ ਨਾਲ ਕੰਮ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦਾ ਮਾਲ ਨਾ ਖਾਓ। 2:220
- ਤੌਬਾ ਕਰੋ ਅਤੇ ਅੱਲ੍ਹਾ ਤੋਂ ਮੁਆਫ਼ੀ ਮੰਗੋ। ਔਰਤਾਂ ਦੇ ਹੈਦ ਵਾਲੇ ਦਿਨਾਂ ਵਿਚ ਸੰਭੋਗ ਨਾ ਕਰੋ। ਪਵਿੱਤਰਤਾ (ਸਰੀਰਕ ਅਤੇ ਰੂਹਾਨੀ ਦੋਵੇਂ) ਬਣਾਈ ਰੱਖੋ 2:222
- ਆਪਣੇ ਪਰਿਵਾਰ ਪ੍ਰਤੀ ਆਪਣੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਨਿਭਾਓ 2:233
- ਆਗੂਆਂ ਦੀ ਚੋਣ ਉਨ੍ਹਾਂ ਦੀ ਕਾਬਲੀਅਤ ਦੇ ਆਧਾਰ 'ਤੇ ਕਰੋ 2:247
- ਧਰਮ ਬਾਰੇ ਕੋਈ ਜ਼ਬਰਦਸਤੀ ਨਾ ਕਰੋ 2:256
- ਮਾਲ ਖ਼ਰਚ ਕਰੋ ਖੈਰਾਤ ਵਿਚ। ਮਾਲ ਅਤੇ ਸਮਾਂ ਦੋਵੇਂ ਖੈਰਾਤ ਵਿਚ ਲਾਓ 2:261
- ਆਪਣੀ ਖੈਰਾਤ ਨੂੰ ਆਪਣੀ ਦਾਨਸ਼ੀ ਦਾ ਵਖਰਾਵਾ ਦਿਖਾ ਕੇ ਰੱਦ ਨਾ ਕਰੋ 2:264
- ਸ਼ੈਤਾਨ ਤੁਹਾਨੂੰ ਫ਼ਕੀਰੀ ਤੋਂ ਡਰਾਉਂਦਾ ਹੈ ਅਤੇ ਬਦਕਾਰੀ (ਫ਼ਾਹਿਸ਼ਾ) ਦਾ ਹੁਕਮ ਦਿੰਦਾ ਹੈ। 2:268
- ਲੋੜਵੰਦਾਂ ਨੂੰ ਲੱਭੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਮਦਦ ਕਰੋ 2:273
- ਸੂਦ ਜਾਂ ਵਿਆਜ ਵਿਚ ਨਾ ਪਓ। ਵਿਆਜ ਵਾਲਾ ਮਾਲ ਨਾ ਖਾਓ। ਸੂਦ (ਰਿਬਾ) ਨਾ ਖਾਓ। 2:275
- ਜੇਕਰ ਕਰਜ਼ਦਾਰ ਮੁਸ਼ਕਲ ਵਿਚ ਹੈ ਤਾਂ ਉਸ ਨੂੰ ਮੋਹਲਤ ਦਿਓ 2:280
- ਕਾਰੋਬਾਰੀ ਲੈਣ-ਦੇਣ ਵਿਚ ਆਪਣੀ ਗੱਲ 'ਤੇ ਕਾਇਮ ਰਹੋ। ਆਪਣੇ ਮਾਲੀ ਮਾਮਲਿਆਂ ਵਿਚ ਸੱਚੇ ਰਹੋ। ਸਾਰੇ ਇਕਰਾਰਨਾਮਿਆਂ ਵਿਚ ਇਮਾਨਦਾਰੀ ਨਾਲ ਕੰਮ ਕਰੋ। ਜਦੋਂ ਕਿਸੇ ਮਿਆਦ ਲਈ ਕਰਜ਼ ਦਾ ਇਕਰਾਰ ਕਰੋ ਤਾਂ ਉਸ ਨੂੰ ਲਿਖ ਲਓ। ਜਦੋਂ ਕੋਈ ਵਪਾਰਕ ਇਕਰਾਰ ਕਰੋ ਤਾਂ ਗਵਾਹ ਬਣਾਓ। 2:282
- ਸਭ ਅਮਾਨਤਾਂ ਨੂੰ ਨਿਭਾਓ 2:283
- ਉਤਾਰੀਆਂ ਗਈਆਂ ਕਿਤਾਬਾਂ ਅਤੇ ਸਾਰੇ ਨਬੀਆਂ 'ਤੇ ਈਮਾਨ ਲਿਆਓ 2:285
- ਅੱਲ੍ਹਾ ਕਿਸੇ ਜੀਵ 'ਤੇ ਉਸ ਦੀ ਸਮਰੱਥਾ ਤੋਂ ਵੱਧ ਬੋਝ ਨਹੀਂ ਪਾਉਂਦਾ। ਉਹ ਨੇਕੀ ਦਾ ਫਲ ਪਾਉਣਗੇ ਅਤੇ ਬੁਰਾਈ ਦਾ ਫਲ ਪਾਉਣਗੇ। ਅੱਲ੍ਹਾ ਕਿਸੇ 'ਤੇ ਉਸ ਦੀ ਸਮਰੱਥਾ ਤੋਂ ਵੱਧ ਬੋਝ ਨਹੀਂ ਪਾਉਂਦਾ; ਨਾ ਹੀ ਸਾਨੂੰ (ਆਪਸ 'ਤੇ) ਬੋਝ ਪਾਉਣਾ ਚਾਹੀਦਾ। ਮੁਸ਼ਕਲ ਵਿਚ ਅੱਲ੍ਹਾ ਦੀ ਯੋਜਨਾ 'ਤੇ ਭਰੋਸਾ ਰੱਖੋ 2:286
- ਜੋ ਵਾਅਦੇ ਨਿਭਾਉਂਦਾ ਹੈ ਅਤੇ ਅੱਲ੍ਹਾ ਤੋਂ ਬਹੁਤ ਡਰਦਾ ਹੈ, ਤਾਂ ਅੱਲ੍ਹਾ ਪਰਹੇਜ਼ਗਾਰਾਂ ਨੂੰ ਪਸੰਦ ਕਰਦਾ ਹੈ। 3:76
- ਹੱਜ (ਪਵਿੱਤਰ ਯਾਤਰਾ) ਕਰੋ ਜੇ ਤੁਸੀਂ ਸਮਰੱਥ ਹੋ 3:97
- ਆਪਸ ਵਿਚ ਵੰਡੇ ਨਾ ਬਣੋ 3:103
- ਭਲਾਈ ਦਾ ਹੁਕਮ ਕਰੋ ਅਤੇ ਬੁਰਾਈ ਤੋਂ ਰੋਕੋ। ਆਪਣੀ ਕੌਮ ਵਿਚ ਨੇਕੀ ਨੂੰ ਉਤਸ਼ਾਹਿਤ ਕਰੋ। ਲੋਕਾਂ ਨੂੰ ਅੱਲ੍ਹਾ ਦੀ ਯਾਦ ਵੱਲ ਬੁਲਾਓ 3:104
- ਮੋਮਿਨਾਂ ਨੂੰ ਸਿਰਫ਼ ਅੱਲ੍ਹਾ 'ਤੇ ਭਰੋਸਾ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ। 3:122
- ਸੂਦ (ਰਿਬਾ) ਨਾ ਖਾਓ। 3:130
- ਅੱਲ੍ਹਾ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ ਦੀ ਇਤਾਅਤ ਕਰੋ ਤਾਂ ਜੋ ਰਹਿਮਤ ਪਾਓ। 3:132
- ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਨੂੰ ਪਸੰਦ ਕਰਦਾ ਹੈ ਜੋ ਖੁਸ਼ਹਾਲੀ ਅਤੇ ਤੰਗੀ ਵਿਚ (ਅੱਲ੍ਹਾ ਦੀ ਰਾਹ ਵਿਚ) ਖ਼ਰਚ ਕਰਦੇ ਹਨ, ਗੁੱਸੇ ਨੂੰ ਕਾਬੂ ਕਰਦੇ ਹਨ ਅਤੇ ਲੋਕਾਂ ਨੂੰ ਮਾਫ਼ ਕਰਦੇ ਹਨ। 3:134
- ਗੁੱਸੇ ਨੂੰ ਕਾਬੂ ਕਰੋ। 3:134
- ਦੂਜਿਆਂ ਦੀਆਂ ਗ਼ਲਤੀਆਂ ਨੂੰ ਮਾਫ਼ ਕਰੋ 3:135
- ਬੋਲੀ ਵਿਚ ਰੁੱਖ ਨਾ ਬਣੋ। ਜੋ ਤੁਹਾਡੇ ਤੋਂ ਵੱਖਰੇ ਹਨ, ਉਨ੍ਹਾਂ ਨਾਲ ਸਬਰ ਕਰੋ 3:159
- ਜੇ ਅੱਲ੍ਹਾ ਤੁਹਾਡੀ ਮਦਦ ਕਰੇ, ਤਾਂ ਕੋਈ ਤੁਹਾਨੂੰ ਨਹੀਂ ਹਰਾ ਸਕਦਾ; ਅਤੇ ਜੇ ਉਹ ਤੁਹਾਨੂੰ ਛੱਡ ਦੇਵੇ, ਤਾਂ ਉਸ ਤੋਂ ਬਾਅਦ ਕੌਣ ਹੈ ਜੋ ਤੁਹਾਡੀ ਮਦਦ ਕਰ ਸਕੇ? 3:160
- ਹਰੇਕ ਨੂੰ ਮੌਤ ਦਾ ਸੁਆਦ ਚੱਖਣਾ ਹੈ। ਅਤੇ ਸਿਰਫ਼ ਕ਼ਿਆਮਤ ਦੇ ਦਿਨ ਹੀ ਤੁਹਾਨੂੰ ਤੁਹਾਡਾ ਪੂਰਾ ਬਦਲਾ ਦਿੱਤਾ ਜਾਵੇਗਾ। 3:185
- ਕੁਦਰਤ ਦੇ ਕਰਿਸ਼ਮਿਆਂ ਅਤੇ ਇਸ ਬ੍ਰਹਿਮੰਡ ਦੀ ਰਚਨਾ ਬਾਰੇ ਡੂੰਘਾ ਵਿਚਾਰ ਕਰੋ। ਜਾਣੋ ਕਿ ਅੱਲ੍ਹਾ ਨੇ ਬ੍ਰਹਿਮੰਡ ਨੂੰ ਮਕਸਦ ਅਤੇ ਅਰਥ ਨਾਲ ਪੈਦਾ ਕੀਤਾ ਹੈ 3:191
- ਮਰਦਾਂ ਅਤੇ ਔਰਤਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਕੰਮਾਂ ਦਾ ਬਰਾਬਰ ਫਲ ਮਿਲੇਗਾ 3:195
- ਉਨ੍ਹਾਂ ਲਈ ਜੋ ਆਪਣੇ ਰੱਬ ਤੋਂ ਡਰਦੇ ਹਨ, ਬਾਗ਼ ਹਨ ਜਿਨ੍ਹਾਂ ਹੇਠਾਂ ਨਹਿਰਾਂ ਵਹਿੰਦੀਆਂ ਹਨ (ਜਨਤ ਵਿਚ); ਉਹ ਉੱਥੇ ਹਮੇਸ਼ਾ ਰਹਿਣਗੇ, ਇਹ ਅੱਲ੍ਹਾ ਵੱਲੋਂ ਮਹਿਮਾਨੀ ਹੈ। 3:198
- ਹਰ ਕੰਮ ਵਿਚ ਅੱਲ੍ਹਾ ਦੀ ਖੁਸ਼ੀ ਲਈ ਕੋਸ਼ਿਸ਼ ਕਰੋ। 3:200
- ਆਪਣੇ ਰੱਬ ਤੋਂ ਡਰੋ ਅਤੇ (ਰਿਸ਼ਤੇਦਾਰੀਆਂ ਦੇ) ਸੰਬੰਧ ਨਾ ਤੋੜੋ। 4:1
- ਯਤੀਮਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦਾ ਮਾਲ ਦਿਓ ਅਤੇ ਆਪਣੀਆਂ ਮਾੜੀਆਂ ਚੀਜ਼ਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀਆਂ ਚੰਗੀਆਂ ਚੀਜ਼ਾਂ ਨਾਲ ਨਾ ਬਦਲੋ; ਅਤੇ ਉਨ੍ਹਾਂ ਦਾ ਮਾਲ ਆਪਣੇ ਮਾਲ ਵਿਚ ਰਲਾ ਕੇ ਨਾ ਖਾਓ। 4:2
- ਔਰਤਾਂ ਨੂੰ (ਜਿਨ੍ਹਾਂ ਨਾਲ ਵਿਆਹ ਕਰੋ) ਉਨ੍ਹਾਂ ਦਾ ਮਹਿਰ (ਵਿਆਹ ਦਾ ਲਾਜ਼ਮੀ ਖ਼ਰਚ) ਖੁਸ਼ੀ ਨਾਲ ਦਿਓ। 4:4
- ਯਤੀਮਾਂ ਦੇ ਅਧਿਕਾਰਾਂ ਦੀ ਰੱਖਿਆ ਕਰੋ 4:6
- ਮੁਰਦੇ ਦਾ ਮਾਲ ਉਸ ਦੇ ਪਰਿਵਾਰ ਦੇ ਮੈਂਬਰਾਂ ਵਿਚ ਵੰਡਿਆ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ। ਔਰਤਾਂ ਨੂੰ ਵੀ ਵਿਰਾਸਤ ਦਾ ਅਧਿਕਾਰ ਹੈ 4:7
- ਯਤੀਮਾਂ ਦਾ ਮਾਲ ਨਾਜਾਇਜ਼ ਤੌਰ 'ਤੇ ਨਾ ਖਾਓ 4:10
- ਵਿਰਾਸਤ ਬਾਰੇ ਹੁਕਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰੋ 4:11
- ਔਰਤਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀ ਮਰਜ਼ੀ ਦੇ ਖ਼ਿਲਾਫ਼ ਵਿਰਾਸਤ ਤੋਂ ਵਾਂਝਾ ਕਰਨਾ ਮਨ੍ਹਾ ਹੈ, ਅਤੇ ਨਾ ਹੀ ਤੁਹਾਨੂੰ ਉਨ੍ਹਾਂ ਨਾਲ ਕਠੋਰਤਾ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ। ਉਨ੍ਹਾਂ (ਪਤਨੀਆਂ) ਨਾਲ ਚੰਗੇ ਢੰਗ ਨਾਲ ਰਹੋ। ਔਰਤਾਂ ਦੇ ਅਧਿਕਾਰਾਂ ਦਾ ਆਦਰ ਕਰੋ। ਆਪਣੇ ਜੀਵਨ ਸਾਥੀ ਨਾਲ ਨਿਮਰਤਾ ਅਤੇ ਦਇਆ ਨਾਲ ਪੇਸ਼ ਆਓ। ਔਰਤਾਂ ਨਾਲ ਇੱਜ਼ਤ ਅਤੇ ਇਨਸਾਫ਼ ਨਾਲ ਪੇਸ਼ ਆਓ 4:19
- ਉਨ੍ਹਾਂ ਨਾਲ ਵਿਆਹ ਨਾ ਕਰੋ ਜਿਹੜੇ ਤੁਹਾਡੇ ਖੂਨ ਦੇ ਰਿਸ਼ਤੇਦਾਰ ਹਨ 4:23
- ਆਪਣੇ ਆਪ ਨੂੰ ਨਾ ਮਾਰੋ (ਨਾ ਹੀ ਇਕ-ਦੂਜੇ ਨੂੰ ਮਾਰੋ)। ਯਕੀਨਨ, ਅੱਲ੍ਹਾ ਤੁਹਾਡੇ 'ਤੇ ਬਹੁਤ ਮਿਹਰਬਾਨ ਹੈ। ਇਕ-ਦੂਜੇ ਦਾ ਮਾਲ ਨਾਜਾਇਜ਼ ਤੌਰ 'ਤੇ ਨਾ ਖਾਓ 4:29
- ਜੇਕਰ ਤੁਸੀਂ ਵੱਡੇ ਗੁਨਾਹਾਂ ਤੋਂ ਬਚੋ ਜਿਨ੍ਹਾਂ ਤੋਂ ਮਨ੍ਹਾ ਕੀਤਾ ਗਿਆ ਹੈ, ਤਾਂ ਅੱਲ੍ਹਾ ਤੁਹਾਡੇ (ਛੋਟੇ) ਗੁਨਾਹਾਂ ਨੂੰ ਮਾਫ਼ ਕਰ ਦੇਵੇਗਾ, ਅਤੇ ਤੁਹਾਨੂੰ ਉੱਤਮ ਥਾਂ (ਜਨਤ) ਵਿਚ ਦਾਖ਼ਲ ਕਰੇਗਾ। 4:31
- ਉਨ੍ਹਾਂ ਚੀਜ਼ਾਂ ਦੀ ਇੱਛਾ ਨਾ ਕਰੋ ਜਿਨ੍ਹਾਂ ਵਿਚ ਅੱਲ੍ਹਾ ਨੇ ਤੁਹਾਡੇ ਵਿਚੋਂ ਕਿਸੇ ਨੂੰ ਕਿਸੇ 'ਤੇ ਵਧਾਈ ਦਿੱਤੀ ਹੈ। ਈਰਖਾ ਅਤੇ ਹੱਸਦ ਤੋਂ ਬਚੋ 4:32
- ਮਰਦ ਔਰਤਾਂ ਦੇ ਸਰਪ੍ਰਸਤ ਅਤੇ ਸੰਭਾਲਕ ਹਨ, ਕਿਉਂਕਿ ਅੱਲ੍ਹਾ ਨੇ ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਇਕ ਨੂੰ ਦੂਜੇ 'ਤੇ ਵਧਾਈ ਦਿੱਤੀ ਹੈ, ਅਤੇ ਕਿਉਂਕਿ ਉਹ ਆਪਣੇ ਮਾਲ ਵਿਚੋਂ ਖ਼ਰਚ ਕਰਦੇ ਹਨ (ਉਨ੍ਹਾਂ ਦਾ ਗੁਜ਼ਾਰਾ ਕਰਨ ਲਈ)। ਮਰਦ ਪਰਿਵਾਰ ਦਾ ਸਰਪ੍ਰਸਤ ਅਤੇ ਸਹਾਇਕ ਹੈ 4:34
- ਅੱਲ੍ਹਾ ਦੀ ਇਬਾਦਤ ਕਰੋ ਅਤੇ ਉਸ ਨਾਲ ਕਿਸੇ ਨੂੰ ਸ਼ਰੀਕ ਨਾ ਕਰੋ, ਮਾਤਾ-ਪਿਤਾ, ਰਿਸ਼ਤੇਦਾਰਾਂ, ਯਤੀਮਾਂ, ਮਸਾਕੀਨ (ਗਰੀਬਾਂ), ਗੁਆਂਢੀ, ਨਾਲ ਰਹਿਣ ਵਾਲੇ ਸਾਥੀ, ਰਾਹਗੀਰ (ਜਿਸ ਨੂੰ ਤੁਸੀਂ ਮਿਲੋ), ਅਤੇ ਉਨ੍ਹਾਂ (ਗ਼ੁਲਾਮਾਂ) ਨਾਲ ਨੇਕੀ ਕਰੋ ਜਿਨ੍ਹਾਂ 'ਤੇ ਤੁਹਾਡਾ ਅਧਿਕਾਰ ਹੈ। ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਨੂੰ ਪਸੰਦ ਨਹੀਂ ਕਰਦਾ ਜੋ ਮਾਣ ਕਰਨ ਵਾਲੇ ਅਤੇ ਆਪਣੀ ਵਡਿਆਈ ਕਰਨ ਵਾਲੇ ਹਨ। ਦੂਜਿਆਂ ਨਾਲ ਚੰਗਾ ਕਰੋ। ਕਮਜ਼ੋਰਾਂ 'ਤੇ ਰਹਿਮ ਕਰੋ। ਰਿਸ਼ਤੇ ਨਿਭਾਓ ਅਤੇ ਰਿਸ਼ਤੇਦਾਰਾਂ ਦਾ ਆਦਰ ਕਰੋ। 4:36
- ਕੰਜੂਸ ਨਾ ਬਣੋ 4:37
- ਅੱਲ੍ਹਾ ਇਸ ਗੱਲ ਨੂੰ ਮਾਫ਼ ਨਹੀਂ ਕਰਦਾ ਕਿ ਉਸ ਨਾਲ ਸ਼ਰੀਕ ਬਣਾਇਆ ਜਾਵੇ, ਪਰ ਇਸ ਤੋਂ ਇਲਾਵਾ ਜਿਸ ਨੂੰ ਚਾਹੇ ਮਾਫ਼ ਕਰ ਦਿੰਦਾ ਹੈ। 4:48
- ਦੂਜਿਆਂ ਤੋਂ ਈਰਖਾ ਨਾ ਕਰੋ 4:54
- ਅੱਲ੍ਹਾ ਹੁਕਮ ਦਿੰਦਾ ਹੈ ਕਿ ਤੁਸੀਂ ਅਮਾਨਤਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਵਾਪਸ ਕਰੋ ਜਿਨ੍ਹਾਂ ਦੀਆਂ ਹਨ। ਅਤੇ ਜਦੋਂ ਤੁਸੀਂ ਲੋਕਾਂ ਵਿਚ ਫੈਸਲਾ ਕਰੋ ਤਾਂ ਇਨਸਾਫ਼ ਨਾਲ ਫੈਸਲਾ ਕਰੋ। 4:58
- ਅੱਲ੍ਹਾ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ ਦੀ ਇਤਾਅਤ ਕਰੋ। ਆਪਣੇ ਵਿਚਕਾਰ ਅਧਿਕਾਰੀਆਂ ਦਾ ਆਦਰ ਕਰੋ 4:59
- ਕਮਜ਼ੋਰਾਂ ਅਤੇ ਅਸਹਾਇ ਲੋਕਾਂ 'ਤੇ ਜ਼ੁਲਮ ਨਾ ਕਰੋ 4:75
- ਤੁਹਾਨੂੰ ਜੋ ਵੀ ਭਲਾਈ ਪਹੁੰਚਦੀ ਹੈ, ਉਹ ਅੱਲ੍ਹਾ ਵੱਲੋਂ ਹੈ, ਪਰ ਜੋ ਵੀ ਬੁਰਾਈ ਤੁਹਾਨੂੰ ਆਉਂਦੀ ਹੈ, ਉਹ ਤੁਹਾਡੇ ਆਪਣੇ ਕਾਰਨ ਹੈ। 4:79
- ਜਿਸ ਨੇ ਰਸੂਲ (ਮੁਹੰਮਦ ﷺ) ਦੀ ਇਤਾਅਤ ਕੀਤੀ, ਉਸ ਨੇ ਅੱਲ੍ਹਾ ਦੀ ਇਤਾਅਤ ਕੀਤੀ। 4:80
- ਜਿਹੜਾ ਕਿਸੇ ਚੰਗੇ ਕੰਮ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਕਰੇਗਾ, ਉਸ ਨੂੰ ਉਸ ਦਾ ਫਲ ਮਿਲੇਗਾ, ਅਤੇ ਜਿਹੜਾ ਕਿਸੇ ਮਾੜੇ ਕੰਮ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਕਰੇਗਾ, ਉਸ 'ਤੇ ਉਸ ਦਾ ਬੋਝ ਹੋਵੇਗਾ। 4:85
- ਕਿਸੇ ਮੋਮਿਨ ਲਈ ਇਹ ਉਚਿਤ ਨਹੀਂ ਕਿ ਉਹ ਕਿਸੇ ਹੋਰ ਮੋਮਿਨ ਨੂੰ ਕਤਲ ਕਰੇ, ਸਿਵਾਏ ਭੁੱਲ-ਚੁੱਕ ਵਿਚ। 4:92
- ਜਿਹੜਾ ਕਿਸੇ ਮੋਮਿਨ ਨੂੰ ਜਾਣ-ਬੁੱਝ ਕੇ ਕਤਲ ਕਰਦਾ ਹੈ, ਉਸ ਦਾ ਬਦਲਾ ਜਹੰਨਮ ਹੈ, ਜਿਸ ਵਿਚ ਉਹ ਹਮੇਸ਼ਾ ਰਹੇਗਾ। ਉਸ 'ਤੇ ਅੱਲ੍ਹਾ ਦਾ ਗ਼ਜ਼ਬ ਅਤੇ ਲਾਅਨਤ ਹੈ, ਅਤੇ ਉਸ ਲਈ ਵੱਡਾ ਅਜ਼ਾਬ ਤਿਆਰ ਹੈ। 4:93
- ਜਿਹੜਾ ਅੱਲ੍ਹਾ ਦੀ ਰਾਹ ਵਿਚ ਆਪਣੇ ਘਰੋਂ ਹਿਜਰਤ ਕਰਦਾ ਹੈ, ਉਹ ਧਰਤੀ 'ਤੇ ਬਹੁਤ ਸਾਰੇ ਟਿਕਾਣੇ ਅਤੇ ਖੁੱਲ੍ਹੀ ਗੁਜ਼ਰ-ਬਸਰ ਪਾਵੇਗਾ। 4:100
- ਆਪਣੀਆਂ ਨਮਾਜ਼ਾਂ ਦਾ ਪਾਬੰਦ ਰਹੋ 4:103
- ਉਨ੍ਹਾਂ ਦਾ ਸਮਰਥਨ ਜਾਂ ਵਕਾਲਤ ਨਾ ਕਰੋ ਜੋ ਆਪਣੀਆਂ ਅਮਾਨਤਾਂ ਵਿਚ ਧੋਖਾ ਕਰਦੇ ਹਨ 4:105
- ਅੱਲ੍ਹਾ ਤੋਂ ਮੁਆਫ਼ੀ ਮੰਗੋ, ਯਕੀਨਨ ਅੱਲ੍ਹਾ ਬਹੁਤ ਮਾਫ਼ ਕਰਨ ਵਾਲਾ, ਬਹੁਤ ਮਿਹਰਬਾਨ ਹੈ। 4:106
- ਐ ਈਮਾਨ ਵਾਲਿਓ! ਇਨਸਾਫ਼ ਦੇ ਨਾਲ ਖੜੇ ਰਹੋ, ਅੱਲ੍ਹਾ ਲਈ ਗਵਾਹ ਬਣ ਕੇ, ਭਾਵੇਂ ਇਹ ਤੁਹਾਡੇ ਆਪਣੇ ਖ਼ਿਲਾਫ਼ ਹੋਵੇ, ਜਾਂ ਤੁਹਾਡੇ ਮਾਤਾ-ਪਿਤਾ ਜਾਂ ਰਿਸ਼ਤੇਦਾਰਾਂ ਦੇ ਖ਼ਿਲਾਫ਼, ਉਹ ਚਾਹੇ ਅਮੀਰ ਹੋਣ ਜਾਂ ਗਰੀਬ। ਇਨਸਾਫ਼ ਵਿਚ ਦੇਰੀ ਨਾ ਕਰੋ; ਜ਼ੁਲਮ ਨੂੰ ਸੁਧਾਰਨ ਲਈ ਤੁਰੰਤ ਕੰਮ ਕਰੋ 4:135
- ਮੁਨਾਫ਼ਿਕ ਅੱਲ੍ਹਾ ਨਾਲ ਧੋਖਾ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹਨ, ਪਰ ਉਹ ਅੱਲ੍ਹਾ ਹੈ ਜੋ ਉਨ੍ਹਾਂ ਨਾਲ ਧੋਖਾ ਕਰਦਾ ਹੈ। 4:142
- ਮੁਨਾਫ਼ਿਕ ਜਹੰਨਮ ਦੇ ਸਭ ਤੋਂ ਹੇਠਲੇ (ਪੱਧਰ) ਵਿਚ ਹੋਣਗੇ; ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਲਈ ਕੋਈ ਮਦਦਗਾਰ ਨਹੀਂ ਪਾਓਗੇ। 4:145
- ਅੱਲ੍ਹਾ ਇਹ ਪਸੰਦ ਨਹੀਂ ਕਰਦਾ ਕਿ ਬੁਰਾਈ ਨੂੰ ਖੁੱਲ੍ਹਾ ਕਿਹਾ ਜਾਵੇ, ਸਿਵਾਏ ਉਸ ਵਿਅਕਤੀ ਤੋਂ ਜਿਸ 'ਤੇ ਜ਼ੁਲਮ ਹੋਇਆ ਹੋਵੇ। 4:148
- ਰਸੂਲ ਖ਼ੁਸ਼ਖਬਰੀ ਦੇਣ ਵਾਲੇ ਅਤੇ ਡਰਾਉਣ ਵਾਲੇ ਵਜੋਂ (ਭੇਜੇ ਗਏ) ਤਾਂ ਜੋ ਰਸੂਲਾਂ (ਦੇ ਆਉਣ) ਤੋਂ ਬਾਅਦ ਲੋਕਾਂ ਦਾ ਅੱਲ੍ਹਾ ਦੇ ਖ਼ਿਲਾਫ਼ ਕੋਈ ਬਹਾਨਾ ਨਾ ਰਹੇ। 4:165
- ਆਪਣੇ ਇਕਰਾਰਨਾਮੇ ਅਤੇ ਵਾਅਦੇ ਪੂਰੇ ਕਰੋ 5:1
- ਨੇਕੀ ਅਤੇ ਪਰਹੇਜ਼ਗਾਰੀ ਵਿਚ ਇਕ-ਦੂਜੇ ਦਾ ਸਾਥ ਦਿਓ, ਗੁਨਾਹ ਅਤੇ ਜ਼ੁਲਮ ਵਿਚ ਨਹੀਂ। 5:2
- ਮੁਰਦਾ ਜਾਨਵਰ, ਖੂਨ ਅਤੇ ਸੂਰ ਦਾ ਮਾਸ ਨਾ ਖਾਓ 5:3
- ਇਨਸਾਫ਼ ਕਰੋ, ਦੂਜਿਆਂ ਦੀ ਦੁਸ਼ਮਣੀ ਅਤੇ ਨਫ਼ਰਤ ਤੁਹਾਨੂੰ ਇਨਸਾਫ਼ ਤੋਂ ਨਾ ਰੋਕੇ। ਆਪਣੇ ਲੈਣ-ਦੇਣ ਵਿਚ ਇਨਸਾਫ਼ ਅਤੇ ਨਿਰਪੱਖ ਰਹੋ। ਜਾਣੋ ਕਿ ਇਨਸਾਫ਼ ਕਰਨਾ ਪਰਹੇਜ਼ਗਾਰੀ ਦੇ ਨੇੜੇ ਹੈ। ਇਨਸਾਫ਼ ਵਿਚ ਦੇਰੀ ਨਾ ਕਰੋ; ਜ਼ੁਲਮ ਨੂੰ ਸੁਧਾਰਨ ਲਈ ਤੁਰੰਤ ਕੰਮ ਕਰੋ 5:8
- ਅੱਲ੍ਹਾ ਦੇ ਨੇੜੇ ਹੋਣ ਦੇ ਰਾਹ ਲੱਭੋ, ਅਤੇ ਉਸ ਦੀ ਰਾਹ ਵਿਚ ਜਿੰਨਾ ਹੋ ਸਕੇ ਜਤਨ ਕਰੋ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਸਫ਼ਲ ਹੋ ਸਕੋ। 5:35
- ਆਪਣੀਆਂ ਸੌਖਾਂ ਅਤੇ ਇਕਰਾਰਨਾਮੇ ਪੂਰੇ ਕਰੋ 5:89
- ਨਸ਼ੇ ਅਤੇ ਸ਼ਰਾਬ ਤੋਂ ਬਚੋ। ਸਖ਼ਤੀ ਨਾਲ ਨਸ਼ੀਲੀਆਂ ਚੀਜ਼ਾਂ (ਹਰ ਤਰ੍ਹਾਂ ਦੇ ਸ਼ਰਾਬੀ ਪੀਣ ਵਾਲੇ ਪਦਾਰਥ), ਜੂਆ, ਅੰਸਾਬ (ਪੱਥਰ ਦੀਆਂ ਵੇਦੀਆਂ), ਅਤੇ ਅਜ਼ਲਾਮ (ਤੀਰ ਜੋ ਕਿਸਮਤ ਜਾਂ ਫੈਸਲਾ ਲੱਭਣ ਲਈ ਹਨ) ਤੋਂ ਬਚੋ, ਜੋ ਸ਼ੈਤਾਨ ਦੇ ਕੰਮਾਂ ਵਿਚੋਂ ਘ੍ਰਿਣਾਯੋਗ ਹਨ। 5:90
- ਹੱਜ ਜਾਂ ਉਮਰੇ ਦੀ ਇਹਰਾਮ ਦੀ ਹਾਲਤ ਵਿਚ ਸ਼ਿਕਾਰ ਨਾ ਕਰੋ। 5:95
- ਅਜਿਹੀਆਂ ਚੀਜ਼ਾਂ ਬਾਰੇ ਨਾ ਪੁੱਛੋ ਜਿਨ੍ਹਾਂ ਦੇ ਤੁਹਾਡੇ ਸਾਹਮਣੇ ਸਪਸ਼ਟ ਹੋਣ 'ਤੇ ਤੁਹਾਨੂੰ ਮੁਸ਼ਕਲ ਪੈਦਾ ਹੋ ਸਕਦੀ ਹੈ। 5:101
- ਦੂਜੇ ਲੋਕਾਂ ਦੇ ਪੂਜਣਯੋਗਾਂ ਦੀ ਬੇਇੱਜ਼ਤੀ ਨਾ ਕਰੋ। ਉਨ੍ਹਾਂ (ਬੁੱਤ ਪੂਜਕਾਂ) ਦੀਆਂ ਪੂਜਾ ਦੀਆਂ ਚੀਜ਼ਾਂ ਦੀ ਬੇਇੱਜ਼ਤੀ ਨਾ ਕਰੋ ਜਿਨ੍ਹਾਂ ਨੂੰ ਉਹ ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਪੂਜਦੇ ਹਨ, ਕਿਤੇ ਅਜਿਹਾ ਨਾ ਹੋਵੇ ਕਿ ਉਹ ਬੇਸਮਝੀ ਵਿਚ ਅੱਲ੍ਹਾ ਦੀ ਬੇਇੱਜ਼ਤੀ ਕਰਨ। 6:108
- ਜੇਕਰ ਤੁਸੀਂ ਧਰਤੀ 'ਤੇ ਬਹੁਤਿਆਂ ਦੀ ਗੱਲ ਮੰਨੋ, ਤਾਂ ਉਹ ਤੁਹਾਨੂੰ ਅੱਲ੍ਹਾ ਦੇ ਰਾਹ ਤੋਂ ਭਟਕਾ ਦੇਣਗੇ। ਉਹ ਸਿਰਫ਼ ਗੁਮਾਨ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ, ਅਤੇ ਸਿਰਫ਼ ਝੂਠ ਬੋਲਦੇ ਹਨ। 6:116
- (ਐ ਲੋਕੋ!) ਸਭ ਕਿਸਮ ਦੇ ਗੁਨਾਹ, ਖੁੱਲ੍ਹੇ ਅਤੇ ਛੁਪੇ, ਛੱਡ ਦਿਓ। 6:120
- (ਐ ਈਮਾਨ ਵਾਲਿਓ!) ਉਸ (ਮਾਸ) ਵਿਚੋਂ ਨਾ ਖਾਓ ਜਿਸ 'ਤੇ (ਜ਼ਿਬ੍ਹਾ ਕਰਦੇ ਸਮੇਂ) ਅੱਲ੍ਹਾ ਦਾ ਨਾਮ ਨਾ ਲਿਆ ਗਿਆ ਹੋਵੇ। 6:121
- ਜਿਸ ਨੂੰ ਅੱਲ੍ਹਾ ਰਾਹ ਦਿਖਾਉਣਾ ਚਾਹੁੰਦਾ ਹੈ, ਉਸ ਦਾ ਸੀਨਾ ਇਸਲਾਮ ਲਈ ਖੋਲ੍ਹ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਜਿਸ ਨੂੰ ਭਟਕਾਉਣਾ ਚਾਹੁੰਦਾ ਹੈ, ਉਸ ਦਾ ਸੀਨਾ ਤੰਗ ਅਤੇ ਘੁੱਟ ਕਰ ਦਿੰਦਾ ਹੈ। 6:125
- ਖ਼ਰਚ ਵਿਚ ਸੰਤੁਲਨ ਰੱਖੋ ਅਤੇ ਫ਼ਜ਼ੂਲਖ਼ਰਚੀ ਤੋਂ ਬਚੋ। ਸਾਰੀਆਂ ਮਖ਼ਲੂਕਾਂ ਦੇ ਅਧਿਕਾਰਾਂ ਦੀ ਰੱਖਿਆ ਕਰੋ 6:141
- ਅੱਲ੍ਹਾ ਨਾਲ ਕਿਸੇ ਨੂੰ ਸ਼ਰੀਕ ਨਾ ਬਣਾਓ, ਮਾਤਾ-ਪਿਤਾ ਨਾਲ ਨੇਕੀ ਕਰੋ, ਆਪਣੇ ਬੱਚਿਆਂ ਨੂੰ ਗ਼ਰੀਬੀ ਦੇ ਡਰੋਂ ਨਾ ਮਾਰੋ, ਬਦਕਾਰੀ (ਫ਼ਾਹਿਸ਼ਾ) ਦੇ ਨੇੜੇ ਨਾ ਜਾਓ, ਕਿਸੇ ਨੂੰ ਕਤਲ ਨਾ ਕਰੋ ਜਿਸ ਨੂੰ ਅੱਲ੍ਹਾ ਨੇ ਮਨ੍ਹਾ ਕੀਤਾ ਹੈ, ਸਿਵਾਏ ਕਿਸੇ ਹੱਕੀ ਕਾਰਨ ਤੋਂ। 6:151
- ਇਮਾਨਦਾਰ ਰਹੋ; ਆਪਣੇ ਕਿਸੇ ਵੀ ਲੈਣ-ਦੇਣ ਵਿਚ ਧੋਖਾ ਨਾ ਕਰੋ। ਯਤੀਮ ਦੇ ਮਾਲ ਦੇ ਨੇੜੇ ਨਾ ਜਾਓ, ਸਿਵਾਏ ਉਸ ਨੂੰ ਸੁਧਾਰਨ ਲਈ, ਨਾਪ-ਤੋਲ ਇਨਸਾਫ਼ ਨਾਲ ਪੂਰਾ ਕਰੋ, ਜਦੋਂ ਤੁਸੀਂ ਗੱਲ ਕਰੋ ਤਾਂ ਸੱਚ ਬੋਲੋ, ਭਾਵੇਂ ਕੋਈ ਨੇੜਲਾ ਰਿਸ਼ਤੇਦਾਰ ਹੀ ਕਿਉਂ ਨਾ ਹੋਵੇ, ਅਤੇ ਅੱਲ੍ਹਾ ਦਾ ਇਕਰਾਰ ਪੂਰਾ ਕਰੋ। 6:152
- ਸਿੱਧਾ ਰਾਹ ਅਪਣਾਓ ਅਤੇ (ਹੋਰ) ਰਾਹਾਂ 'ਤੇ ਨਾ ਚੱਲੋ, ਕਿਉਂਕਿ ਉਹ ਤੁਹਾਨੂੰ ਉਸ ਦੇ ਰਾਹ ਤੋਂ ਵੱਖ ਕਰ ਦੇਣਗੇ। 6:153
- (ਐ ਮੁਹੰਮਦ ﷺ) ਕਹਿ ਦਿਓ: "ਯਕੀਨਨ, ਮੇਰੀ ਨਮਾਜ਼, ਮੇਰੀ ਕੁਰਬਾਨੀ, ਮੇਰਾ ਜੀਉਣਾ ਅਤੇ ਮੇਰਾ ਮਰਨਾ ਸਭ ਅੱਲ੍ਹਾ ਲਈ ਹੈ, ਜੋ ਸਾਰੇ ਸੰਸਾਰਾਂ ਦਾ ਰੱਬ ਹੈ।" 6:162
- ਮਾਣ ਨਾ ਕਰੋ 7:13
- ਸ਼ੈਤਾਨ ਤੁਹਾਨੂੰ ਧੋਖਾ ਨਾ ਦੇਵੇ। 7:27
- (ਐ ਮੁਹੰਮਦ ﷺ) ਕਹਿ ਦਿਓ: "ਮੇਰੇ ਰੱਬ ਨੇ ਇਨਸਾਫ਼ ਦਾ ਹੁਕਮ ਦਿੱਤਾ ਹੈ..." 7:29
- ਹਰ ਮਾਮਲੇ ਵਿਚ ਅੱਲ੍ਹਾ ਵੱਲੋਂ ਮੁਕੱਰਰ ਕੀਤੀਆਂ ਹੱਦਾਂ ਦੀ ਪਾਲਣਾ ਕਰੋ। ਬੋਲੀ ਅਤੇ ਕੰਮਾਂ ਵਿਚ ਹੱਦ ਤੋਂ ਨਾ ਵਧੋ। ਖਾਓ-ਪੀਓ ਪਰ ਜ਼ਿਆਦਤੀ ਨਾ ਕਰੋ। ਨਮਾਜ਼ ਦੇ ਸਮੇਂ ਚੰਗੇ ਕੱਪੜੇ ਪਾਓ 7:31
- ਅੱਲ੍ਹਾ ਨੇ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਨੂੰ ਛੇ ਦਿਨਾਂ ਵਿਚ ਪੈਦਾ ਕੀਤਾ, ਫਿਰ ਉਹ ਅਰਸ਼ 'ਤੇ ਤਸੱਕੀ ਕੀਤੀ (ਇਸ ਤਰ੍ਹਾਂ ਜੋ ਉਸ ਦੀ ਸ਼ਾਨ ਦੇ ਯੋਗ ਹੈ)। 7:54
- ਆਪਣੇ ਰੱਬ ਨੂੰ ਗਿਰਾਵਰ ਅਤੇ ਛੁਪ ਕੇ ਪੁਕਾਰੋ। ਉਹ ਹੱਦ ਤੋਂ ਵੱਧਣ ਵਾਲਿਆਂ ਨੂੰ ਪਸੰਦ ਨਹੀਂ ਕਰਦਾ। 7:55
- ਅਤੇ ਧਰਤੀ 'ਤੇ, ਜਦੋਂ ਉਸ ਦਾ ਸੁਧਾਰ ਹੋ ਚੁੱਕਿਆ ਹੋਵੇ, ਫ਼ਸਾਦ ਨਾ ਫੈਲਾਓ, ਅਤੇ ਉਸ ਨੂੰ ਡਰ ਅਤੇ ਉਮੀਦ ਨਾਲ ਪੁਕਾਰੋ। 7:56
- ਪਰ ਜਿਨ੍ਹਾਂ ਨੇ ਬੁਰਾਈਆਂ ਕੀਤੀਆਂ ਅਤੇ ਫਿਰ ਉਸ ਤੋਂ ਬਾਅਦ ਤੌਬਾ ਕੀਤੀ ਅਤੇ ਈਮਾਨ ਲਿਆਏ, ਤਾਂ ਯਕੀਨਨ ਤੁਹਾਡਾ ਰੱਬ ਉਸ (ਤੌਬਾ) ਤੋਂ ਬਾਅਦ ਬਹੁਤ ਮਾਫ਼ ਕਰਨ ਵਾਲਾ, ਬਹੁਤ ਮਿਹਰਬਾਨ ਹੈ। 7:153
- (ਐ ਮੁਹੰਮਦ ﷺ) ਕਹਿ ਦਿਓ: "ਐ ਲੋਕੋ! ਯਕੀਨਨ, ਮੈਂ ਤੁਹਾਡੇ ਸਭ ਵੱਲ ਅੱਲ੍ਹਾ ਦਾ ਰਸੂਲ ਹਾਂ..." 7:158
- ਅਤੇ (ਸਭ) ਸੋਹਣੇ ਨਾਮ ਅੱਲ੍ਹਾ ਦੇ ਹਨ, ਇਸ ਲਈ ਉਸ ਨੂੰ ਉਨ੍ਹਾਂ ਨਾਲ ਪੁਕਾਰੋ, ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਛੱਡ ਦਿਓ ਜੋ ਉਸ ਦੇ ਨਾਮਾਂ ਬਾਰੇ ਝੂਠ ਬੋਲਦੇ ਜਾਂ ਇਨਕਾਰ ਕਰਦੇ (ਜਾਂ ਬੁਰਾ ਭਾਸ਼ਣ ਕਰਦੇ) ਹਨ... 7:180
- ਜਿਸ ਨੂੰ ਅੱਲ੍ਹਾ ਭਟਕਾ ਦੇਵੇ, ਉਸ ਨੂੰ ਕੋਈ ਰਾਹ ਨਹੀਂ ਦਿਖਾ ਸਕਦਾ; ਅਤੇ ਉਹ ਉਨ੍ਹਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੀ ਸਰਕਸ਼ੀ ਵਿਚ ਭਟਕਦਾ ਛੱਡ ਦਿੰਦਾ ਹੈ। 7:186
- ਮਾਫ਼ੀ ਅਪਣਾਓ, ਭਲਾਈ ਦਾ ਹੁਕਮ ਦਿਓ, ਅਤੇ ਜਾਹਿਲਾਂ (ਤੋਂ) ਮੁੰਹ ਮੋੜ ਲਓ (ਭਾਵ, ਉਨ੍ਹਾਂ ਨੂੰ ਸਜ਼ਾ ਨਾ ਦਿਓ)। 7:199
- ਦੂਜਿਆਂ ਦੀਆਂ ਗ਼ਲਤੀਆਂ ਨੂੰ ਮਾਫ਼ ਕਰੋ 7:199
- ਅਤੇ ਜੇਕਰ ਸ਼ੈਤਾਨ ਵੱਲੋਂ ਕੋਈ ਬੁਰਾ ਖਿਆਲ ਤੁਹਾਡੇ ਮਨ ਵਿਚ ਆਵੇ, ਤਾਂ ਅੱਲ੍ਹਾ ਦੀ ਪਨਾਹ ਮੰਗੋ। ਯਕੀਨਨ, ਉਹ ਸਭ ਕੁਝ ਸੁਣਨ ਵਾਲਾ, ਸਭ ਕੁਝ ਜਾਣਨ ਵਾਲਾ ਹੈ। 7:200
- ਈਮਾਨ ਵਾਲੇ ਤਾਂ ਸਿਰਫ਼ ਉਹ ਹਨ ਜਿਨ੍ਹਾਂ ਦੇ ਦਿਲ ਵਿਚ ਜਦੋਂ ਅੱਲ੍ਹਾ ਦਾ ਜ਼ਿਕਰ ਕੀਤਾ ਜਾਵੇ ਤਾਂ ਡਰ ਪੈਦਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਜਦੋਂ ਉਸ ਦੀਆਂ ਆਇਤਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਸੁਣਾਈਆਂ ਜਾਣ ਤਾਂ ਉਨ੍ਹਾਂ ਦਾ ਈਮਾਨ ਵਧ ਜਾਂਦਾ ਹੈ... 8:2
- ਅੱਲ੍ਹਾ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ ਨਾਲ ਧੋਖਾ ਨਾ ਕਰੋ, ਨਾ ਹੀ ਜਾਣ-ਬੁੱਝ ਕੇ ਆਪਣੀਆਂ ਅਮਾਨਤਾਂ (ਤੁਹਾਨੂੰ ਸੌਂਪੀਆਂ ਗਈਆਂ ਚੀਜ਼ਾਂ, ਅਤੇ ਸਾਰੇ ਧਾਰਮਿਕ ਫ਼ਰਜ਼) ਵਿਚ ਧੋਖਾ ਕਰੋ। 8:27
- ਜੇਕਰ ਤੁਸੀਂ ਅੱਲ੍ਹਾ ਦੀ ਇਤਾਅਤ ਕਰੋ ਅਤੇ ਉਸ ਤੋਂ ਡਰੋ, ਤਾਂ ਉਹ ਤੁਹਾਨੂੰ ਫ਼ੁਰਕਾਨ (ਸੱਚ-ਝੂਠ ਦਾ ਪਰਖ ਮਾਪ) ਦੇਵੇਗਾ। 8:29
- ਜਿਨ੍ਹਾਂ ਨੇ ਇਨਕਾਰ ਕੀਤਾ, ਉਹ ਆਪਣਾ ਮਾਲ ਅੱਲ੍ਹਾ ਦੇ ਰਾਹ ਤੋਂ ਰੋਕਣ ਲਈ ਖ਼ਰਚ ਕਰਦੇ ਹਨ, ਅਤੇ ਉਹ ਇਸ ਨੂੰ ਖ਼ਰਚ ਕਰਦੇ ਰਹਿਣਗੇ; ਪਰ ਅੰਤ ਵਿਚ ਇਹ ਉਨ੍ਹਾਂ ਲਈ ਪਛਤਾਵਾ ਬਣੇਗਾ। 8:36
- ਜਿਨ੍ਹਾਂ ਨੇ ਇਨਕਾਰ ਕੀਤਾ ਹੈ, ਉਨ੍ਹਾਂ ਨੂੰ ਕਹਿ ਦਿਓ ਕਿ ਜੇਕਰ ਉਹ (ਇਨਕਾਰ ਤੋਂ) ਰੁਕ ਜਾਣ, ਤਾਂ ਉਨ੍ਹਾਂ ਦਾ ਪਿਛਲਾ ਜੀਵਨ ਮਾਫ਼ ਕਰ ਦਿੱਤਾ ਜਾਵੇਗਾ। ਪਰ ਜੇਕਰ ਉਹ (ਉਸ ਵੱਲ) ਮੁੜਨ, ਤਾਂ ਪਹਿਲਾਂ ਉਨ੍ਹਾਂ (ਸਜ਼ਾਯਾਫ਼ਤਾ) ਦੀਆਂ ਮਿਸਾਲਾਂ ਬੀਤ ਚੁੱਕੀਆਂ ਹਨ। 8:38
- ਜਦੋਂ ਤੁਹਾਡਾ (ਦੁਸ਼ਮਣ) ਫ਼ੌਜ ਨਾਲ ਮੁਕਾਬਲਾ ਹੋਵੇ, ਤਾਂ ਉਨ੍ਹਾਂ ਦੇ ਮੁਕਾਬਲੇ 'ਤੇ ਦ੍ਰਿੜ ਰਹੋ ਅਤੇ ਅੱਲ੍ਹਾ ਦਾ ਬਹੁਤ ਜ਼ਿਕਰ ਕਰੋ (ਬੋਲੀ ਅਤੇ ਮਨ ਨਾਲ), ਤਾਂ ਜੋ ਤੁਸੀਂ ਸਫ਼ਲ ਹੋ ਸਕੋ। 8:45
- ਉਨ੍ਹਾਂ ਵਰਗੇ ਨਾ ਬਣੋ ਜੋ ਆਪਣੇ ਘਰਾਂ ਤੋਂ ਇਤਰਾਜ਼ ਅਤੇ ਲੋਕਾਂ ਨੂੰ ਦਿਖਾਉਣ ਲਈ ਨਿਕਲੇ, ਅਤੇ ਲੋਕਾਂ ਨੂੰ ਅੱਲ੍ਹਾ ਦੇ ਰਾਹ ਤੋਂ ਰੋਕਦੇ ਹਨ। 8:47
- ਅੱਲ੍ਹਾ ਕਿਸੇ ਕੌਮ 'ਤੇ ਕੋਈ ਨਿਅਮਤ ਨਹੀਂ ਬਦਲਦਾ ਜਦੋਂ ਤੱਕ ਉਹ ਆਪਣੇ ਆਪ ਨੂੰ ਨਹੀਂ ਬਦਲਦੇ। 8:53
- ਅੱਲ੍ਹਾ ਦੇ ਨੇੜੇ ਚੱਲਣ ਵਾਲੀਆਂ ਮਖ਼ਲੂਕਾਂ ਵਿਚੋਂ ਸਭ ਤੋਂ ਮਾੜੇ ਉਹ ਹਨ ਜੋ ਇਨਕਾਰ ਕਰਦੇ ਹਨ। 8:55
- ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਦੇ ਦਿਲਾਂ ਵਿਚ ਪਿਆਰ ਅਤੇ ਮੁਹੱਬਤ ਪੈਦਾ ਕਰਦਾ ਹੈ ਜੋ ਉਸ 'ਤੇ ਈਮਾਨ ਰੱਖਦੇ ਹਨ 8:63
- ਉਨ੍ਹਾਂ ਦੀ ਰੱਖਿਆ ਅਤੇ ਮਦਦ ਕਰੋ ਜੋ ਪਨਾਹ ਮੰਗਦੇ ਹਨ 9:6
- ਮੁਸ਼ਰਿਕਾਂ ਲਈ ਅੱਲ੍ਹਾ ਦੀਆਂ ਮਸਜਿਦਾਂ ਨੂੰ (ਉਨ੍ਹਾਂ ਦੇ ਕਬਜ਼ੇ ਵਿਚ) ਰੱਖਣਾ ਉਚਿਤ ਨਹੀਂ। 9:17
- ਉਹ (ਇਨਕਾਰੀ, ਯਹੂਦੀ ਅਤੇ ਈਸਾਈ) ਚਾਹੁੰਦੇ ਹਨ ਕਿ ਅੱਲ੍ਹਾ ਦੇ ਨੂਰ (ਜਿਸ ਨਾਲ ਮੁਹੰਮਦ ﷺ ਭੇਜੇ ਗਏ – ਇਸਲਾਮੀ ਇੱਕਤੌਹੀਦ) ਨੂੰ ਆਪਣੇ ਮੂੰਹਾਂ ਨਾਲ ਬੁਝਾ ਦੇਣ, ਪਰ ਅੱਲ੍ਹਾ ਇਸ ਨੂੰ ਪੂਰਾ ਕਰਨ ਤੋਂ ਬਿਨਾਂ ਨਹੀਂ ਰਹਿਣ ਦੇਵੇਗਾ, ਭਾਵੇਂ ਇਨਕਾਰੀਆਂ ਨੂੰ ਕਿੰਨਾ ਹੀ ਬੁਰਾ ਲੱਗੇ। 9:32
- ਸਦਕ਼ਾਤ (ਭਾਵ, ਜ਼ਕਾਤ) ਸਿਰਫ਼ ਇਨ੍ਹਾਂ ਲਈ ਹਨ: 1) ਫ਼ੁਕਰਾ (ਗਰੀਬ), 2) ਮਸਾਕੀਨ (ਗਰੀਬ), 3) ਉਹ ਜੋ ਫੰਡ ਇਕੱਠੇ ਕਰਨ ਲਈ ਨਿਯੁਕਤ ਕੀਤੇ ਗਏ ਹਨ, 4) ਉਨ੍ਹਾਂ ਦੇ ਦਿਲਾਂ ਨੂੰ ਇਸਲਾਮ ਵੱਲ ਝੁਕਾਉਣ ਲਈ, 5) ਗ਼ੁਲਾਮ ਛੁਡਾਉਣ ਲਈ, 6) ਕਰਜ਼ਦਾਰਾਂ ਲਈ, 7) ਅੱਲ੍ਹਾ ਦੀ ਰਾਹ (ਭਾਵ, ਮੁਜਾਹਿਦਾਂ) ਲਈ, ਅਤੇ 8) ਰਾਹਗੀਰਾਂ ਲਈ। 9:60
- ਜਿਹੜਾ ਅੱਲ੍ਹਾ ਅਤੇ ਉਸ ਦੇ ਰਸੂਲ (ﷺ) ਦਾ ਵਿਰੋਧ ਕਰਦਾ ਅਤੇ ਦੁਸ਼ਮਣੀ ਰੱਖਦਾ ਹੈ, ਉਸ ਲਈ ਯਕੀਨਨ ਜਹੰਨਮ ਦੀ ਅੱਗ ਹੈ, ਜਿਸ ਵਿਚ ਉਹ ਹਮੇਸ਼ਾ ਰਹੇਗਾ। ਇਹ ਬਹੁਤ ਵੱਡੀ ਬੇਇੱਜ਼ਤੀ ਹੈ। 9:63
- ਮੁਨਾਫ਼ਿਕ ਮਰਦ ਅਤੇ ਔਰਤਾਂ ਆਪਸ ਵਿਚ ਇਕੋ ਜਿਹੇ ਹਨ। ਉਹ ਅੱਲ੍ਹਾ ਨੂੰ ਭੁੱਲ ਗਏ, ਇਸ ਲਈ ਉਹ ਉਨ੍ਹਾਂ ਨੂੰ ਭੁੱਲ ਗਿਆ। 9:67
- ਪਵਿੱਤਰਤਾ ਲਈ ਕੋਸ਼ਿਸ਼ ਕਰੋ। ਮਸਜਿਦ ਦੀ ਪਵਿੱਤਰਤਾ ਦਾ ਆਦਰ ਕਰੋ 9:108
- ਨਬੀ ਅਤੇ ਈਮਾਨ ਵਾਲਿਆਂ ਲਈ ਇਹ ਉਚਿਤ ਨਹੀਂ ਕਿ ਉਹ ਮੁਸ਼ਰਿਕਾਂ ਲਈ ਮੁਆਫ਼ੀ ਮੰਗਣ, ਭਾਵੇਂ ਉਹ ਰਿਸ਼ਤੇਦਾਰ ਹੀ ਹੋਣ, ਜਦੋਂ ਉਨ੍ਹਾਂ 'ਤੇ ਇਹ ਸਪਸ਼ਟ ਹੋ ਗਿਆ ਹੋਵੇ ਕਿ ਉਹ ਜਹੰਨਮ ਵਾਲੇ ਹਨ (ਕਿਉਂਕਿ ਉਹ ਇਨਕਾਰ ਦੀ ਹਾਲਤ ਵਿਚ ਮਰੇ)। 9:113
- ਉਸ ਤੋਂ ਵੱਡਾ ਜ਼ਾਲਮ ਕੌਣ ਹੈ ਜੋ ਅੱਲ੍ਹਾ 'ਤੇ ਝੂਠ ਘੜੇ ਜਾਂ ਉਸ ਦੀਆਂ ਆਇਤਾਂ ਦਾ ਇਨਕਾਰ ਕਰੇ? ਯਕੀਨਨ, ਗੁਨਾਹਗਾਰ ਕਦੇ ਸਫ਼ਲ ਨਹੀਂ ਹੋਣਗੇ! 10:17
- ਉਹ ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਉਨ੍ਹਾਂ ਚੀਜ਼ਾਂ ਦੀ ਪੂਜਾ ਕਰਦੇ ਹਨ ਜੋ ਨਾ ਉਨ੍ਹਾਂ ਨੂੰ ਨੁਕਸਾਨ ਪਹੁੰਚਾ ਸਕਦੀਆਂ ਹਨ ਅਤੇ ਨਾ ਲਾਭ, ਅਤੇ ਉਹ ਕਹਿੰਦੇ ਹਨ: "ਇਹ ਅੱਲ੍ਹਾ ਅੱਗੇ ਸਾਡੇ ਸਿਫ਼ਾਰਸ਼ੀ ਹਨ।" ਕਹਿ ਦਿਓ: "ਕੀ ਤੁਸੀਂ ਅੱਲ੍ਹਾ ਨੂੰ ਉਹ ਚੀਜ਼ ਦੱਸਦੇ ਹੋ ਜਿਸ ਨੂੰ ਉਹ ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਵਿਚ ਨਹੀਂ ਜਾਣਦਾ?" ਉਹ ਪਵਿੱਤਰ ਹੈ ਅਤੇ ਉਸ ਤੋਂ ਉੱਚਾ ਹੈ ਜੋ ਉਹ ਉਸ ਨਾਲ ਸ਼ਰੀਕ ਬਣਾਉਂਦੇ ਹਨ! 10:18
- ਬੁਰਾਈ ਦਾ ਬਦਲਾ ਉਸ ਦੇ ਬਰਾਬਰ ਹੈ। 10:27
- ਇਹ ਹੈ ਅੱਲ੍ਹਾ, ਤੁਹਾਡਾ ਸੱਚਾ ਰੱਬ। ਫਿਰ ਸੱਚ ਤੋਂ ਬਾਅਦ ਭਟਕਣਾ ਹੀ ਬਚਦਾ ਹੈ? ਫਿਰ ਤੁਸੀਂ ਕਿੱਥੇ ਭਟਕਾਏ ਜਾ ਰਹੇ ਹੋ? 10:32
- ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਬਹੁਤੇ ਸਿਰਫ਼ ਗੁਮਾਨ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ। ਯਕੀਨਨ, ਗੁਮਾਨ ਸੱਚ ਦੇ ਮੁਕਾਬਲੇ ਕੁਝ ਕੰਮ ਨਹੀਂ ਆ ਸਕਦਾ। 10:36
- ਯਕੀਨਨ, ਅੱਲ੍ਹਾ ਲੋਕਾਂ 'ਤੇ ਕੋਈ ਜ਼ੁਲਮ ਨਹੀਂ ਕਰਦਾ; ਪਰ ਲੋਕ ਆਪਣੇ ਆਪ 'ਤੇ ਜ਼ੁਲਮ ਕਰਦੇ ਹਨ। 10:44
- ਜਾਣ ਲਵੋ ਕਿ ਅੱਲ੍ਹਾ ਦੀ ਦਾਤ ਮਨੁੱਖ ਦੁਆਰਾ ਇਕੱਠੀ ਕੀਤੀ ਗਈ ਕਿਸੇ ਵੀ ਦੌਲਤ ਨਾਲੋਂ ਉੱਤਮ ਹੈ 10:58
- ਅੱਲ੍ਹਾ ਦੀਆਂ ਆਇਤਾਂ ਦਾ ਇਨਕਾਰ ਕਰਨ ਵਾਲਿਆਂ ਵਿਚੋਂ ਨਾ ਬਣੋ, ਕਿਉਂਕਿ ਫਿਰ ਤੁਸੀਂ ਘਾਟੇ ਵਿਚ ਰਹਿਣ ਵਾਲਿਆਂ ਵਿਚੋਂ ਹੋਵੋਗੇ। 10:95
- ਜੇਕਰ ਅੱਲ੍ਹਾ ਤੁਹਾਨੂੰ ਕੋਈ ਤਕਲੀਫ਼ ਪਹੁੰਚਾਵੇ, ਤਾਂ ਉਸ ਤੋਂ ਇਲਾਵਾ ਕੋਈ ਉਸ ਨੂੰ ਦੂਰ ਨਹੀਂ ਕਰ ਸਕਦਾ; ਅਤੇ ਜੇਕਰ ਉਹ ਤੁਹਾਡੇ ਲਈ ਕੋਈ ਭਲਾਈ ਚਾਹੁੰਦਾ ਹੈ, ਤਾਂ ਉਸ ਦੀ ਰਹਿਮਤ ਨੂੰ ਕੋਈ ਨਹੀਂ ਰੋਕ ਸਕਦਾ, ਜਿਸ ਨੂੰ ਉਹ ਆਪਣੇ ਬੰਦਿਆਂ ਵਿਚੋਂ ਚਾਹੇ ਪਹੁੰਚਾਉਂਦਾ ਹੈ। 10:107
- ਧਰਤੀ 'ਤੇ ਕੋਈ ਜੀਵ ਨਹੀਂ ਹੈ ਪਰ ਉਸ ਦੀ ਰੋਜ਼ੀ ਅੱਲ੍ਹਾ 'ਤੇ ਹੈ। ਅਤੇ ਉਹ ਉਸ ਦੇ ਰਹਿਣ ਦੀ ਜਗ੍ਹਾ ਅਤੇ ਉਸ ਦੀ ਅੰਤਿਮ ਥਾਂ (ਪੇਟ, ਕਬਰ ਆਦਿ) ਨੂੰ ਜਾਣਦਾ ਹੈ। 11:6
- ਜੇਕਰ ਅਸੀਂ ਮਨੁੱਖ ਨੂੰ ਆਪਣੀ ਰਹਿਮਤ ਦਾ ਸੁਆਦ ਚਖਾਉਂਦੇ ਹਾਂ, ਅਤੇ ਫਿਰ ਉਸ ਨੂੰ ਉਸ ਤੋਂ ਵਾਂਝਾ ਕਰ ਦਿੰਦੇ ਹਾਂ, ਤਾਂ ਉਹ ਨਿਰਾਸ਼ ਅਤੇ ਨਾਸ਼ੁਕਰਾ ਬਣ ਜਾਂਦਾ ਹੈ। 11:9
- ਜਿਹੜਾ ਸੰਸਾਰ ਦੀ ਜ਼ਿੰਦਗੀ ਅਤੇ ਉਸ ਦੀ ਚਮਕ-ਦਮਕ ਚਾਹੁੰਦਾ ਹੈ, ਅਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਕੰਮਾਂ ਦਾ ਪੂਰਾ ਬਦਲਾ ਇਸੇ ਦੁਨੀਆ ਵਿਚ ਦੇ ਦਿੰਦੇ ਹਾਂ, ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਕੋਈ ਘਾਟਾ ਨਹੀਂ ਹੁੰਦਾ। 11:15
- ਅਸੀਂ ਉਨ੍ਹਾਂ 'ਤੇ ਜ਼ੁਲਮ ਨਹੀਂ ਕੀਤਾ, ਸਗੋਂ ਉਨ੍ਹਾਂ ਨੇ ਆਪਣੇ ਆਪ 'ਤੇ ਜ਼ੁਲਮ ਕੀਤਾ। ਇਸ ਲਈ ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਜਿਨ੍ਹਾਂ (ਪੂਜਣਯੋਗਾਂ) ਨੂੰ ਉਹ ਪੁਕਾਰਦੇ ਸਨ, ਉਨ੍ਹਾਂ ਨੇ ਉਨ੍ਹਾਂ ਨੂੰ ਕੋਈ ਲਾਭ ਨਾ ਪਹੁੰਚਾਇਆ ਜਦੋਂ ਤੁਹਾਡੇ ਰੱਬ ਦਾ ਹੁਕਮ ਆਇਆ, ਅਤੇ ਨਾ ਹੀ ਉਨ੍ਹਾਂ ਨੇ ਉਨ੍ਹਾਂ ਦੀ ਤਬਾਹੀ ਵਿਚ ਕੋਈ ਵਾਧਾ ਕੀਤਾ। 11:101
- ਜਿਸ ਦਿਨ ਉਹ (ਕ਼ਿਆਮਤ) ਆਵੇਗੀ, ਕੋਈ ਵੀ ਵਿਅਕਤੀ ਅੱਲ੍ਹਾ ਦੀ ਇਜਾਜ਼ਤ ਤੋਂ ਬਿਨਾਂ ਨਹੀਂ ਬੋਲੇਗਾ। ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਕੁਝ ਬਦਕਿਸਮਤ ਹੋਣਗੇ ਅਤੇ (ਕੁਝ) ਖੁਸ਼ਕਿਸਮਤ। 11:105
- ਜਿਹੜੇ ਬਦਕਿਸਮਤ ਹਨ, ਉਹ ਜਹੰਨਮ ਵਿਚ ਹੋਣਗੇ, ਉੱਥੇ ਉੱਚੀ-ਨੀਵੀਂ ਆਵਾਜ਼ ਵਿਚ ਰੋਣ-ਧੋਣ ਕਰਨਗੇ। 11:106
- ਉਹ ਉੱਥੇ ਓਨਾ ਸਮਾਂ ਰਹਿਣਗੇ ਜਿੰਨਾ ਆਕਾਸ਼ ਅਤੇ ਧਰਤੀ ਰਹਿਣਗੇ, ਸਿਵਾਏ ਜੋ ਤੁਹਾਡਾ ਰੱਬ ਚਾਹੇ। ਯਕੀਨਨ, ਤੁਹਾਡਾ ਰੱਬ ਉਹ ਕਰ ਸਕਦਾ ਹੈ ਜੋ ਉਹ ਚਾਹੁੰਦਾ ਹੈ। 11:107
- ਅਤੇ ਜਿਹੜੇ ਖੁਸ਼ਕਿਸਮਤ ਹਨ, ਉਹ ਜਨਤ ਵਿਚ ਹੋਣਗੇ, ਉੱਥੇ ਓਨਾ ਸਮਾਂ ਰਹਿਣਗੇ ਜਿੰਨਾ ਆਕਾਸ਼ ਅਤੇ ਧਰਤੀ ਰਹਿਣਗੇ, ਸਿਵਾਏ ਜੋ ਤੁਹਾਡਾ ਰੱਬ ਚਾਹੇ, ਇਹ ਇੱਕ ਬੇਅੰਤ ਦਾਤ ਹੈ। 11:108
- ਜ਼ਾਲਮਾਂ ਵੱਲ ਝੁਕਾਓ ਨਾ, ਕਿਤੇ ਅਜਿਹਾ ਨਾ ਹੋਵੇ ਕਿ ਅੱਗ ਤੁਹਾਨੂੰ ਛੂਹ ਲਵੇ, ਅਤੇ ਤੁਹਾਡਾ ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਕੋਈ ਸਰਪ੍ਰਸਤ ਨਾ ਹੋਵੇ, ਅਤੇ ਨਾ ਹੀ ਤੁਹਾਡੀ ਮਦਦ ਕੀਤੀ ਜਾਵੇ। 11:113
- ਦਿਨ ਦੇ ਦੋ ਸਿਰਿਆਂ 'ਤੇ ਅਤੇ ਰਾਤ ਦੇ ਕੁਝ ਘੰਟਿਆਂ ਵਿਚ ਨਮਾਜ਼ ਕਾਇਮ ਕਰੋ (ਭਾਵ, 5 ਵਾਰ ਦੀ ਨਮਾਜ਼)। ਚੰਗੇ ਕੰਮ ਬੁਰਾਈਆਂ (ਛੋਟੇ ਗੁਨਾਹਾਂ) ਨੂੰ ਮਿਟਾ ਦਿੰਦੇ ਹਨ। 11:114
- ਆਕਾਸ਼ਾਂ ਅਤੇ ਧਰਤੀ ਦਾ ਅਲੋਪ ਜਾਣਨਾ ਅੱਲ੍ਹਾ ਲਈ ਹੈ, ਅਤੇ ਸਾਰੇ ਮਾਮਲੇ ਉਸ ਵੱਲ ਮੁੜਦੇ ਹਨ (ਫੈਸਲੇ ਲਈ)। 11:123
- ਹੁਕਮ (ਜਾਂ ਫੈਸਲਾ) ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਕਿਸੇ ਦਾ ਨਹੀਂ। ਉਸ ਨੇ ਹੁਕਮ ਦਿੱਤਾ ਹੈ ਕਿ ਤੁਸੀਂ ਉਸ ਤੋਂ ਇਲਾਵਾ ਕਿਸੇ ਦੀ ਇਬਾਦਤ ਨਾ ਕਰੋ (ਭਾਵ, ਇੱਕਤੌਹੀਦ), ਇਹ ਸਿੱਧਾ ਧਰਮ ਹੈ, ਪਰ ਬਹੁਤੇ ਲੋਕ ਨਹੀਂ ਜਾਣਦੇ। 12:40
- ਅੱਲ੍ਹਾ ਦੀ ਰਹਿਮਤ ਤੋਂ ਕਦੇ ਨਿਰਾਸ਼ ਨਾ ਹੋਵੋ 12:87
- ਅਤੇ ਬਹੁਤੇ ਲੋਕ ਈਮਾਨ ਨਹੀਂ ਲਿਆਉਣਗੇ, ਭਾਵੇਂ ਤੁਸੀਂ ਕਿੰਨਾ ਵੀ ਚਾਹੋ। 12:103
- ਅਤੇ ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਬਹੁਤੇ ਤਾਂ ਅੱਲ੍ਹਾ 'ਤੇ ਈਮਾਨ ਨਹੀਂ ਲਿਆਉਂਦੇ ਪਰ ਇਹ ਕਿ ਉਹ ਉਸ ਨਾਲ ਸ਼ਰੀਕ ਬਣਾਉਣ (ਭਾਵ, ਉਹ ਮੁਸ਼ਰਿਕ ਹਨ)। 12:106
- ਇਹ (ਕੁਰਆਨ) ਕੋਈ ਘੜੀ ਹੋਈ ਗੱਲ ਨਹੀਂ, ਸਗੋਂ ਇਹ ਅੱਲ੍ਹਾ ਦੀਆਂ ਪਿਛਲੀਆਂ ਕਿਤਾਬਾਂ (ਤੌਰਾਤ, ਇੰਜੀਲ ਅਤੇ ਹੋਰ ਕਿਤਾਬਾਂ) ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ, ਅਤੇ ਹਰ ਚੀਜ਼ ਦੀ ਵਿਸਥਾਰਪੂਰਵਕ ਵਿਆਖਿਆ ਹੈ, ਅਤੇ ਈਮਾਨ ਵਾਲਿਆਂ ਲਈ ਰਹਿਨੁਮਾਈ ਅਤੇ ਰਹਿਮਤ ਹੈ। 12:111
- ਅੱਲ੍ਹਾ ਜਿਸ ਲਈ ਚਾਹੁੰਦਾ ਹੈ ਰੋਜ਼ੀ ਵਧਾਉਂਦਾ ਹੈ, ਅਤੇ (ਜਿਸ ਲਈ ਚਾਹੁੰਦਾ ਹੈ) ਘਟਾਉਂਦਾ ਹੈ। 13:26
- ਅੱਲ੍ਹਾ ਨੂੰ ਅਕਸਰ ਜ਼ਿਕਰ (ਧਿਕਰ) ਨਾਲ ਯਾਦ ਕਰੋ। ਜਿਹੜੇ ਅੱਲ੍ਹਾ 'ਤੇ ਈਮਾਨ ਰੱਖਦੇ ਹਨ, ਉਨ੍ਹਾਂ ਦੇ ਦਿਲ ਉਸ ਦੇ ਜ਼ਿਕਰ ਨਾਲ ਸੰਤੁਸ਼ਟ ਹੁੰਦੇ ਹਨ। 13:28
- ਜਿਹੜੇ ਈਮਾਨ ਰੱਖਦੇ ਹਨ ਅਤੇ ਚੰਗੇ ਕੰਮ ਕਰਦੇ ਹਨ, ਉਨ੍ਹਾਂ ਨੂੰ ਖੁਸ਼ੀ ਅਤੇ ਮਾਨਸਿਕ ਸ਼ਾਂਤੀ ਮਿਲਦੀ ਹੈ। 13:29
- ਜਿਹੜੇ ਆਖ਼ਿਰਤ ਦੀ ਬਜਾਏ ਇਸ ਸੰਸਾਰ ਦੀ ਜ਼ਿੰਦਗੀ ਨੂੰ ਤਰਜੀਹ ਦਿੰਦੇ ਹਨ, ਅਤੇ ਲੋਕਾਂ ਨੂੰ ਅੱਲ੍ਹਾ ਦੇ ਰਾਹ (ਇਸਲਾਮ) ਤੋਂ ਰੋਕਦੇ ਹਨ, ਅਤੇ ਉਸ ਵਿਚ ਟੇਢ ਚਾਹੁੰਦੇ ਹਨ – ਉਹ ਬਹੁਤ ਭਟਕ ਗਏ ਹਨ। 14:3
- ਇਬਾਦਤ ਵਿਚ ਨਿਮਰਤਾ ਅਤੇ ਸ਼ੁਕਰਗੁਜ਼ਾਰੀ ਅਪਣਾਓ 14:7
- ਜਿਹੜੇ ਆਪਣੇ ਰੱਬ ਦਾ ਇਨਕਾਰ ਕਰਦੇ ਹਨ, ਉਨ੍ਹਾਂ ਦੀਆਂ ਕਿਰਤਾਂ ਦੀ ਮਿਸਾਲ ਸੁਆਹ ਵਰਗੀ ਹੈ, ਜਿਸ 'ਤੇ ਤੂਫ਼ਾਨੀ ਦਿਨ ਵਿਚ ਤੇਜ਼ ਹਵਾ ਚੱਲੇ, ਉਹ ਆਪਣੀ ਕਮਾਈ ਵਿਚੋਂ ਕੁਝ ਵੀ ਹਾਸਲ ਨਹੀਂ ਕਰ ਸਕਦੇ। 14:18
- ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਨੂੰ ਜਿਨ੍ਹਾਂ ਨੇ ਈਮਾਨ ਲਿਆਂਦਾ ਹੈ, ਇਸ ਸੰਸਾਰ ਵਿਚ (ਭਾਵ, ਉਹ ਸਿਰਫ਼ ਅੱਲ੍ਹਾ ਦੀ ਹੀ ਇਬਾਦਤ ਕਰਦੇ ਰਹਿਣਗੇ) ਅਤੇ ਆਖ਼ਿਰਤ ਵਿਚ ਦ੍ਰਿੜ ਸ਼ਬਦ ਨਾਲ ਸਥਿਰ ਰੱਖਦਾ ਹੈ। 14:27
- ਇਹ ਨਾ ਸਮਝੋ ਕਿ ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਕੰਮਾਂ ਤੋਂ ਬੇਖਬਰ ਹੈ ਜੋ ਜ਼ਾਲਮ (ਮੁਸ਼ਰਿਕ, ਜ਼ਾਲਮ ਆਦਿ) ਕਰਦੇ ਹਨ, ਪਰ ਉਹ ਉਨ੍ਹਾਂ ਨੂੰ ਉਸ ਦਿਨ ਤੱਕ ਮੌਹਲਤ ਦਿੰਦਾ ਹੈ ਜਦੋਂ ਅੱਖਾਂ ਡਰ ਨਾਲ ਖੁੱਲ੍ਹੀਆਂ ਰਹਿ ਜਾਣਗੀਆਂ। 14:42
- ਤਾਂ ਜੋ ਅੱਲ੍ਹਾ ਹਰੇਕ ਵਿਅਕਤੀ ਨੂੰ ਉਸ ਦੀ ਕਮਾਈ ਦਾ ਬਦਲਾ ਦੇਵੇ। ਯਕੀਨਨ, ਅੱਲ੍ਹਾ ਹਿਸਾਬ ਲੈਣ ਵਿਚ ਤੇਜ਼ ਹੈ। 14:51
- ਅਤੇ ਯਕੀਨਨ, ਅਸੀਂ ਮਨੁੱਖ ਨੂੰ ਖੁਸ਼ਕ ਮਿੱਟੀ ਵਿੱਚੋਂ, ਰੂਪ-ਬਦਲੀ ਹੋਈ ਕਾਲੀ ਚਿਕਨੀ ਮਿੱਟੀ ਵਿੱਚੋਂ ਪੈਦਾ ਕੀਤਾ। 15:26
- ਅਤੇ ਜਿਨ੍ਹਾਂ ਨੂੰ ਅਸੀਂ ਇਸ ਤੋਂ ਪਹਿਲਾਂ ਅੱਗ ਦੀ ਤੇਜ਼ ਲੌਂਟ (ਬਿਨਾਂ ਧੂੰਏਂ) ਵਿੱਚੋਂ ਪੈਦਾ ਕੀਤਾ। 15:27
- ਉਸ (ਜਹੰਨਮ) ਦੇ ਸੱਤ ਦਰਵਾਜ਼ੇ ਹਨ; ਹਰੇਕ ਦਰਵਾਜ਼ੇ ਲਈ ਗੁਨਾਹਗਾਰਾਂ ਦਾ ਇੱਕ (ਖਾਸ) ਸਮੂਹ ਮੁਕੱਰਰ ਹੈ। 15:44
- ਉਸ ਨੇ ਮਨੁੱਖ ਨੂੰ ਨੁਤਫ਼ੇ (ਮਰਦ ਅਤੇ ਔਰਤ ਦੇ ਵੀਰਜ ਦੀਆਂ ਰਲੀਆਂ ਬੂੰਦਾਂ) ਵਿੱਚੋਂ ਪੈਦਾ ਕੀਤਾ, ਫਿਰ ਵੇਖੋ, ਇਹੀ (ਮਨੁੱਖ) ਖੁੱਲ੍ਹਾ ਵਿਰੋਧੀ ਬਣ ਜਾਂਦਾ ਹੈ। 16:4
- ਅਤੇ ਢੋਰ-ਪਸ਼ੂ, ਉਸ ਨੇ ਉਹ ਤੁਹਾਡੇ ਲਈ ਪੈਦਾ ਕੀਤੇ; ਉਨ੍ਹਾਂ ਵਿਚ ਤੁਹਾਡੇ ਲਈ ਗਰਮੀ (ਗਰਮ ਕੱਪੜੇ), ਅਤੇ ਬਹੁਤ ਸਾਰੇ ਫ਼ਾਇਦੇ ਹਨ, ਅਤੇ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਵਿੱਚੋਂ ਖਾਂਦੇ ਹੋ। 16:5
- ਅਤੇ (ਉਸ ਨੇ) ਘੋੜੇ, ਖਚਰ ਅਤੇ ਗਧੇ (ਪੈਦਾ ਕੀਤੇ), ਤਾਂ ਜੋ ਤੁਸੀਂ ਉਨ੍ਹਾਂ 'ਤੇ ਸਵਾਰ ਹੋਵੋ ਅਤੇ ਸ਼ਾਨ-ਸ਼ੌਕਤ ਦੇ ਤੌਰ 'ਤੇ ਵੀ। ਅਤੇ ਉਹ ਅਜਿਹੀਆਂ ਚੀਜ਼ਾਂ ਪੈਦਾ ਕਰਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਬਾਰੇ ਤੁਹਾਨੂੰ ਕੁਝ ਨਹੀਂ ਪਤਾ। 16:8
- ਉਹ ਹੈ ਜਿਸ ਨੇ ਅਕਾਸ਼ ਤੋਂ ਪਾਣੀ (ਮੀਂਹ) ਵਰਸਾਇਆ; ਉਸ ਵਿੱਚੋਂ ਤੁਸੀਂ ਪੀਂਦੇ ਹੋ ਅਤੇ ਉਸ ਵਿੱਚੋਂ ਉਹ ਬੂਟੀ ਉੱਗਦੀ ਹੈ ਜਿਸ 'ਤੇ ਤੁਸੀਂ ਆਪਣੇ ਢੋਰਾਂ ਨੂੰ ਚੇਰਦੇ ਹੋ। 16:10
- ਉਹ ਹੈ ਜਿਸ ਨੇ ਸਮੁੰਦਰ ਨੂੰ (ਤੁਹਾਡੇ) ਵੱਸ ਵਿਚ ਕੀਤਾ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਉਸ ਵਿੱਚੋਂ ਤਾਜ਼ਾ ਨਰਮ ਮਾਸ (ਭਾਵ, ਮੱਛੀ) ਖਾਓ, ਅਤੇ ਉਸ ਵਿੱਚੋਂ ਗਹਿਣੇ ਕੱਢੋ ਜੋ ਤੁਸੀਂ ਪਾਉਂਦੇ ਹੋ। 16:14
- ਉਸ ਨੇ ਧਰਤੀ ਵਿਚ ਪਹਾੜ ਗੱਡ ਦਿੱਤੇ, ਤਾਂ ਜੋ ਉਹ ਤੁਹਾਨੂੰ ਲੈ ਕੇ ਡੋਲੇ ਨਾ, ਅਤੇ ਨਦੀਆਂ ਅਤੇ ਰਸਤੇ (ਬਣਾਏ), ਤਾਂ ਜੋ ਤੁਸੀਂ ਰਾਹ ਪਾ ਸਕੋ। 16:15
- ਕੀ ਫਿਰ ਉਹ ਜੋ ਪੈਦਾ ਕਰਦਾ ਹੈ, ਉਸ ਵਰਗਾ ਹੈ ਜੋ ਪੈਦਾ ਨਹੀਂ ਕਰਦਾ? ਕੀ ਤੁਸੀਂ ਫਿਰ ਧਿਆਨ ਨਹੀਂ ਦੇਵੋਗੇ? 16:17
- ਜੇਕਰ ਤੁਸੀਂ ਅੱਲ੍ਹਾ ਦੀਆਂ ਨਿਅਮਤਾਂ ਨੂੰ ਗਿਣਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਤਾਂ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਗਿਣ ਨਹੀਂ ਸਕਦੇ। 16:18
- ਅੱਲ੍ਹਾ ਜਾਣਦਾ ਹੈ ਜੋ ਤੁਸੀਂ ਛੁਪਾਉਂਦੇ ਹੋ ਅਤੇ ਜੋ ਤੁਸੀਂ ਪ੍ਰਗਟ ਕਰਦੇ ਹੋ। 16:19
- ਜਿਨ੍ਹਾਂ (ਪੂਜਣਯੋਗਾਂ) ਨੂੰ ਉਹ (ਮੁਸ਼ਰਿਕ) ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਪੁਕਾਰਦੇ ਹਨ, ਉਨ੍ਹਾਂ ਨੇ ਕੁਝ ਵੀ ਪੈਦਾ ਨਹੀਂ ਕੀਤਾ, ਸਗੋਂ ਉਹ ਆਪ ਪੈਦਾ ਕੀਤੇ ਗਏ ਹਨ। 16:20
- (ਉਹ) ਮੁਰਦਾ, ਬੇਜਾਨ ਹਨ, ਅਤੇ ਉਹ ਨਹੀਂ ਜਾਣਦੇ ਕਿ ਉਹ ਕਦੋਂ ਉਠਾਏ ਜਾਣਗੇ। 16:21
- ਜਦੋਂ ਅਸੀਂ ਕਿਸੇ ਚੀਜ਼ ਦਾ ਇਰਾਦਾ ਕਰਦੇ ਹਾਂ ਤਾਂ ਉਸ ਲਈ ਸਾਡਾ ਕਹਿਣਾ ਇਹ ਹੁੰਦਾ ਹੈ: "ਹੋ ਜਾ!" ਅਤੇ ਉਹ ਹੋ ਜਾਂਦੀ ਹੈ। 16:40
- ਕੀ ਫਿਰ ਉਹ ਜਿਹੜੇ ਬੁਰੀਆਂ ਸਾਜ਼ਿਸ਼ਾਂ ਰਚਦੇ ਹਨ, ਇਹ ਸੋਚ ਕੇ ਨਿਸਚਿੰਤ ਹੋ ਜਾਂਦੇ ਹਨ ਕਿ ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਨੂੰ ਧਰਤੀ ਵਿਚ ਧੰਸਾ ਨਹੀਂ ਦੇਵੇਗਾ, ਜਾਂ ਉਨ੍ਹਾਂ 'ਤੇ ਅਜ਼ਾਬ ਅਜਿਹੀ ਦਿਸ਼ਾ ਤੋਂ ਨਹੀਂ ਆਵੇਗਾ ਜਿਸ ਦਾ ਉਨ੍ਹਾਂ ਨੂੰ ਖਿਆਲ ਵੀ ਨਾ ਹੋਵੇ? 16:45
- ਤੁਹਾਡੇ ਕੋਲ ਜੋ ਵੀ ਨਿਅਮਤਾਂ ਅਤੇ ਚੰਗੀਆਂ ਚੀਜ਼ਾਂ ਹਨ, ਉਹ ਅੱਲ੍ਹਾ ਵੱਲੋਂ ਹਨ। ਫਿਰ ਜਦੋਂ ਤੁਹਾਨੂੰ ਤਕਲੀਫ਼ ਪਹੁੰਚਦੀ ਹੈ, ਤਾਂ ਤੁਸੀਂ ਉਸ ਨੂੰ ਉੱਚੀ ਅਵਾਜ਼ ਨਾਲ ਪੁਕਾਰਦੇ ਹੋ। 16:53
- ਫਿਰ, ਜਦੋਂ ਉਹ ਤੁਹਾਡੇ ਤੋਂ ਤਕਲੀਫ਼ ਦੂਰ ਕਰ ਦਿੰਦਾ ਹੈ, ਤਾਂ ਵੇਖੋ! ਤੁਹਾਡੇ ਵਿਚੋਂ ਕੁਝ ਆਪਣੇ ਰੱਬ ਨਾਲ (ਦੂਜਿਆਂ ਨੂੰ) ਇਬਾਦਤ ਵਿਚ ਸ਼ਰੀਕ ਕਰਦੇ ਹਨ। 16:54
- ਢੋਰ-ਪਸ਼ੂਆਂ ਵਿਚ ਤੁਹਾਡੇ ਲਈ ਇੱਕ ਸਬਕ ਹੈ। ਅਸੀਂ ਤੁਹਾਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਢਿੱਡਾਂ ਵਿੱਚੋਂ, ਗੋਹ ਅਤੇ ਖੂਨ ਦੇ ਵਿਚਕਾਰੋਂ, ਸ਼ੁੱਧ ਦੁੱਧ ਪਿਲਾਉਂਦੇ ਹਾਂ, ਜੋ ਪੀਣ ਵਾਲਿਆਂ ਨੂੰ ਚੰਗਾ ਲੱਗਦਾ ਹੈ। 16:66
- ਇਸ ਲਈ ਅੱਲ੍ਹਾ ਲਈ ਮਿਸਾਲਾਂ ਨਾ ਘੜੋ (ਕਿਉਂਕਿ ਉਸ ਵਰਗਾ ਕੁਝ ਨਹੀਂ, ਨਾ ਉਹ ਕਿਸੇ ਵਰਗਾ ਹੈ)। ਯਕੀਨਨ, ਅੱਲ੍ਹਾ ਜਾਣਦਾ ਹੈ ਅਤੇ ਤੁਸੀਂ ਨਹੀਂ ਜਾਣਦੇ। 16:74
- ਜਾਣੋ ਕਿ ਅੱਲ੍ਹਾ ਨੇ ਮਨੁੱਖ ਨੂੰ ਸੁਣਨ, ਵੇਖਣ, ਬੁੱਧ ਅਤੇ ਜਜ਼ਬਾਤ ਦਿੱਤੇ ਤਾਂ ਜੋ ਉਹ ਸ਼ੁਕਰਗੁਜ਼ਾਰ ਬਣੇ 16:78
- ਲਾਲਚ ਅਤੇ ਤਮਾ ਤੋਂ ਬਚੋ 16:97
- ਜਦੋਂ ਤੁਸੀਂ ਕੁਰਆਨ ਪੜ੍ਹਨਾ ਚਾਹੋ, ਤਾਂ ਸ਼ੈਤਾਨ, ਜੋ ਕੱਢਿਆ ਹੋਇਆ (ਲਾਅਨਤੀ) ਹੈ, ਤੋਂ ਅੱਲ੍ਹਾ ਦੀ ਪਨਾਹ ਮੰਗੋ। 16:98
- ਜਾਣੋ ਕਿ ਅਗਿਆਨਤਾ ਵਿਚ ਕੀਤਾ ਗਿਆ ਕੋਈ ਜ਼ੁਲਮ ਮਾਫ਼ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਜੇਕਰ ਵਿਅਕਤੀ ਤੌਬਾ ਕਰੇ ਅਤੇ ਆਪਣੇ ਆਪ ਨੂੰ ਸੁਧਾਰੇ। 16:119
- (ਐ ਮੁਹੰਮਦ ﷺ) ਆਪਣੇ ਰੱਬ ਦੇ ਰਾਹ (ਇਸਲਾਮ) ਵੱਲ ਬੁੱਧੀ ਅਤੇ ਚੰਗੀ ਨਸੀਹਤ ਨਾਲ ਬੁਲਾਓ, ਅਤੇ ਉਨ੍ਹਾਂ ਨਾਲ ਉਸ ਤਰੀਕੇ ਨਾਲ ਬਹਿਸ ਕਰੋ ਜੋ ਉੱਤਮ ਹੈ। ਲੋਕਾਂ ਨੂੰ ਅੱਲ੍ਹਾ ਦੇ ਰਾਹ ਵੱਲ ਬੁਲਾਉਣਾ ਬੁੱਧੀ ਅਤੇ ਨਿਮਰਤਾ ਨਾਲ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ। 16:125
- ਯਕੀਨਨ, ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਨਾਲ ਹੈ ਜੋ ਉਸ ਤੋਂ ਡਰਦੇ ਹਨ (ਆਪਣਾ ਫ਼ਰਜ਼ ਨਿਭਾਉਂਦੇ ਹਨ) ਅਤੇ ਉਨ੍ਹਾਂ ਨਾਲ ਜੋ ਨੇਕੀ ਕਰਨ ਵਾਲੇ (ਮੁਹਸਿਨ) ਹਨ। 16:128
- ਇਹ ਕੁਰਆਨ ਉਸ (ਰਾਹ) ਵੱਲ ਰਹਿਨੁਮਾਈ ਕਰਦਾ ਹੈ ਜੋ ਸਭ ਤੋਂ ਵੱਧ ਨਿਆਂਯੁਕਤ ਅਤੇ ਸਿੱਧਾ ਹੈ। 17:9
- ਕੋਈ ਵੀ ਦੂਜੇ ਦੇ ਗੁਨਾਹਾਂ ਦਾ ਬੋਝ ਨਹੀਂ ਚੁੱਕੇਗਾ। 17:15
- ਜਿਹੜਾ ਆਖ਼ਿਰਤ ਚਾਹੁੰਦਾ ਹੈ ਅਤੇ ਉਸ ਲਈ, ਜਦੋਂ ਕਿ ਉਹ ਮੋਮਿਨ ਹੈ, ਜਿੰਨੀ ਯਤਨ ਕਰਨ ਦੀ ਲੋੜ ਹੈ, ਕਰਦਾ ਹੈ, ਤਾਂ ਅਜਿਹੇ ਲੋਕਾਂ ਦੀ ਕੋਸ਼ਿਸ਼ ਨੂੰ (ਅੱਲ੍ਹਾ ਵੱਲੋਂ) ਮੰਨਿਆ ਜਾਵੇਗਾ, ਧੰਨਵਾਦ ਕੀਤਾ ਜਾਵੇਗਾ ਅਤੇ ਬਦਲਾ ਦਿੱਤਾ ਜਾਵੇਗਾ। 17:19
- ਆਪਣੇ ਮਾਤਾ-ਪਿਤਾ ਦਾ ਆਦਰ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਨਾਲ ਨਿਮਰਤਾ ਨਾਲ ਪੇਸ਼ ਆਓ। ਮਾਤਾ-ਪਿਤਾ ਨਾਲ ਨੇਕੀ ਕਰੋ। ਉਨ੍ਹਾਂ ਨੂੰ ਅਣਸੁਣੇ ਸ਼ਬਦ ਨਾ ਕਹੋ। ਅਤੇ ਤੁਹਾਡੇ ਰੱਬ ਨੇ ਹੁਕਮ ਦਿੱਤਾ ਹੈ ਕਿ ਤੁਸੀਂ ਉਸ ਤੋਂ ਇਲਾਵਾ ਕਿਸੇ ਦੀ ਇਬਾਦਤ ਨਾ ਕਰੋ। ਅਤੇ ਇਹ ਕਿ ਤੁਸੀਂ ਆਪਣੇ ਮਾਤਾ-ਪਿਤਾ ਨਾਲ ਨੇਕੀ ਕਰੋ। ਜੇਕਰ ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਇਕ ਜਾਂ ਦੋਵੇਂ ਤੁਹਾਡੇ ਜੀਉਂਦੇ ਵੇਲੇ ਬੁਢਾਪੇ ਨੂੰ ਪਹੁੰਚਣ, ਤਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਅਣਸੁਣਾ ਸ਼ਬਦ ਨਾ ਕਹੋ, ਨਾ ਉਨ੍ਹਾਂ 'ਤੇ ਚਿੱਲਾਓ, ਸਗੋਂ ਉਨ੍ਹਾਂ ਨਾਲ ਸਤਿਕਾਰ ਨਾਲ ਗੱਲ ਕਰੋ। 17:23
- ਅਤੇ ਉਨ੍ਹਾਂ ਲਈ ਨਿਮਰਤਾ ਅਤੇ ਦਇਆ ਨਾਲ ਆਪਣਾ ਪਰ ਨਿਮਰ ਕਰੋ, ਅਤੇ ਕਹੋ: "ਮੇਰੇ ਰੱਬ! ਉਨ੍ਹਾਂ 'ਤੇ ਰਹਿਮ ਕਰ ਜਿਵੇਂ ਉਨ੍ਹਾਂ ਨੇ ਮੈਨੂੰ ਛੋਟੀ ਉਮਰ ਵਿਚ ਪਾਲਿਆ ਸੀ।" 17:24
- ਯਕੀਨਨ, ਫ਼ਜ਼ੂਲਖ਼ਰਚ ਕਰਨ ਵਾਲੇ ਸ਼ੈਤਾਨਾਂ ਦੇ ਭਰਾ ਹਨ, ਅਤੇ ਸ਼ੈਤਾਨ ਆਪਣੇ ਰੱਬ ਦਾ ਬਹੁਤ ਨਾਸ਼ੁਕਰਾ ਹੈ। 17:27
- ਪੈਸਾ ਫ਼ਜ਼ੂਲ ਖ਼ਰਚ ਨਾ ਕਰੋ 17:29
- ਆਪਣੇ ਬੱਚਿਆਂ ਨੂੰ ਗ਼ਰੀਬੀ ਦੇ ਡਰੋਂ ਕਤਲ ਨਾ ਕਰੋ 17:31
- ਵਿਭਚਾਰ ਨਾ ਕਰੋ। ਵਿਆਹ ਦੀ ਪਵਿੱਤਰਤਾ ਬਣਾਈ ਰੱਖੋ ਅਤੇ ਵਿਭਚਾਰ ਤੋਂ ਬਚੋ 17:32
- ਜਦੋਂ ਤੁਸੀਂ ਨਾਪ ਕਰੋ ਤਾਂ ਪੂਰਾ ਨਾਪ ਕਰੋ, ਅਤੇ ਸਿੱਧੇ ਤਰਾਜ਼ੂ ਨਾਲ ਤੋਲ ਕਰੋ। ਇਹ ਚੰਗਾ (ਲਾਭਦਾਇਕ) ਅਤੇ ਅੰਤ ਵਿਚ ਉੱਤਮ ਹੈ। 17:35
- (ਐ ਮਨੁੱਖ!) ਜਿਸ ਚੀਜ਼ ਦਾ ਤੁਹਾਨੂੰ ਗਿਆਨ ਨਹੀਂ, ਉਸ ਦੀ ਪਾਲਣਾ ਨਾ ਕਰੋ (ਜਿਵੇਂ, ਕੋਈ ਕਹੇ: "ਮੈਂ ਵੇਖਿਆ ਹੈ," ਜਦੋਂ ਕਿ ਉਸ ਨੇ ਨਹੀਂ ਵੇਖਿਆ, ਜਾਂ "ਮੈਂ ਸੁਣਿਆ ਹੈ," ਜਦੋਂ ਕਿ ਉਸ ਨੇ ਨਹੀਂ ਸੁਣਿਆ)। 17:36
- ਨਿਮਰ ਬਣੋ ਅਤੇ ਮਾਣ ਨਾ ਕਰੋ। ਧਰਤੀ 'ਤੇ ਮਾਣ ਅਤੇ ਅਕੜ ਨਾਲ ਨਾ ਚੱਲੋ। ਯਕੀਨਨ, ਤੁਸੀਂ ਨਾ ਤਾਂ ਧਰਤੀ ਨੂੰ ਪਾੜ ਸਕਦੇ ਹੋ ਅਤੇ ਨਾ ਹੀ ਪਹਾੜਾਂ ਦੀ ਉਚਾਈ ਤੱਕ ਪਹੁੰਚ ਸਕਦੇ ਹੋ। 17:37
- ਤੁਹਾਡਾ ਰੱਬ ਤੁਹਾਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਜਾਣਦਾ ਹੈ, ਜੇਕਰ ਉਹ ਚਾਹੇ ਤਾਂ ਤੁਹਾਡੇ 'ਤੇ ਰਹਿਮ ਕਰੇ, ਜਾਂ ਜੇਕਰ ਚਾਹੇ ਤਾਂ ਤੁਹਾਨੂੰ ਸਜ਼ਾ ਦੇਵੇ। 17:54
- ਜਿਹੜਾ ਇਸ ਸੰਸਾਰ ਵਿਚ ਅੰਨ੍ਹਾ ਰਿਹਾ (ਭਾਵ, ਉਸ ਨੇ ਅੱਲ੍ਹਾ ਦੀਆਂ ਨਿਸ਼ਾਨੀਆਂ ਨਹੀਂ ਵੇਖੀਆਂ ਅਤੇ ਉਸ 'ਤੇ ਈਮਾਨ ਨਹੀਂ ਲਿਆਇਆ), ਉਹ ਆਖ਼ਿਰਤ ਵਿਚ ਵੀ ਅੰਨ੍ਹਾ ਹੋਵੇਗਾ, ਅਤੇ ਰਾਹ ਤੋਂ ਵੀ ਵੱਧ ਭਟਕਿਆ ਹੋਇਆ। 17:72
- ਨਮਾਜ਼ ਦੇ ਮੁਕੱਰਰ ਸਮੇਂ ਦਾ ਧਿਆਨ ਰੱਖੋ 17:78
- ਯਕੀਨਨ ਅਸੀਂ ਇਸ ਕੁਰਆਨ ਵਿਚ ਲੋਕਾਂ ਲਈ ਹਰ ਤਰ੍ਹਾਂ ਦੀਆਂ ਮਿਸਾਲਾਂ ਬਿਆਨ ਕਰ ਦਿੱਤੀਆਂ ਹਨ, ਪਰ ਬਹੁਤੇ ਲੋਕ (ਸੱਚ ਨੂੰ ਮੰਨਣ ਤੋਂ) ਇਨਕਾਰ ਕਰਦੇ ਹਨ ਅਤੇ ਕੁਫ਼ਰ ਤੋਂ ਬਿਨਾਂ ਨਹੀਂ ਰਹਿਣਾ ਚਾਹੁੰਦੇ। 17:89
- ਅਸੀਂ ਇਸ ਕੁਰਆਨ ਵਿਚ ਲੋਕਾਂ ਲਈ ਹਰ ਤਰ੍ਹਾਂ ਦੀਆਂ ਮਿਸਾਲਾਂ ਬਿਆਨ ਕਰ ਦਿੱਤੀਆਂ ਹਨ। ਪਰ ਮਨੁੱਖ ਕਿਸੇ ਵੀ ਚੀਜ਼ ਨਾਲੋਂ ਵੱਧ ਝਗੜਾਲੂ ਹੈ। 18:54
- ਉਨ੍ਹਾਂ ਦਾ ਬਦਲਾ ਜਹੰਨਮ ਹੈ, ਕਿਉਂਕਿ ਉਨ੍ਹਾਂ ਨੇ ਇਨਕਾਰ ਕੀਤਾ ਅਤੇ ਮੇਰੀਆਂ ਆਇਤਾਂ ਅਤੇ ਮੇਰੇ ਰਸੂਲਾਂ ਨੂੰ ਮਖੌਲ ਅਤੇ ਮਸ਼ਕਰੀ ਬਣਾਇਆ। 18:106
- ਅੱਲ੍ਹਾ ਦੀ ਸ਼ਾਨ ਇਸ ਗੱਲ ਤੋਂ ਉੱਚੀ ਹੈ ਕਿ ਉਹ ਕਿਸੇ ਨੂੰ ਆਪਣਾ ਪੁੱਤਰ ਬਣਾਏ (ਇਹ ਈਸਾਈਆਂ ਦੀ ਉਸ ਤੁਹਮਤ ਵੱਲ ਇਸ਼ਾਰਾ ਹੈ ਜੋ ਉਹ ਅੱਲ੍ਹਾ 'ਤੇ ਲਗਾਉਂਦੇ ਹਨ ਕਿ 'ਈਸਾ (ਯੀਸੂ) ਅੱਲ੍ਹਾ ਦਾ ਪੁੱਤਰ ਹੈ)। ਉਹ ਪਵਿੱਤਰ ਹੈ (ਅਤੇ ਉਨ੍ਹਾਂ ਸਭ ਤੋਂ ਉੱਚਾ ਹੈ ਜੋ ਉਹ ਉਸ ਨਾਲ ਸ਼ਰੀਕ ਕਰਦੇ ਹਨ)। 19:35
- ਲੋਕਾਂ ਨਾਲ ਨਰਮਾਈ ਨਾਲ ਗੱਲ ਕਰੋ 20:44
- ਭਲਾਈ ਕਰਨ ਵਿਚ ਇਕ-ਦੂਜੇ ਨਾਲ ਮੁਕਾਬਲਾ ਕਰੋ 21:90
- ਬੇਕਾਰ ਗੱਲਾਂ ਤੋਂ ਬਚੋ 23:3
- ਆਪਣੀ ਲੱਜਾ ਦੀ ਰੱਖਿਆ ਕਰੋ 23:5
- ਆਪਣੇ ਦਿਲ ਨੂੰ ਗੁਨਾਹਾਂ ਵੱਲ ਝੁਕਾਅ ਤੋਂ ਬਚਾਓ 23:97
- ਦੂਜਿਆਂ ਨੂੰ ਮਾਫ਼ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀਆਂ ਕਮੀਆਂ ਨੂੰ ਅੱਖੋਂ ਪਰੋਖੇ ਕਰੋ 24:22
- ਦੂਜੇ ਲੋਕਾਂ ਦੀ ਗੋਪਨੀਯਤਾ ਦਾ ਆਦਰ ਕਰੋ, ਖਾਸ ਕਰਕੇ ਉਨ੍ਹਾਂ ਦੇ ਆਪਣੇ ਘਰਾਂ ਵਿਚ। ਗੁਆਂਢੀਆਂ ਦੇ ਅਧਿਕਾਰਾਂ ਨੂੰ ਨਿਭਾਓ 24:27
- (ਮਰਦ ਅਤੇ ਔਰਤਾਂ ਦੋਵਾਂ) ਲਈ ਆਪਣੀ ਨਿਗਾਹ ਨੀਵੀਂ ਰੱਖੋ। ਆਪਣੀ ਲੱਜਾ ਅਤੇ ਪਵਿੱਤਰਤਾ ਦੀ ਰੱਖਿਆ ਕਰੋ। 24:30
- ਪਹਿਰਾਵੇ ਅਤੇ ਵਿਹਾਰ ਵਿਚ ਲੱਜਾ ਦਾ ਧਿਆਨ ਰੱਖੋ 24:31
- ਜਾਣੋ ਕਿ ਅੱਲ੍ਹਾ ਉਨ੍ਹਾਂ ਲਈ ਰੱਖਿਆ ਅਤੇ ਸ਼ਾਂਤੀ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ ਜੋ ਉਸ ਦੀ ਇਬਾਦਤ ਕਰਦੇ ਹਨ ਅਤੇ ਨੇਕ ਕੰਮ ਕਰਦੇ ਹਨ 24:55
- ਮਾਤਾ-ਪਿਤਾ ਦੇ ਨਿੱਜੀ ਕਮਰੇ ਵਿਚ ਉਨ੍ਹਾਂ ਦੀ ਇਜਾਜ਼ਤ ਤੋਂ ਬਿਨਾਂ ਨਾ ਦਾਖ਼ਲ ਹੋਵੋ 24:58
- ਨਿਮਰ ਅਤੇ ਮਾਮੂਲੀ ਬਣੋ 25:63
- ਝੂਠੀ ਗਵਾਹੀ ਅਤੇ ਧੋਖੇ ਤੋਂ ਬਚੋ 25:72
- ਆਖ਼ਿਰਤ ਦੇ ਬਦਲੇ ਲਈ ਕੋਸ਼ਿਸ਼ ਕਰੋ ਪਰ ਇਸ ਸੰਸਾਰ ਦੇ ਮਾਮਲਿਆਂ ਨੂੰ ਵੀ ਨਾ ਭੁੱਲੋ 28:77
- ਅੱਲ੍ਹਾ ਤੋਂ ਇਲਾਵਾ ਕਿਸੇ ਹੋਰ ਨੂੰ ਨਾ ਪੁਕਾਰੋ 28:88
- ਹਮਜਿਨਸੀ (ਸਮਲਿੰਗੀ) ਕਿਰਿਆ ਵਿਚ ਨਾ ਪਓ 29:29
- ਆਪਣੇ ਸਾਰੇ ਯਤਨਾਂ ਵਿਚ ਉੱਤਮਤਾ ਲਈ ਕੋਸ਼ਿਸ਼ ਕਰੋ 29:69
- ਨਮਾਜ਼ ਕਾਇਮ ਕਰੋ ਅਤੇ ਖੈਰਾਤ (ਜ਼ਕਾਤ) ਦਿਓ 31:4
- ਭਲਾਈ ਦਾ ਹੁਕਮ ਦਿਓ ਅਤੇ ਬੁਰਾਈ ਤੋਂ ਰੋਕੋ 31:17
- ਆਪਣੇ ਵਿਹਾਰ ਵਿਚ ਮਾਣ ਤੋਂ ਬਚੋ। ਬੇਕਾਰ ਗੱਲਾਂ ਵਿਚ ਸਮਾਂ ਬਰਬਾਦ ਕਰਨ ਤੋਂ ਬਚੋ 31:18
- ਆਪਣੇ ਚਾਲ-ਢੰਗ ਅਤੇ ਆਪਣੀ ਆਵਾਜ਼ ਵਿਚ ਸੰਤੁਲਨ ਰੱਖੋ 31:19
- ਨਬੀ ਮੁਹੰਮਦ (ﷺ) ਦੀ ਸੁੰਨਤ ਦੀ ਪਾਲਣਾ ਕਰੋ 33:21
- ਔਰਤਾਂ ਨੂੰ ਆਪਣੀ ਸੁੰਦਰਤਾ ਅਤੇ ਜ਼ੇਵਰ ਨੂੰ ਪ੍ਰਦਰਸ਼ਤ ਨਹੀਂ ਕਰਨਾ ਚਾਹੀਦਾ 33:33
- ਹਰ ਹਾਲਤ ਵਿਚ ਸੱਚ ਬੋਲੋ 33:70
- ਚਿੰਤਨ ਅਤੇ ਸੋਚ-ਵਿਚਾਰ ਰਾਹੀਂ ਬੁੱਧ ਅਤੇ ਸਮਝ ਪ੍ਰਾਪਤ ਕਰੋ 38:29
- ਕੁਰਆਨ ਦੇ ਹੁਕਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰੋ 39:23
- ਅੱਲ੍ਹਾ ਸਾਰੇ ਗੁਨਾਹਾਂ ਨੂੰ ਮਾਫ਼ ਕਰ ਦਿੰਦਾ ਹੈ ਜਦੋਂ ਗੁਨਾਹਗਾਰ ਤੌਬਾ ਕਰਦਾ ਹੈ ਅਤੇ ਉਸ ਵੱਲ ਮੁੜਦਾ ਹੈ 39:53
- ਅੱਲ੍ਹਾ ਨੂੰ ਖੁੱਲ੍ਹੇ ਦਿਲ ਨਾਲ ਦੁਆ (ਸਪੁਰਦਗੀ) ਕਰੋ 40:60
- ਬੁਰਾਈ ਨੂੰ ਚੰਗੀ ਚੀਜ਼ ਨਾਲ ਦੂਰ ਕਰੋ 41:34
- ਮਾਮਲਿਆਂ ਨੂੰ ਸਲਾਹ-ਮਸ਼ਵਰੇ ਨਾਲ ਤੈਅ ਕਰੋ 42:38
- ਆਪਣੀ ਆਵਾਜ਼ ਨਬੀ ਦੀ ਆਵਾਜ਼ ਤੋਂ ਉੱਚੀ ਨਾ ਕਰੋ 49:2
- ਰਾਜ਼ ਰੱਖੋ ਅਤੇ ਧੋਖੇ ਤੋਂ ਬਚੋ 49:6
- ਝਗੜਾ ਕਰਨ ਵਾਲਿਆਂ ਵਿਚ ਸੁਲ੍ਹਾ ਕਰਾਓ। ਝਗੜਿਆਂ ਵਿਚ ਸੁਲ੍ਹਾ ਕਰਾਉਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰੋ 49:9
- ਦੂਜਿਆਂ ਦਾ ਮਖੌਲ ਨਾ ਉਡਾਓ 49:11
